class _UnhandledExceptionMiddleware(BaseHTTPMiddleware):
    """Real fix Aug 28: any genuinely unhandled exception (a real backend crash, e.g. the
    admin_settings primary-key bug found the same day) previously reached the client as
    Starlette's bare default 500 page — which carries NO CORS headers, because it's
    generated by ServerErrorMiddleware, outside CORSMiddleware's response-wrapping. Every
    browser then reports this as a CORS error ("blocked by CORS policy"), masking the real
    500 and the real error message, which is genuinely misleading to debug from the frontend
    console. First attempt at this fix used @app.exception_handler(Exception) instead of a
    real middleware - live-verified WRONG: Starlette hoists a bare-Exception handler onto
    ServerErrorMiddleware itself, which is outermost, still outside CORSMiddleware - the 500
    got the right JSON body but still no CORS header. A real middleware registered here,
    BEFORE app.add_middleware(CORSMiddleware) below, ends up INSIDE CORSMiddleware in the
    final stack (Starlette wraps middleware outside-in in reverse registration order) - so a
    response built here still passes back out through CORSMiddleware's header-adding wrap.
    Live-verified after this fix: same 500, now carries a real access-control-allow-origin
    header. HTTPExceptions are unaffected (FastAPI's own handler for those runs at a
    different layer and already gets CORS headers)."""
    async def dispatch(self, request: Request, call_next):
        try:
            return await call_next(request)
        except Exception as exc:
            logger.error(f"Unhandled exception on {request.method} {request.url.path}: {exc}", exc_info=True)
            return JSONResponse(status_code=500, content={"detail": "Internal server error"})

app.add_middleware(_UnhandledExceptionMiddleware)

app.add_middleware(
    CORSMiddleware,
    allow_credentials=False,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)

