# ================== AUTH HELPERS ==================
async def get_current_user(request: Request) -> Optional[dict]:
    """Get current user from Supabase session token"""
    session_token = request.cookies.get("session_token")
    if not session_token:
        auth_header = request.headers.get("Authorization")
        if auth_header and auth_header.startswith("Bearer "):
            session_token = auth_header[7:]
    if not session_token:
        # Also accept token as query param (for PDF downloads via Linking.openURL)
        session_token = request.query_params.get("token")
    if not session_token:
        return None
    try:
        result = supabase.table("user_sessions").select("*").eq("session_token", session_token).execute()
        if not result.data:
            return None
        session = result.data[0]
        expires_at = datetime.fromisoformat(session["expires_at"].replace("Z", "+00:00"))
        if expires_at < datetime.now(timezone.utc):
            return None
        user_result = supabase.table("users").select("*").eq("user_id", session["user_id"]).execute()
        if not user_result.data:
            return None
        found_user = user_result.data[0]
        # Real feature Aug 27 (item 11, account suspend/reactivate): checked here, not just
        # at login, so suspending an account kills an already-active session immediately
        # rather than waiting for it to next log in. .get() is a no-op if the account_suspended
        # column doesn't exist yet (migration pending, see POST /admin/users/{user_id}/suspend),
        # so this is safe pre-migration - every caller already treats a None return as "not
        # authenticated" with their own 401/403, same as an expired session.
        if found_user.get("account_suspended"):
            return None
        return found_user
    except Exception as e:
        logger.error(f"Auth error: {e}")
        return None

def _public_user(user: dict) -> dict:
    """CRITICAL security fix Aug 26: /auth/me, /auth/email-login, and google_auth all used to
    return the raw user row straight from the DB - including portal_password (a real bcrypt
    hash) and reset_token, sent to every client on every session check. Never caught in
    practice (bcrypt hashes aren't trivially reversible), but there's no reason to ever ship
    a password hash to a client at all. Strips both, and adds has_password - a safe boolean
    the frontend needs to force real password creation for the ~98% of real accounts that
    don't have one yet (see COH-REVIEW-PLAN.md - the account-takeover investigation this
    round). get_current_user() itself is untouched - many endpoints need the real
    portal_password internally (login's own verify_password check) - this sanitizer is only
    for the handful of endpoints that hand the user object back to the client."""
    if not user:
        return user
    safe = dict(user)
    has_password = bool(safe.get("portal_password"))
    safe.pop("portal_password", None)
    safe.pop("reset_token", None)
    safe.pop("reset_token_expires", None)
    safe["has_password"] = has_password
    return safe

def _trial_is_valid(user: dict) -> bool:
    """Real bug fix Aug 25: a promo code (POST /subscription/redeem-trial-code, e.g.
    HAPPYCLASS2026) can grant a real duration other than the standard TRIAL_DURATION_DAYS
    (30 days, not 14) - it writes that real expiry into subscription_expires_at. Every
    trial-status expiry check in this file used to ignore that entirely and always compute
    from trial_started_at + the standard 14-day TRIAL_DURATION_DAYS instead, so a promo-code
    trial silently lost its real access after only 14 of its advertised 30 days - confirmed
    across both check_subscription_active (general feature-gating) and
    _is_genuinely_free_tier (the new creature caps). subscription_expires_at is checked first
    when present (the promo-granted real value); falls back to the standard 14-day window,
    computed from trial_started_at, for a regular trial (POST /subscription/start-trial),
    which never sets subscription_expires_at at all."""
    if user.get("subscription_status") != "trial":
        return False
    exp = user.get("subscription_expires_at")
    if exp:
        return datetime.fromisoformat(exp.replace("Z", "+00:00")) > datetime.now(timezone.utc)
    start = user.get("trial_started_at")
    if start:
        return datetime.now(timezone.utc) < datetime.fromisoformat(start.replace("Z", "+00:00")) + timedelta(days=TRIAL_DURATION_DAYS)
    return False

def check_subscription_active(user: dict) -> bool:
    if not user:
        return False
    # Internal staff roles always have full access
    if user.get("role") == "superadmin":
        return True
    # The 4 permanent always-open accounts (PIN-protected at login, see ALWAYS_OPEN_PINS)
    if (user.get("email") or "").strip().lower() in ALWAYS_OPEN_PINS:
        return True
    # Covered by their school's paid plan (real column is school_admin_id — school_id doesn't exist)
    if user.get("school_admin_id") or user.get("invite_code"):
        return True
    sub_status = user.get("subscription_status", "none")
    if sub_status == "active":
        exp = user.get("subscription_expires_at")
        if exp:
            exp_dt = datetime.fromisoformat(exp.replace("Z", "+00:00"))
            return exp_dt > datetime.now(timezone.utc)
        return True
    if sub_status == "trial":
        return _trial_is_valid(user)
    return False

def _personal_sub_is_active(user: dict) -> bool:
    """Real bug fix Aug 28 (technical debt sweep): the old `subscription_status not in
    ("none","free",None)` pattern, used at 3 historical-PDF-access gates (family-all,
    teacher-wellbeing, classroom-overview) to mean "this account's OWN subscription is
    genuinely active", treated ANY non-none/free status as active - including a trial or
    paid plan that has genuinely expired (nothing ever flips subscription_status back once
    set), same root cause as the free_tier_limit checks already fixed via
    _is_genuinely_free_tier(). Deliberately NOT reusing check_subscription_active() here -
    that function intentionally also returns True on a loose school_admin_id/invite_code
    bypass, which would double up with (and isn't equivalent to) the strict
    _teacher_is_school_covered/_parent_is_school_covered check each of those 3 call sites
    already ORs in separately. This is just the real, expiry-aware personal-subscription
    fact, same active/trial logic check_subscription_active/_is_genuinely_free_tier both
    use internally."""
    sub_status = user.get("subscription_status") or "none"
    if sub_status == "active":
        exp = user.get("subscription_expires_at")
        return not exp or datetime.fromisoformat(exp.replace("Z", "+00:00")) > datetime.now(timezone.utc)
    if sub_status == "trial":
        return _trial_is_valid(user)
    return False

