# ================== STUDENTS ==================
@api_router.get("/students")
async def get_students(request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): always self-scoped by user_id (never a data leak),
    # but had no role check - any authenticated non-teacher account could hit this.
    if user.get("role") not in ("teacher", "school_admin", "superadmin"):
        raise HTTPException(status_code=403, detail="Teacher access required")

    # Get students via user_id AND via classrooms (for teachers assigned to classrooms)
    result = supabase.table("students").select("*").eq("user_id", user["user_id"]).execute()
    own_students = result.data or []
    
    # Also get students from classrooms assigned to this teacher
    classrooms_r = supabase.table("classrooms").select("id").eq("user_id", user["user_id"]).execute()
    classroom_ids = [cl["id"] for cl in (classrooms_r.data or [])]
    existing_ids = {s["id"] for s in own_students}
    if classroom_ids:
        classroom_students_r = supabase.table("students").select("*").in_("classroom_id", classroom_ids).execute()
        classroom_students = classroom_students_r.data or []
        for s in classroom_students:
            if s["id"] not in existing_ids:
                own_students.append(s)
                existing_ids.add(s["id"])
    # Also include students who have link codes generated by this teacher
    # These are students whose classroom_id belongs to this teacher's classrooms
    # but may have been created with a different user_id
    try:
        if classroom_ids:
            # Get ALL students in teacher's classrooms regardless of user_id
            all_classroom_stud_r = supabase.table("students").select("*").in_("classroom_id", classroom_ids).execute()
            for s in (all_classroom_stud_r.data or []):
                if s["id"] not in existing_ids:
                    own_students.append(s)
                    existing_ids.add(s["id"])
    except Exception as e:
        logger.warning(f"Could not fetch classroom students: {e}")
    
    own_ids = {s["id"] for s in own_students}

    # Get parent links ONLY for THIS teacher's own students
    try:
        if own_ids:
            links_result = supabase.table("parent_links").select("*").in_(
                "student_id", list(own_ids)[:50]
            ).execute()
            own_links = links_result.data or []
            linked_map = {l["student_id"]: l for l in own_links}
        else:
            linked_map = {}

        # Real bug fix Aug 23 (item 7): is_linked only ever checked parent_links - the
        # OTHER real linking path, family_members.student_id (set by
        # /family/members/{id}/link-student), was never checked here, so a student linked
        # only that way would incorrectly show as not linked. _is_authorized_for_student
        # already treats both as equally real; this now does too.
        linked_via_family_members = set()
        if own_ids:
            fm_result = supabase.table("family_members").select("student_id").in_(
                "student_id", list(own_ids)[:50]
            ).execute()
            linked_via_family_members = {f["student_id"] for f in (fm_result.data or []) if f.get("student_id")}

        # Add is_linked flag to own students only
        for s in own_students:
            link = linked_map.get(s["id"])
            s["is_linked"] = link is not None or s["id"] in linked_via_family_members
            s["home_sharing_enabled"] = link.get("home_sharing_enabled", False) if link else False
            s["parent_user_id"] = link.get("parent_user_id") if link else None

        # NOTE: We intentionally do NOT add students from other teachers here.
        # Each teacher only sees their own students. Parents can view shared data
        # through the family dashboard, not by appearing in teacher lists.

    except Exception as e:
        logger.error(f"Could not fetch link status: {e}")

    return own_students

@api_router.post("/students")
async def create_student(student: StudentCreate, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): live-confirmed exploit - a parent-role test account
    # with no role check at all was able to successfully create a student record via this
    # endpoint (200, not 403).
    if user.get("role") not in ("teacher", "school_admin", "superadmin"):
        raise HTTPException(status_code=403, detail="Teacher access required")
    # Free tier: limit to 10 students (mirrors the same real pattern already used for classrooms)
    # Real fix Aug 26 (item 4): was `subscription_status in ("none","free",None)` plus a bare
    # `bool(school_admin_id)` - blind to real expiry (a lapsed trial/paid account dodged this
    # cap forever, same root cause as the Aug 24/25 creature-cap bugs) AND to whether the
    # linked school_admin's OWN subscription was still active (bool(school_admin_id) alone
    # doesn't mean the school ever paid, or still does). _is_genuinely_free_tier() already
    # fixes both - reused here instead of copying the same two bugs into yet another check.
    if _is_genuinely_free_tier(user):
        existing = supabase.table("students").select("id", count="exact").eq("user_id", user["user_id"]).execute()
        student_count = existing.count or len(existing.data or [])
        if student_count >= 10:
            raise HTTPException(
                status_code=403,
                detail="free_tier_limit|Free plan is limited to 10 students. Upgrade to Teacher Pro for unlimited students, or ask your school to add you to their school plan."
            )
    new_student = {
        "id": str(uuid.uuid4()),
        "user_id": user["user_id"],
        "name": student.name,
        "avatar_type": student.avatar_type,
        "avatar_preset": student.avatar_preset,
        "avatar_custom": student.avatar_custom,
        "classroom_id": student.classroom_id,
        "created_at": datetime.now(timezone.utc).isoformat()
    }
    result = supabase.table("students").insert(new_student).execute()
    saved = result.data[0] if result.data else new_student

    # Auto-create creature record so student doesn't show egg on first login
    try:
        creatures_r = supabase.table("creatures").select("id").order("created_at").limit(1).execute()
        if creatures_r.data:
            first_creature_id = creatures_r.data[0]["id"]
            supabase.table("student_rewards").insert({
                "id": str(uuid.uuid4()),
                "student_id": saved["id"],
                "current_creature_id": first_creature_id,
                "current_stage": 0,
                "total_points": 0,
                "current_points": 0,
                "created_at": datetime.now(timezone.utc).isoformat(),
            }).execute()
            logger.info(f"[create_student] Auto-created creature for {saved['name']}")
    except Exception as ce:
        logger.warning(f"[create_student] Could not auto-create creature: {ce}")

    return saved

@api_router.get("/students/{student_id}")
async def get_student(student_id: str, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    result = supabase.table("students").select("*").eq("id", student_id).execute()
    if not result.data:
        raise HTTPException(status_code=404, detail="Student not found")
    # Real fix Aug 26 (security audit): had no authorization check at all - any authenticated
    # user could read any student's full record by id. Uses _is_authorized_for_student (not a
    # staff-only role check) since this is legitimately read by parent-facing screens too.
    if not await _is_authorized_for_student(user, student_id, result.data[0]):
        raise HTTPException(status_code=403, detail="Not authorized for this student")
    return result.data[0]

@api_router.put("/students/{student_id}")
async def update_student(student_id: str, update: StudentUpdate, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): had no authorization check at all - any authenticated
    # user could edit any student's record by id. Editing a student's core profile is staff
    # functionality (unlike the read above, which parent-facing screens legitimately use too).
    if user.get("role") not in ("teacher", "school_admin", "superadmin"):
        raise HTTPException(status_code=403, detail="Teacher access required")
    if not await _is_authorized_for_student(user, student_id):
        raise HTTPException(status_code=403, detail="Not authorized for this student")
    update_data = {k: v for k, v in update.dict().items() if v is not None}
    supabase.table("students").update(update_data).eq("id", student_id).execute()
    result = supabase.table("students").select("*").eq("id", student_id).execute()
    return result.data[0] if result.data else {}

@api_router.delete("/students/{student_id}")
async def delete_student(student_id: str, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): had no authorization check at all - any authenticated
    # user could permanently delete any student system-wide (and their feeling_logs/rewards)
    # by id.
    if user.get("role") not in ("teacher", "school_admin", "superadmin"):
        raise HTTPException(status_code=403, detail="Teacher access required")
    if not await _is_authorized_for_student(user, student_id):
        raise HTTPException(status_code=403, detail="Not authorized for this student")
    supabase.table("feeling_logs").delete().eq("student_id", student_id).execute()
    supabase.table("student_rewards").delete().eq("student_id", student_id).execute()
    supabase.table("students").delete().eq("id", student_id).execute()
    return {"message": "Student deleted"}

@api_router.post("/students/{student_id}/generate-link-code")
async def generate_link_code(student_id: str, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): the old comment here ("auth check above is
    # sufficient") was false - nothing tied the student to the caller, so any authenticated
    # user could mint a real link code for any student, which a parent could then use to
    # link themselves to a child that isn't theirs.
    if user.get("role") not in ("teacher", "school_admin", "superadmin"):
        raise HTTPException(status_code=403, detail="Teacher access required")
    if not await _is_authorized_for_student(user, student_id):
        raise HTTPException(status_code=403, detail="Not authorized for this student")
    link_code = str(uuid.uuid4())[:6].upper()
    expires_at = datetime.now(timezone.utc) + timedelta(days=7)
    supabase.table("students").update({
        "link_code": link_code,
        "link_code_expires_at": expires_at.isoformat()
    }).eq("id", student_id).execute()
    return {"link_code": link_code, "expires_at": expires_at.isoformat()}

