@api_router.get("/helpers")
async def get_helpers(feeling_colour: Optional[str] = None, student_id: Optional[str] = None, lang: str = "en"):
    helpers = []
    colours = [feeling_colour] if feeling_colour else FEELING_COLOURS
    # Use language-specific helper cards if available
    LANG_HELPERS = {
        "pt": HELPERS_PT, "es": HELPERS_ES, "fr": HELPERS_FR,
        "de": HELPERS_DE, "it": HELPERS_IT,
    }
    lang_helpers = LANG_HELPERS.get(lang, DEFAULT_HELPERS)
    for colour in colours:
        colour_helpers = lang_helpers.get(colour, DEFAULT_HELPERS.get(colour, []))
        helpers.extend(colour_helpers)

    # Get custom helpers for this student
    if student_id:
        try:
            custom = supabase.table("custom_helpers").select("*").eq("student_id", student_id).eq("is_active", True).execute()
            if custom.data:
                for h in custom.data:
                    if not feeling_colour or h.get("feeling_colour") == feeling_colour:
                        helpers.append(h)
        except Exception as e:
            logger.error(f"Error fetching custom helpers: {e}")

    return helpers

# ================== VOICE CLIPS (student check-in narration) ==================
# Real feature Aug 19: kids' voice recordings that play when a colour or helper button
# is tapped on the student check-in flow. No DB table - the "voice-recordings" Storage
# bucket itself is the source of truth (organised as {language}/{clip_key}.m4a), so
# uploading/replacing a clip is the only step ever needed; nothing else can drift out of
# sync with it. Missing keys (unfinished PT clips, unsupported languages) are simply
# absent from the response - the app skips playback for those, same code path either way.
VOICE_CLIP_KEYS = ["blue", "green", "yellow", "red"] + [
    f"{zone}_{n}" for zone in ("blue", "green", "yellow", "red") for n in range(1, 7)
]
VOICE_CLIP_LANGUAGES = ("en", "pt", "es", "it")  # Real feature Aug 25: it - full rollout,
# all 28 canonical clips (4 colours + 24 helpers) uploaded and live-verified, real converted
# .m4a files (confirmed by content, not extension - the originals were .opus, genuinely
# converted before upload this time). es partial rollout Aug 23: only the 4 colour
# names (blue/green/yellow/red) have real recordings so far - the 24 helpers and other
# clips don't exist yet. Safe by design: get_voice_clips only ever returns keys that
# genuinely have a file in Storage, and the frontend already no-ops silently for any
# missing key (same code path as pt's own partial rollout), so this doesn't need special
# handling - it's the same mechanism already proven for pt.

@api_router.get("/voice-clips")
async def get_voice_clips(language: str = "en"):
    if language not in VOICE_CLIP_LANGUAGES:
        return {}
    try:
        files = supabase.storage.from_("voice-recordings").list(language)
    except Exception as e:
        logger.error(f"voice-clips list error: {e}")
        return {}
    existing = {f["name"].rsplit(".", 1)[0] for f in (files or [])}
    return {
        key: supabase.storage.from_("voice-recordings").get_public_url(f"{language}/{key}.m4a")
        for key in VOICE_CLIP_KEYS if key in existing
    }

# Real feature Aug 21, extended Aug 28 (item A): Matilda/Mateus recorded a batch of 15
# "greeting/praise" clips for check-in start/completion moments, left sitting in the
# voice-recordings bucket ROOT (not the en/pt/ canonical structure the 28 zone/helper clips
# above live in) - only Great_job/Muito_bem were ever wired (the original reward-screen
# clip). Re-inventoried directly against live Storage (not the old handover notes) before
# building: 8 English files, 7 Portuguese (I_did_it has no Portuguese recording - confirmed
# still true). Grouped into 3 pools by real UI moment, confirmed with Jono before building:
# "opening" (zone.tsx, the colour-picker screen), "praise" (rewards.tsx, replaces the old
# single Great_job-only call), "farewell" (rewards.tsx's exit/Continue tap). Each pool is
# randomized client-side on every play so a kid hears variety, not the same line every
# check-in. No Italian recordings exist for any of these 15 clips (checked the `it/` folder
# and every other Storage bucket directly) - `it` is simply absent from the language dict
# below, same "missing key/language quietly returns nothing" convention as the 28-clip
# manifest above, not a special case.
VOICE_PHRASE_POOLS = {
    "opening": {
        "en": ["How_are_you_feeling_today.m4a", "Check_in_with_my_feelings.m4a"],
        "pt": ["Como_te_sentes_hoje.m4a", "Regista_como_te_sentes.m4a"],
    },
    "praise": {
        "en": ["Great_job.m4a", "Well_done.m4a", "You_did_it.m4a", "I_did_it.m4a"],
        "pt": ["Muito_bem.m4a", "Boa.m4a", "Conseguiste.m4a"],
    },
    "farewell": {
        "en": ["See_you_tomorrow.m4a", "Thank_you_for_checking_in.m4a"],
        "pt": ["Ate_amanha.m4a", "Obrigada_por_te_registares.m4a"],
    },
}

@api_router.get("/voice-clips/phrases")
async def get_voice_phrase_pool(moment: str = "praise", language: str = "en"):
    pool = VOICE_PHRASE_POOLS.get(moment, {}).get(language, [])
