@api_router.post("/custom-strategies")
async def create_custom_strategy_alias(request: Request):
    """Alias for /helpers/custom - used by classrooms and strategies pages."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    body = await request.json()
    # Real fix Aug 26 (security audit): had no authorization check on the target student_id
    # at all - any authenticated user could create a custom strategy attributed to any
    # student. Placed before the try/except below since its bare `except Exception` would
    # otherwise mask a raised HTTPException as a 500 instead of a real 403.
    target_student_id = body.get("student_id")
    if target_student_id and not await _is_authorized_for_student(user, target_student_id):
        raise HTTPException(status_code=403, detail="Not authorized for this student")
    try:
        new_id = str(uuid.uuid4())
        strategy = {
            "id": new_id,
            "student_id": body.get("student_id"),
            "user_id": user["user_id"],
            "name": body.get("name", ""),
            "description": body.get("description", ""),
            "feeling_colour": body.get("feeling_colour", body.get("zone", "green")),
            "icon": body.get("icon", "star"),
            "is_shared": body.get("is_shared", True),
            "created_at": datetime.now(timezone.utc).isoformat(),
        }
        result = supabase.table("custom_helpers").insert(strategy).execute()
        return result.data[0] if result.data else strategy
    except Exception as e:
        logger.error(f"custom_strategies create error: {e}")
        raise HTTPException(status_code=500, detail=str(e))

@api_router.put("/custom-strategies/{strategy_id}")
async def update_custom_strategy(strategy_id: str, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): had no ownership check at all - any authenticated
    # user could edit any custom strategy system-wide by id. Placed before the try/except
    # below since its bare `except Exception` would otherwise mask a raised HTTPException
    # as a 500 instead of a real 403/404.
    existing = supabase.table("custom_helpers").select("user_id,student_id").eq("id", strategy_id).execute()
    if not existing.data:
        raise HTTPException(status_code=404, detail="Strategy not found")
    row = existing.data[0]
    if row.get("user_id") != user["user_id"] and not await _is_authorized_for_student(user, row.get("student_id") or ""):
        raise HTTPException(status_code=403, detail="Not authorized for this strategy")
    try:
        body = await request.json()
        update_data = {}
        for field in ["name", "description", "zone", "feeling_colour", "icon", "is_shared", "assigned_to"]:
            if field in body:
                update_data[field] = body[field]
        if "zone" in update_data:
            update_data["feeling_colour"] = update_data["zone"]
        result = supabase.table("custom_helpers").update(update_data).eq("id", strategy_id).execute()
        row = result.data[0] if result.data else update_data
        row["zone"] = row.get("zone") or row.get("feeling_colour", "green")
        return row
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@api_router.delete("/custom-strategies/{strategy_id}")
async def delete_custom_strategy(strategy_id: str, request: Request):
    """Delete a custom strategy - owner only."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): the docstring already said "owner only" but the code
    # never actually checked that - any authenticated user could delete any custom strategy
    # system-wide by id.
    existing = supabase.table("custom_helpers").select("user_id").eq("id", strategy_id).execute()
    if not existing.data:
        raise HTTPException(status_code=404, detail="Strategy not found")
    if existing.data[0].get("user_id") != user["user_id"] and user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Not authorized for this strategy")
    try:
        result = supabase.table("custom_helpers").delete().eq("id", strategy_id).execute()
        return {"deleted": True}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@api_router.get("/custom-strategies")
async def get_custom_strategies(request: Request, student_id: Optional[str] = None):
    """Get custom strategies for a student."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): with no student_id, this had NO filter at all -
    # returned every custom strategy for every student system-wide to any authenticated
    # user. With a student_id, it had no authorization check on that student either. Now:
    # no student_id -> scoped to strategies the caller themselves created; a student_id ->
    # requires real authorization for that specific student.
    if student_id and not await _is_authorized_for_student(user, student_id):
        raise HTTPException(status_code=403, detail="Not authorized for this student")
    try:
        query = supabase.table("custom_helpers").select("*")
        if student_id:
            query = query.eq("student_id", student_id)
        else:
            query = query.eq("user_id", user["user_id"])
        result = query.execute()
        # Normalise: add zone field from feeling_colour for frontend compatibility
        data = result.data or []
        for row in data:
            fc = row.get("feeling_colour", "")
            z  = row.get("zone", "")
            row["zone"]           = z or fc or "green"
            row["feeling_colour"] = fc or z or "green"
        return data
    except Exception as e:
        return []

@api_router.post("/helpers/custom")
async def create_custom_helper(helper: CustomHelperCreate, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    new_helper = {
        "id": str(uuid.uuid4()),
        "user_id": user["user_id"],
        "student_id": helper.student_id,
        "name": helper.name,
        "description": helper.description,
        "feeling_colour": helper.feeling_colour,
        "icon": helper.icon,
        "custom_image": helper.custom_image,
        "is_shared": helper.is_shared,
        "is_active": True,
        "created_at": datetime.now(timezone.utc).isoformat()
    }
    result = supabase.table("custom_helpers").insert(new_helper).execute()
    return result.data[0] if result.data else new_helper

