@api_router.get("/family/members")
async def get_family_members(request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): always self-scoped by user_id (never a data leak),
    # but had no role check.
    if user.get("role") not in ("parent", "superadmin"):
        raise HTTPException(status_code=403, detail="Parent access required")
    result = supabase.table("family_members").select("*").eq("user_id", user["user_id"]).execute()
    members = result.data or []
    # Real school link, path 1: the family_members.student_id row has a classroom_id
    student_ids = [m["student_id"] for m in members if m.get("student_id")]
    classroom_map = {}
    if student_ids:
        students_r = supabase.table("students").select("id,classroom_id").in_("id", student_ids).execute()
        classroom_map = {s["id"]: s.get("classroom_id") for s in (students_r.data or [])}
    # Real school link, path 2: a genuine parent_links row exists for this parent, matched by
    # child name — this is the older/legacy linking system the app itself actually uses, and
    # can be true even when family_members.student_id is null (confirmed real case: Matilda)
    linked_names_via_parent_links = set()
    name_to_real_student_id = {}
    try:
        pl = supabase.table("parent_links").select("student_id,expires_at").eq("parent_user_id", user["user_id"]).execute()
        active_student_ids = [
            l["student_id"] for l in (pl.data or [])
            if l.get("student_id") and (not l.get("expires_at") or datetime.fromisoformat(l["expires_at"].replace("Z","+00:00")) > datetime.now(timezone.utc))
        ]
        if active_student_ids:
            linked_students_r = supabase.table("students").select("id,name").in_("id", active_student_ids).execute()
            for s in (linked_students_r.data or []):
                if s.get("name"):
                    nm = s["name"].strip().lower()
                    linked_names_via_parent_links.add(nm)
                    name_to_real_student_id[nm] = s["id"]
    except Exception as e:
        logger.warning(f"[get_family_members] parent_links fallback check failed: {e}")
    for m in members:
        via_classroom = bool(m.get("student_id") and classroom_map.get(m["student_id"]))
        via_parent_links = (m.get("name") or "").strip().lower() in linked_names_via_parent_links
        m["school_linked"] = via_classroom or via_parent_links
        # Real fix: resolve the actual linked student_id via parent_links when the raw column is
        # null — this is what the app's own student-select screen uses to dedupe against real
        # school records; leaving it null causes a visible duplicate entry (confirmed real case:
        # Matilda showing twice, only one genuinely linked)
        if not m.get("student_id") and via_parent_links:
            resolved = name_to_real_student_id.get((m.get("name") or "").strip().lower())
            if resolved:
                m["student_id"] = resolved
    return members

@api_router.post("/family/members")
async def add_family_member(member: FamilyMemberCreate, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    if user.get("role") not in ("parent", "superadmin"):
        raise HTTPException(status_code=403, detail="Parent access required")
    # Free tier: limit to 2 children (mirrors the same real pattern used for classrooms/students —
    # only counts relationship=="child", adult family members like partners aren't capped).
    # Real fix Aug 18: this never checked school-package coverage, only the parent's own
    # subscription_status — a parent free because their school pays could still incorrectly
    # hit this cap. See _parent_is_school_covered (defined near /parent/link-child).
    if member.relationship == "child":
        # Real fix Aug 26 (item 4): the school-coverage side was already real
        # (_parent_is_school_covered), but the parent's own subscription_status check was
        # still expiry-blind - a lapsed trial/paid parent dodged this cap forever. Swapped
        # to _is_genuinely_free_tier(), same fix pattern as the Aug 24/25 creature caps.
        if _is_genuinely_free_tier(user):
            existing = supabase.table("family_members").select("id", count="exact").eq("user_id", user["user_id"]).eq("relationship", "child").execute()
            child_count = existing.count or len(existing.data or [])
            if child_count >= 2:
                raise HTTPException(
                    status_code=403,
                    detail="free_tier_limit|Free plan is limited to 2 children. Upgrade to Family Pro for unlimited children."
                )
    new_member = {
        "id": str(uuid.uuid4()),
        "user_id": user["user_id"],
        "name": member.name,
        "relationship": member.relationship,
        "avatar_type": member.avatar_type,
        "avatar_preset": member.avatar_preset,
        "avatar_custom": member.avatar_custom,
        "created_at": datetime.now(timezone.utc).isoformat()
    }
    if member.student_id:
        new_member["student_id"] = member.student_id
    result = supabase.table("family_members").insert(new_member).execute()
    
    # Auto-create student record for family children (gives full creature/points experience)
    if new_member.get("relationship") == "child":
        try:
            family_member_id = result.data[0]["id"] if result.data else new_member["id"]
            # Only use columns that exist in students table
            student_record = {
                "id": str(uuid.uuid4()),
                "user_id": user["user_id"],
                "name": new_member["name"],
                "avatar_type": new_member.get("avatar_type", "preset"),
                "avatar_preset": new_member.get("avatar_preset", "bear"),
                "avatar_custom": new_member.get("avatar_custom"),
                "created_at": datetime.now(timezone.utc).isoformat(),
            }
            student_result = supabase.table("students").insert(student_record).execute()
            if student_result.data:
                new_student_id = student_result.data[0]["id"]
                # Link the student back to the family member
                supabase.table("family_members").update({"student_id": new_student_id}).eq("id", family_member_id).execute()
                # Also init rewards so creature system works immediately
                default_rewards = {
                    "student_id": new_student_id,
                    "total_points_earned": 0,
                    "streak_days": 0,
                    "last_checkin_date": None,
                    "creature_points": {"aqua_buddy": 0, "leaf_friend": 0, "spark_pal": 0, "blaze_heart": 0},
                    "creature_stages": {"aqua_buddy": 0, "leaf_friend": 0, "spark_pal": 0, "blaze_heart": 0},
                    "collected_creatures": [],
                    "current_creature_id": "aqua_buddy",
                    "current_stage": 0,
                    "current_points": 0,
                }
                supabase.table("student_rewards").insert(default_rewards).execute()
        except Exception as e:
            logger.warning(f"Could not auto-create student for family child: {e}")
    return result.data[0] if result.data else new_member

@api_router.put("/family/members/{member_id}")
async def update_family_member(member_id: str, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): the actual update below was already correctly
    # scoped by user_id (not an IDOR), just had no role check.
    if user.get("role") not in ("parent", "superadmin"):
        raise HTTPException(status_code=403, detail="Parent access required")
    body = await request.json()
    allowed = ["name", "relationship", "avatar_type", "avatar_preset", "avatar_custom"]
    update_data = {k: v for k, v in body.items() if k in allowed and v is not None}
    if not update_data:
        raise HTTPException(status_code=400, detail="No valid fields to update")
    supabase.table("family_members").update(update_data).eq("id", member_id).eq("user_id", user["user_id"]).execute()
    updated = supabase.table("family_members").select("*").eq("id", member_id).eq("user_id", user["user_id"]).execute()
    if not updated.data:
        raise HTTPException(status_code=404, detail="Family member not found")
    member = updated.data[0]
    # Also update linked student record so avatar shows correctly in student flow
    student_id = member.get("student_id")
    if student_id:
        avatar_fields = {k: v for k, v in update_data.items() if k in ["avatar_type", "avatar_preset", "avatar_custom", "name"]}
        if avatar_fields:
            supabase.table("students").update(avatar_fields).eq("id", student_id).execute()
    return member

@api_router.delete("/family/members/{member_id}")
async def delete_family_member(member_id: str, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    if user.get("role") not in ("parent", "superadmin"):
        raise HTTPException(status_code=403, detail="Parent access required")
    # Real fix Aug 26 (security audit): had no ownership scoping at all (unlike the PUT
    # right above, which was already correctly scoped) - any authenticated user could
    # delete any family_members row system-wide by id.
    existing = supabase.table("family_members").select("id").eq("id", member_id).eq("user_id", user["user_id"]).execute()
    if not existing.data:
        raise HTTPException(status_code=404, detail="Family member not found")
    # Only delete the family_member record — preserve student profile and rewards
    # Student records/rewards should persist even if removed from family dashboard
    supabase.table("family_members").delete().eq("id", member_id).execute()
    return {"message": "Member deleted"}

async def _is_authorized_for_student(user: dict, student_id: str, student_data: dict = None) -> bool:
    """Shared authorization check for viewing an individual student's data (analytics, zone
    logs, available months). Real feature Aug 21: adds school_admin as a real authorized
    role for their own school's students - mirrors the dual-match (school_admin_id OR
    school_name) pattern used everywhere else for resolving "this school_admin's teachers".
    Reuses an already-fetched student_data row if the caller has one, to skip a duplicate
    query."""
    if student_data is None:
        student_r = supabase.table("students").select("*").eq("id", student_id).execute()
        if not student_r.data:
            return False
        student_data = student_r.data[0]
    if user.get("role") == "superadmin":
        return True
    if student_data.get("user_id") == user["user_id"]:
        return True
    classroom_id = student_data.get("classroom_id")
    classroom_owner_id = None
    if classroom_id:
        try:
            cls = supabase.table("classrooms").select("user_id").eq("id", classroom_id).execute()
            if cls.data:
                classroom_owner_id = cls.data[0].get("user_id")
        except Exception:
            pass
        if classroom_owner_id and classroom_owner_id == user["user_id"]:
            return True
    if user.get("role") == "school_admin" and classroom_owner_id:
        try:
            owner_r = supabase.table("users").select("school_admin_id,school_name").eq("user_id", classroom_owner_id).execute()
            if owner_r.data:
                owner = owner_r.data[0]
                if owner.get("school_admin_id") == user["user_id"]:
                    return True
                school_name = user.get("school_name", "")
                if school_name and owner.get("school_name") == school_name:
                    return True
        except Exception:
            pass
    try:
        pl = supabase.table("parent_links").select("id,expires_at").eq("parent_user_id", user["user_id"]).eq("student_id", student_id).execute()
        for l in (pl.data or []):
            if not l.get("expires_at") or datetime.fromisoformat(l["expires_at"].replace("Z", "+00:00")) > datetime.now(timezone.utc):
                return True
    except Exception:
        pass
    try:
        fm = supabase.table("family_members").select("id").eq("user_id", user["user_id"]).eq("student_id", student_id).execute()
        if fm.data:
            return True
    except Exception:
        pass
    return False

async def _is_authorized_for_classroom(user: dict, classroom_id: str, classroom_data: dict = None) -> bool:
    """Real fix Aug 26 (security audit): shared authorization check for classroom-scoped
    teacher endpoints (analytics, join code, delete) - same dual-match (school_admin_id OR
    school_name) precedent as _is_authorized_for_student's classroom-ownership branch.
    Several of these endpoints previously had NO check at all - any authenticated user could
    read or delete any classroom by id."""
    if classroom_data is None:
        cls_r = supabase.table("classrooms").select("*").eq("id", classroom_id).execute()
        if not cls_r.data:
            return False
        classroom_data = cls_r.data[0]
    if user.get("role") == "superadmin":
        return True
    owner_id = classroom_data.get("user_id")
    if owner_id == user["user_id"]:
        return True
    if user.get("role") == "school_admin" and owner_id:
        try:
            owner_r = supabase.table("users").select("school_admin_id,school_name").eq("user_id", owner_id).execute()
            if owner_r.data:
                owner = owner_r.data[0]
                if owner.get("school_admin_id") == user["user_id"]:
                    return True
                school_name = user.get("school_name", "")
                if school_name and owner.get("school_name") == school_name:
                    return True
        except Exception:
            pass
    return False

DEFAULT_CREATURE_IDS = {"aqua_buddy", "leaf_friend", "spark_pal", "blaze_heart"}

def _get_active_creatures(student_data: dict) -> dict:
    """Real feature Aug 21 (bug fix): a student's active creature per colour - either one of
    the 4 built-in default creatures (day-1 default, points-based evolution) or a community
    creature_submissions id they've chosen to pursue (check-in-count-based evolution, see
    _progress_community_creature). Defensive default if the column doesn't exist yet."""
    active = student_data.get("active_creatures") if student_data else None
    if not active or not isinstance(active, dict):
        return dict(FEELING_COLOUR_MAP)
    merged = dict(FEELING_COLOUR_MAP)
    merged.update({k: v for k, v in active.items() if v})
    return merged

def _is_creature_fully_evolved(student_data: dict, active_id: str, real_student_id: str) -> bool:
    """True if the currently-active creature for a colour has been fully evolved - gates
    whether a student may pick a new one for that colour (default creatures: stage 3/3 via
    student_rewards; community creatures: stages_unlocked 4/4 via creature_unlocks)."""
    if active_id in DEFAULT_CREATURE_IDS:
        rewards_r = supabase.table("student_rewards").select("creature_stages").eq("student_id", real_student_id).execute()
        if not rewards_r.data:
            return False
        stages = rewards_r.data[0].get("creature_stages") or {}
        return (stages.get(active_id, 0) or 0) >= 3
    unlocks_r = _creature_unlocks_for(real_student_id, real_student_id, [active_id])
    return bool(unlocks_r.data) and (unlocks_r.data[0].get("stages_unlocked", 0) or 0) >= 4

def _creature_progress_percent(active_id: str, real_student_id: str, emotion_colour: str = None) -> int:
    """Real feature Aug 27 (item 12, press-and-hold progress ring): single source of truth
    for "% complete" toward a creature's next evolution, computed with the exact same
    thresholds _is_creature_fully_evolved/_progress_community_creature use to decide when a
    creature actually evolves - kept here instead of duplicated in the frontend so the two
    can never drift out of sync. Default creatures are points-based (0/25/60/120, the same
    4 thresholds every default creature line uses); community creatures are a rolling
    30-day check-in count against the same [5,10,15,20] thresholds
    _progress_community_creature evolves on."""
    if active_id in DEFAULT_CREATURE_IDS:
        rewards_r = supabase.table("student_rewards").select("creature_points").eq("student_id", real_student_id).execute()
        points = (rewards_r.data[0].get("creature_points") if rewards_r.data else None) or {}
        current_points = points.get(active_id, 0) or 0
        return max(0, min(100, round(current_points / 120 * 100)))
    if not emotion_colour:
        creature_r = supabase.table("creature_submissions").select("emotion_colour").eq("id", active_id).execute()
        emotion_colour = creature_r.data[0].get("emotion_colour") if creature_r.data else None
    if not emotion_colour:
        return 0
    checkins = supabase.table("feeling_logs").select("id").eq("student_id", real_student_id).eq(
        "feeling_colour", emotion_colour
    ).gte("timestamp", (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()).execute()
    total_checkins = len(checkins.data) if checkins.data else 0
    return max(0, min(100, round(total_checkins / 20 * 100)))

def _progress_community_creature(real_student_id: str, submission_id: str):
    """Real bug fix Aug 21: extracted from unlock_creature_stage so both the direct endpoint
    and the check-in-driven path (add_points) share one real implementation - no duplicated
    threshold/snapshot logic. real_student_id here is always a real students.id (this function
    is only ever called once a creature is a student's genuine active pursuit for its colour)."""
    creature_r = supabase.table("creature_submissions").select(
        "emotion_colour,creature_name,stage1_url,stage2_url,stage3_url,stage4_url,status"
    ).eq("id", submission_id).execute()
    if not creature_r.data or creature_r.data[0].get("status") != "approved":
        return None
    creature = creature_r.data[0]
    checkins = supabase.table("feeling_logs").select("id")        .eq("student_id", real_student_id)        .eq("feeling_colour", creature.get("emotion_colour"))        .gte("timestamp", (datetime.now(timezone.utc) - timedelta(days=30)).isoformat())        .execute()
    total_checkins = len(checkins.data) if checkins.data else 0
    existing = _creature_unlocks_for(real_student_id, real_student_id, [submission_id])
    current_stages = existing.data[0]["stages_unlocked"] if existing.data else 0
    required = [5, 10, 15, 20]
    next_stage = current_stages + 1
    evolved = False
    if next_stage <= 4 and total_checkins >= required[current_stages]:
        evolved = True
        snapshot_fields = {}
        if next_stage == 4:
            now_iso = datetime.now(timezone.utc).isoformat()
            featured_now = supabase.table("featured_creatures").select("active_until")                .eq("creature_id", submission_id).lte("active_from", now_iso).gte("active_until", now_iso).execute()
            was_featured = bool(featured_now.data)
            snapshot_fields = {
                "creature_name_snapshot": creature.get("creature_name"),
                "emotion_colour_snapshot": creature.get("emotion_colour"),
                "stage_image_snapshot": creature.get("stage4_url"),
                "was_featured": was_featured,
                "featured_until_snapshot": featured_now.data[0]["active_until"] if was_featured else None,
            }
        if existing.data:
            completed = datetime.now(timezone.utc).isoformat() if next_stage == 4 else None
            update_body = {"stages_unlocked": next_stage, "completed_at": completed}
            try:
                supabase.table("creature_unlocks").update({**update_body, **snapshot_fields}).eq("id", existing.data[0]["id"]).execute()
            except Exception:
                supabase.table("creature_unlocks").update(update_body).eq("id", existing.data[0]["id"]).execute()
        else:
            new_row = {"student_id": real_student_id, "creature_id": submission_id, "stages_unlocked": next_stage, "real_student_id": real_student_id}
            try:
                supabase.table("creature_unlocks").insert(new_row).execute()
            except Exception:
                supabase.table("creature_unlocks").insert({"student_id": real_student_id, "creature_id": submission_id, "stages_unlocked": next_stage}).execute()
        current_stages = next_stage
        if next_stage == 4:
            supabase.table("creature_submissions").update({
                "global_uses": supabase.table("creature_submissions").select("global_uses")                    .eq("id", submission_id).execute().data[0]["global_uses"] + 1
            }).eq("id", submission_id).execute()
    needed_for_next = 0
    if current_stages < 4 and not evolved:
        needed_for_next = max(0, required[current_stages] - total_checkins)
    return {
        "type": "community",
        "id": submission_id,
        "name": creature.get("creature_name"),
        "emotion_colour": creature.get("emotion_colour"),
        "stage1_url": creature.get("stage1_url"),
        "stage2_url": creature.get("stage2_url"),
        "stage3_url": creature.get("stage3_url"),
        "stage4_url": creature.get("stage4_url"),
        "current_stage": current_stages,
        "evolved": evolved,
        "is_complete": current_stages >= 4,
        "needed_for_next": needed_for_next,
    }

def _creature_unlocks_for(user_id: str, real_student_id: Optional[str], creature_ids: list = None):
    """Real feature Aug 21: creature_unlocks was keyed only by the SUBMITTING ACCOUNT's user_id
    (student_id column) - meaning a teacher's whole classroom, or a multi-child parent's kids,
    all shared ONE progress bucket per creature. real_student_id is a new, migration-dependent
    column that keys progress to the actual student instead. Tries the real_student_id lookup
    first when one is given; falls back to the old account-level lookup if the column doesn't
    exist yet (migration pending) or no real_student_id was provided, so nothing breaks."""
    if real_student_id:
        try:
            q = supabase.table("creature_unlocks").select("*").eq("real_student_id", real_student_id)
            if creature_ids is not None:
                q = q.in_("creature_id", creature_ids)
            return q.execute()
        except Exception:
            pass
    q = supabase.table("creature_unlocks").select("*").eq("student_id", user_id)
    if creature_ids is not None:
        q = q.in_("creature_id", creature_ids)
    return q.execute()

def _free_tier_colour_locks(user_id: str, real_student_id: Optional[str]) -> dict:
    """Real feature Aug 24 (item 1, free-tier collection cap): for a given student, which
    colours already have one fully-evolved (stages_unlocked>=4) community creature - once a
    colour appears here, no OTHER creature of that same colour should be startable/selectable
    for a free-tier account, per Jono's spec (one fully-evolved community creature per colour,
    ever, pooled per real student). Returns {colour: creature_id} for the creature that used
    up each colour's one free slot. Reuses _creature_unlocks_for's own real_student_id-first,
    account-level-fallback resolution, so this degrades the same way every other
    real_student_id-aware check in this file already does when that data isn't available for
    a given row."""
    unlocks_r = _creature_unlocks_for(user_id, real_student_id)
    fully_evolved_ids = [u["creature_id"] for u in (unlocks_r.data or []) if u.get("stages_unlocked", 0) >= 4]
    if not fully_evolved_ids:
        return {}
    creatures_r = supabase.table("creature_submissions").select("id,emotion_colour").in_("id", fully_evolved_ids).execute()
    locks = {}
    for c in (creatures_r.data or []):
        colour = c.get("emotion_colour")
        if colour and colour not in locks:
            locks[colour] = c["id"]
    return locks

def _resolve_student_classroom_school(student_data: dict):
    """Real feature Aug 21: given a students row, resolve (classroom_id, school_name) for
    creature-eligibility matching. school_name comes from the classroom owner (teacher)'s
    own user record, mirroring the dual-match pattern used everywhere else in this file."""
    classroom_id = student_data.get("classroom_id")
    school_name = None
    if classroom_id:
        try:
            cls = supabase.table("classrooms").select("user_id").eq("id", classroom_id).execute()
            if cls.data:
                owner_id = cls.data[0].get("user_id")
                if owner_id:
                    owner_r = supabase.table("users").select("school_name").eq("user_id", owner_id).execute()
                    if owner_r.data:
                        school_name = owner_r.data[0].get("school_name")
        except Exception:
            pass
    return classroom_id, school_name

def _admin_is_active(admin_id: str) -> bool:
    """True if this school_admin user_id has an ACTIVE paid plan. Shared by
    _parent_is_school_covered and _teacher_is_school_covered — extracted Aug 19
    (A8) from what used to be a private closure inside the parent version only.
    Real bug fix Aug 28 (technical debt sweep, item 3): only ever checked the raw
    subscription_status=="active" string, never subscription_expires_at - same expiry-blind
    class already fixed elsewhere via check_subscription_active()/_is_genuinely_free_tier(),
    just missed here since this is the ONE school-wide gate (waives free-tier caps for every
    teacher/parent at the school at once), not a per-user gate, so it wasn't caught by the
    earlier per-endpoint sweep. A lapsed school plan whose subscription_status string hadn't
    yet been separately flipped would otherwise leave every teacher/parent at that school
    uncapped indefinitely. Same active-branch pattern as check_subscription_active()."""
    if not admin_id:
        return False
    r = supabase.table("users").select("subscription_status,subscription_expires_at").eq("user_id", admin_id).execute()
    if not r.data:
        return False
    admin = r.data[0]
    if admin.get("subscription_status") != "active":
        return False
    exp = admin.get("subscription_expires_at")
    if exp:
        return datetime.fromisoformat(exp.replace("Z", "+00:00")) > datetime.now(timezone.utc)
    return True

def _any_school_admin_active_by_name(school_name: str) -> bool:
    """Same expiry-aware check as _admin_is_active, for the school_name dual-match fallback
    used by _teacher_is_school_covered/_parent_is_school_covered when a teacher/parent's
    school_admin_id was never backfilled. Real bug fix Aug 28: this fallback path had the
    exact same expiry-blind subscription_status=="active" check _admin_is_active just had -
    fixed the same way, shared here instead of duplicating the expiry logic a third time."""
    if not school_name:
        return False
    admins = supabase.table("users").select("subscription_status,subscription_expires_at").eq("role", "school_admin").eq("school_name", school_name).execute()
    now = datetime.now(timezone.utc)
    for a in (admins.data or []):
        if a.get("subscription_status") != "active":
            continue
        exp = a.get("subscription_expires_at")
        if not exp or datetime.fromisoformat(exp.replace("Z", "+00:00")) > now:
            return True
    return False

def _school_admin_can_view_teacher_wellbeing(admin_user: dict, target_teacher: dict) -> bool:
    """Real feature Aug 21: teacher-consent mechanism for individual wellbeing visibility -
    previously there was NO path at all for a school_admin to see a specific teacher's
    wellbeing, not even opt-in. Default-off, explicit opt-in, revocable at any time - mirrors
    the parent<->teacher home_sharing_enabled pattern, just at the teacher-account level
    since there's no separate link table here (the relationship already exists via
    school_admin_id/school_name). Requires the new teacher_wellbeing_shared_with_admin
    column (see COH-REVIEW-PLAN.md for the migration) - defensively returns False if that
    column doesn't exist yet rather than erroring."""
    if not target_teacher.get("teacher_wellbeing_shared_with_admin"):
        return False
    admin_id = admin_user.get("user_id")
    if target_teacher.get("school_admin_id") == admin_id:
        return True
    school_name = admin_user.get("school_name")
    if school_name and target_teacher.get("school_name") == school_name:
        return True
    return False

def _teacher_is_school_covered(user: dict) -> bool:
    """True if this teacher's own school (via school_admin_id, with the same school_name
    dual-match fallback used everywhere else in this file since L4) has an ACTIVE paid plan.
    Real feature Aug 19 (A8): used to gate the classroom-overview PDF's historical-month
    access — simpler than the parent version since a teacher already carries their own
    school_admin_id/school_name directly, no parent_links walk needed."""
    if _admin_is_active(user.get("school_admin_id")):
        return True
    return _any_school_admin_active_by_name(user.get("school_name"))

def _parent_is_school_covered(user: dict) -> bool:
    """True if any of this parent's linked children attend a school whose own school_admin
    account has an ACTIVE paid plan. Real fix Aug 18, per Jono's final pricing model
    (parents are free specifically because the school paid): being merely linked to a
    school_admin used to count as 'covered' regardless of whether that school ever actually
    paid (bool(school_admin_id) alone) — that was a real loophole under the old logic, since
    a school_admin on a lapsed/none subscription would make all their teachers' parents free
    forever. Now requires subscription_status == 'active' on the school_admin's own row."""
    # Rare case: a parent row itself carries a school_admin_id.
    if _admin_is_active(user.get("school_admin_id")):
        return True

    try:
        links = supabase.table("parent_links").select("student_id").eq("parent_user_id", user["user_id"]).execute()
        student_ids = [l["student_id"] for l in (links.data or [])]
        if not student_ids:
            return False
        students = supabase.table("students").select("classroom_id").in_("id", student_ids).execute()
        classroom_ids = list({s["classroom_id"] for s in (students.data or []) if s.get("classroom_id")})
        if not classroom_ids:
            return False
        classrooms = supabase.table("classrooms").select("user_id").in_("id", classroom_ids).execute()
        teacher_ids = list({c["user_id"] for c in (classrooms.data or []) if c.get("user_id")})
        if not teacher_ids:
            return False
        teachers = supabase.table("users").select("school_admin_id,school_name").in_("user_id", teacher_ids).execute()
        for t in (teachers.data or []):
            if _admin_is_active(t.get("school_admin_id")):
                return True
            # Dual-match fallback, same principle as the L4 school-identity fix: a teacher's
            # own school_admin_id can be unbackfilled even when their school_name correctly
            # matches an active school's admin.
            if _any_school_admin_active_by_name(t.get("school_name")):
                return True
        return False
    except Exception as e:
        logger.warning(f"_parent_is_school_covered check failed for {user.get('user_id')}: {e}")
        return False

def _can_switch_to_teacher(user: dict) -> bool:
    """Real fix Aug 26: PUT /auth/role used to just flip the role column - live-confirmed
    exploit, a paying PARENT account (subscription_plan='parent') could switch to teacher
    and immediately get unlimited teacher-tier access (e.g. the free-tier 10-student cap
    never enforced) for free, forever, since subscription_plan is never re-checked anywhere
    else in this codebase. Requires genuine entitlement to teacher tier specifically - not
    just "any active subscription" (that's exactly what a paying parent has) - via one of
    three legitimate paths: (1) an actual teacher-tier Stripe subscription, (2) a valid
    trial (grants full access regardless of role everywhere else in this file, so treated
    the same way here), (3) the account's own school already covers it as a teacher.
    Switching TO parent is deliberately NOT gated the same way elsewhere - parent is the
    cheaper/free-available tier, so moving to it is never itself a bypass."""
    if user.get("subscription_status") == "active" and user.get("subscription_plan") == "teacher":
        exp = user.get("subscription_expires_at")
        if not exp or datetime.fromisoformat(exp.replace("Z", "+00:00")) > datetime.now(timezone.utc):
            return True
    if _trial_is_valid(user):
        return True
    if _teacher_is_school_covered(user):
        return True
    return False

def _is_genuinely_free_tier(user: dict) -> bool:
    """Real feature Aug 24 (creature free-tier caps): every existing free_tier_limit check in
    this file (students/classrooms/children/reports/family-strategies) treats ANY
    subscription_status other than 'none'/'free' as "not free" - including a trial or paid
    plan that has genuinely EXPIRED, since nothing ever flips subscription_status back once
    set (same root cause already found and fixed on the subscription screen's Subscribe
    button, Aug 23). A lapsed account would incorrectly dodge every existing cap forever.
    Per Jono's explicit decision, the new creature caps check real expiry instead - this is a
    deliberate, acknowledged divergence from the older checks, not an oversight; the older
    ones are flagged as a separate future fix, not silently copied here.
    Also respects the same school-coverage bypass every other free-tier check uses, so a
    teacher/parent whose school pays is never capped just because their own personal
    subscription_status says otherwise.
    Real bug fix Aug 25: trial-status expiry now goes through the shared _trial_is_valid(),
    which correctly honours a promo-code trial's real (e.g. 30-day) expiry via
    subscription_expires_at instead of always assuming the standard 14-day window - see
    _trial_is_valid's own docstring for the full story."""
    sub_status = user.get("subscription_status") or "none"
    now = datetime.now(timezone.utc)
    if sub_status == "active":
        exp = user.get("subscription_expires_at")
        if not exp or datetime.fromisoformat(exp.replace("Z", "+00:00")) > now:
            return False  # genuinely active, not free tier
    elif sub_status == "trial" and _trial_is_valid(user):
        return False  # genuinely still in a valid trial, not free tier
    role = user.get("role")
    if role == "teacher" and _teacher_is_school_covered(user):
        return False
    if role == "parent" and _parent_is_school_covered(user):
        return False
    return True

@api_router.get("/parent/coverage-status")
async def get_parent_coverage_status(request: Request):
    """New Aug 18, for the subscription screen: lets the app show 'free — covered by your
    school' instead of a €4.99 paywall it would otherwise never need for covered parents."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    covered = user.get("role") == "parent" and _parent_is_school_covered(user)
    return {"covered": covered}

@api_router.post("/parent/link-child")
async def link_child(body: LinkChildRequest, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Try both field names for compatibility
    result = supabase.table("students").select("*").eq("link_code", body.link_code).execute()
    if not result.data:
        result = supabase.table("students").select("*").eq("link_code", body.link_code).execute()
    if not result.data:
        raise HTTPException(status_code=404, detail="Invalid link code")
    student = result.data[0]
    if student.get("link_code_expires_at"):
        exp = datetime.fromisoformat(student["link_code_expires_at"].replace("Z", "+00:00"))
        if exp < datetime.now(timezone.utc):
            raise HTTPException(status_code=400, detail="Link code expired")

    # Real freemium gate, per Jono's explicit rule: the home-school link only completes if
    # EITHER the teacher has subscribed, OR the parent has subscribed, OR there's a school
    # package covering either side. Real fix Aug 18: school-package coverage now requires
    # the school_admin's own subscription_status == "active" (see _parent_is_school_covered
    # above), not just link presence — closes the "free forever via an unpaid school_admin"
    # loophole under the new parent pricing model.
    # Real fix Aug 26 (item 4): both sides of this check were expiry-blind - parent_covered
    # and teacher_covered treated ANY non-none/free subscription_status as "covered" forever,
    # same root cause as the Aug 24/25 creature-cap bugs (a lapsed trial/paid account, on
    # either side, never lost this coverage). _is_genuinely_free_tier() already fixes real
    # expiry + real school-coverage together - reused for the parent directly (it already has
    # role/subscription_expires_at). The teacher record is fetched separately, so role and
    # subscription_expires_at are pulled explicitly and role is set for the helper.
    parent_covered = not _is_genuinely_free_tier(user)
    teacher_covered = False
    classroom_id = student.get("classroom_id")
    if classroom_id:
        try:
            classroom_result = supabase.table("classrooms").select("user_id").eq("id", classroom_id).execute()
            if classroom_result.data:
                teacher_id = classroom_result.data[0].get("user_id")
                teacher_result = supabase.table("users").select("subscription_status,subscription_expires_at,school_admin_id,school_name").eq("user_id", teacher_id).execute()
                if teacher_result.data:
                    teacher = {**teacher_result.data[0], "role": "teacher"}
                    teacher_covered = not _is_genuinely_free_tier(teacher)
        except Exception as e:
            logger.warning(f"link_child teacher status check failed: {e}")
    if not parent_covered and not teacher_covered:
        raise HTTPException(
            status_code=403,
            detail="free_tier_limit|Home-school linking requires either you or your child's teacher to have a subscription, or a school plan covering your child's class. Upgrade to link your account."
        )

    # Link parent to student
    supabase.table("parent_links").insert({
        "id": str(uuid.uuid4()),
        "parent_user_id": user["user_id"],
        "student_id": student["id"],
        "created_at": datetime.now(timezone.utc).isoformat(),
        "expires_at": (datetime.now(timezone.utc) + timedelta(days=30)).isoformat()
    }).execute()
    return {"message": "Child linked successfully", "student": student}

@api_router.post("/students/link")
async def link_child_compat(body: LinkChildRequest, request: Request):
    # Frontend compatibility alias
    return await link_child(body, request)

@api_router.get("/parent/children")
async def get_linked_children(request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    children = []
    seen_ids = set()
    links = supabase.table("parent_links").select("*").eq("parent_user_id", user["user_id"]).execute()
    for link in (links.data or []):
        student = supabase.table("students").select("*").eq("id", link["student_id"]).execute()
        if student.data and student.data[0]["id"] not in seen_ids:
            children.append(student.data[0])
            seen_ids.add(student.data[0]["id"])
    return children

@api_router.get("/parent/available-students")
async def get_available_students(request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    children = []
    seen_ids = set()
    links = supabase.table("parent_links").select("*").eq("parent_user_id", user["user_id"]).execute()
    for link in (links.data or []):
        student = supabase.table("students").select("*").eq("id", link["student_id"]).execute()
        if student.data and student.data[0]["id"] not in seen_ids:
            s = student.data[0]
            s["_source"] = "school"
            children.append(s)
            seen_ids.add(s["id"])
    own_students = supabase.table("students").select("*").eq("user_id", user["user_id"]).execute()
    for s in (own_students.data or []):
        if s["id"] not in seen_ids:
            s["_source"] = "own"
            children.append(s)
            seen_ids.add(s["id"])
    return children

# ================== STRATEGY SHARING ==================

@api_router.get("/strategies/shared/{student_id}")
async def get_shared_strategies_for_student(student_id: str, request: Request):
    """Get all strategies visible to a student: teacher custom + parent shared."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): had no authorization check at all - any authenticated
    # user could pull any student's full strategy list (teacher + all linked parents' custom
    # strategies) by id.
    if not await _is_authorized_for_student(user, student_id):
        raise HTTPException(status_code=403, detail="Not authorized for this student")
    try:
        data = []
        seen_ids = set()

        # 1. Teacher-added custom strategies for this student
        try:
            result = supabase.table("custom_helpers").select("*").eq("student_id", student_id).execute()
            for s in (result.data or []):
                if s["id"] not in seen_ids:
                    s["creator_role"] = "teacher"
                    data.append(s)
                    seen_ids.add(s["id"])
        except Exception as e:
            logger.error(f"teacher strategies fetch error: {e}")

        # 2. Parent family strategies linked via parent_links
        try:
            links = supabase.table("parent_links").select("parent_user_id").eq("student_id", student_id).execute()
            for link in (links.data or []):
                parent_id = link.get("parent_user_id")
                if not parent_id:
                    continue
                # Get ALL parent custom strategies (not just is_shared)
                fam_result = supabase.table("custom_helpers").select("*").eq("user_id", parent_id).execute()
                for s in (fam_result.data or []):
                    if s["id"] in seen_ids:
                        continue
                    assigned = s.get("assigned_to", "all") or "all"
                    # Show if assigned to all, or to this specific student
                    if assigned in ("all", student_id):
                        s["creator_role"] = "parent"
                        data.append(s)
                        seen_ids.add(s["id"])
        except Exception as e:
            logger.error(f"parent strategies fetch error: {e}")

        # 3. Family member strategies — for family children (no parent_links entry)
        # Find if this student_id belongs to a family member, then get that parent's strategies
        try:
            fm_result = supabase.table("family_members").select("user_id").eq("student_id", student_id).execute()
            for fm in (fm_result.data or []):
                parent_id = fm.get("user_id")
                if not parent_id:
                    continue
                fam_result2 = supabase.table("custom_helpers").select("*").eq("user_id", parent_id).execute()
                for s in (fam_result2.data or []):
                    if s["id"] in seen_ids:
                        continue
                    assigned = s.get("assigned_to", "all") or "all"
                    if assigned in ("all", student_id):
                        s["creator_role"] = "parent"
                        data.append(s)
                        seen_ids.add(s["id"])
        except Exception as e:
            logger.error(f"family member strategies fetch error: {e}")

        # Normalise zone/feeling_colour for all
        for row in data:
            fc = row.get("feeling_colour", "")
            z  = row.get("zone", "")
            row["zone"] = z or fc or "green"
            row["feeling_colour"] = fc or z or "green"
            if "creator_role" not in row:
                row["creator_role"] = "teacher"

        return data
    except Exception as e:
        logger.error(f"get_shared_strategies error: {e}")
        return []

@api_router.put("/strategies/sync/{strategy_id}")
async def toggle_strategy_sync(strategy_id: str, request: Request):
    """Toggle is_shared on a custom strategy."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    try:
        current = supabase.table("custom_helpers").select("is_shared,user_id,student_id").eq("id", strategy_id).execute()
        if not current.data:
            raise HTTPException(status_code=404, detail="Strategy not found")
        # Real fix Aug 26 (security audit): had no ownership check at all - any authenticated
        # user could flip is_shared on any custom strategy system-wide by id.
        row = current.data[0]
        if row.get("user_id") != user["user_id"] and not await _is_authorized_for_student(user, row.get("student_id") or ""):
            raise HTTPException(status_code=403, detail="Not authorized for this strategy")
        new_val = not current.data[0].get("is_shared", False)
        supabase.table("custom_helpers").update({"is_shared": new_val}).eq("id", strategy_id).execute()
        return {"is_shared": new_val}
    except HTTPException:
        # Real fix Aug 26 (security audit): this bare except used to swallow the 404/403
        # above into a generic 500, masking both the pre-existing "not found" case and the
        # new ownership check.
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

