@api_router.get("/subscription/status")
async def get_subscription_status(request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    is_active = check_subscription_active(user)
    # Real feature Aug 26 (item 1, cancel-to-free): cancel_at_period_end lives only on
    # Stripe (see _active_stripe_subs's comment) - fetched live here so Settings can show
    # "ends on X, won't renew" instead of "renews on X" once someone's cancelled.
    cancel_at_period_end = False
    if user.get("subscription_status") == "active":
        active_subs = _active_stripe_subs(user.get("stripe_customer_id"))
        cancel_at_period_end = any(_sget(s, "cancel_at_period_end") for s in active_subs)
    # Real fix Aug 26 (item 4): a school-covered teacher/parent's subscription_status is
    # 'active' (correctly - they DO have access) but there's no personal Stripe subscription
    # behind it, so POST /subscription/cancel is guaranteed to 400 for them. Settings uses
    # this flag to show "Managed by your school" instead of a Cancel button that can't work,
    # rather than a confusing error after the fact.
    school_covered = (
        (user.get("role") == "teacher" and _teacher_is_school_covered(user)) or
        (user.get("role") == "parent" and _parent_is_school_covered(user))
    )
    return {
        "is_active": is_active,
        "status": user.get("subscription_status", "none"),
        "expires_at": user.get("subscription_expires_at"),
        "trial_started_at": user.get("trial_started_at"),
        "cancel_at_period_end": cancel_at_period_end,
        "school_covered": school_covered,
    }

# Real fix Aug 18: the app's subscription screen has always called these two endpoints
# (frontend/src/utils/api.ts subscriptionApi.createCheckout/getPaymentStatus) but neither
# existed on the backend — every "Subscribe" tap 404'd. Self-serve checkout is scoped to
# teacher_monthly/parent_monthly only; school plans are sold manually (mailto enquiry in
# the app), so no school branch here by design.
@api_router.post("/subscription/checkout")
async def create_subscription_checkout(request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    if not STRIPE_SECRET_KEY:
        raise HTTPException(status_code=500, detail="Payments are not configured")
    body = await request.json()
    plan = body.get("plan", "")
    origin_url = (body.get("origin_url") or "").rstrip("/")
    if plan not in ("teacher_monthly", "parent_monthly"):
        raise HTTPException(status_code=400, detail="Invalid plan. Only teacher_monthly and parent_monthly are available for self-serve checkout.")
    if not origin_url:
        raise HTTPException(status_code=400, detail="origin_url required")
    price_id = STRIPE_PRICE_IDS.get(plan, "")
    if not price_id:
        raise HTTPException(status_code=500, detail=f"Stripe price for '{plan}' is not configured yet")
    try:
        session = stripe_lib.checkout.Session.create(
            mode="subscription",
            payment_method_types=["card"],
            line_items=[{"price": price_id, "quantity": 1}],
            customer_email=user.get("email"),
            client_reference_id=user["user_id"],
            metadata={"user_id": user["user_id"], "plan": plan},
            success_url=f"{origin_url}/subscription/success?session_id={{CHECKOUT_SESSION_ID}}",
            cancel_url=f"{origin_url}/subscription",
        )
    except Exception as e:
        logger.error(f"Stripe checkout session creation failed for {user['user_id']} ({plan}): {e}")
        raise HTTPException(status_code=500, detail="Could not start checkout. Try again.")
    return {"url": session.url, "session_id": session.id}

@api_router.get("/subscription/status/{session_id}")
async def get_checkout_session_status(session_id: str, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    if not STRIPE_SECRET_KEY:
        raise HTTPException(status_code=500, detail="Payments are not configured")
    try:
        session = stripe_lib.checkout.Session.retrieve(session_id)
    except Exception as e:
        logger.error(f"Could not retrieve checkout session {session_id}: {e}")
        raise HTTPException(status_code=404, detail="Checkout session not found")
    # Real fix Aug 18, found live-testing: this stripe-python version's objects don't
    # support .get() at all (AttributeError) — only bracket access works. See _sget,
    # defined near the webhook handler below.
    if _sget(session, "client_reference_id") != user["user_id"]:
        raise HTTPException(status_code=403, detail="This checkout session does not belong to you")
    # Read payment_status directly from the Stripe session — it's set synchronously on
    # successful payment, unlike Supabase's subscription_status which only updates once the
    # async webhook lands. Matches what frontend/app/subscription/success.tsx checks for.
    return {
        "status": _sget(session, "payment_status", "unpaid"),
        "plan": _sget(_sget(session, "metadata", {}), "plan"),
        "expires_at": None,
    }

# Real feature Aug 26 (item 1, cancel-to-free): standard SaaS cancel semantics - schedule
# the cancellation on Stripe (cancel_at_period_end=True) rather than deleting the
# subscription outright, so access continues until the period the user already paid for
# actually ends. No separate "downgrade" data-migration step needed here - confirmed
# against real source that _is_genuinely_free_tier() and check_subscription_active() both
# already key off subscription_expires_at vs real time, not just subscription_status, so
# the moment the current period genuinely ends (whether via this cancellation or a lapsed
# renewal) the account already behaves as free-tier everywhere caps are enforced - nothing
# in this codebase ever deletes creature/collection/check-in data on downgrade, only
# account deletion does, and that's a fully separate, explicit, re-authenticated flow.
# cancel_at_period_end is intentionally NOT stored in Supabase (would need a migration this
# app can't run itself) - fetched live from Stripe on each read instead, which is also
# more correct: Stripe is the actual source of truth for billing state.
def _active_stripe_subs(stripe_customer_id: str):
    if not stripe_customer_id or not STRIPE_SECRET_KEY:
        return []
    try:
        subs = stripe_lib.Subscription.list(customer=stripe_customer_id, status="active")
        return _sget(subs, "data", []) or []
    except Exception as e:
        logger.warning(f"Could not list Stripe subscriptions for {stripe_customer_id}: {e}")
        return []

@api_router.post("/subscription/cancel")
async def cancel_subscription(request: Request):
    """Schedules cancellation at the end of the current paid period - does not revoke
    access immediately. See module comment above for why no data changes here."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    if user.get("role") not in ("teacher", "parent"):
        raise HTTPException(status_code=403, detail="Only teacher and parent accounts can manage a subscription here.")
    # Real fix Aug 26 (item 4): this used to give one flat "no active subscription found" for
    # three genuinely different situations - live-confirmed the most common real one: a
    # school-covered account whose own Settings screen correctly says "Active" (they DO have
    # access, just via their school, not a personal Stripe subscription), so Cancel was
    # guaranteed to fail with a confusing error every time. Settings now hides the Cancel
    # button entirely for this case (see school_covered on GET /subscription/status) - this
    # check stays as defense-in-depth for anyone who reaches the endpoint directly.
    is_school_covered = (
        (user.get("role") == "teacher" and _teacher_is_school_covered(user)) or
        (user.get("role") == "parent" and _parent_is_school_covered(user))
    )
    if is_school_covered:
        raise HTTPException(
            status_code=400,
            detail="Your account is covered by your school's plan - there's no personal subscription to cancel. Contact your school if you have questions about their plan."
        )
    if not user.get("stripe_customer_id"):
        raise HTTPException(status_code=400, detail="No active subscription found to cancel.")
    active_subs = _active_stripe_subs(user.get("stripe_customer_id"))
    if not active_subs:
        # Genuinely paying-in-theory (has a Stripe customer) but Stripe shows nothing active -
        # a real desync (e.g. cancelled directly in Stripe, outside the app) rather than the
        # "never had a personal subscription at all" case above.
        raise HTTPException(
            status_code=400,
            detail="We couldn't find an active payment to cancel. If you're still being charged, please contact support."
        )
    for sub in active_subs:
        stripe_lib.Subscription.modify(_sget(sub, "id"), cancel_at_period_end=True)
    return {"status": "cancel_scheduled", "access_until": user.get("subscription_expires_at")}

@api_router.post("/subscription/resume")
async def resume_subscription(request: Request):
    """Undoes a scheduled cancellation - lets someone who changed their mind keep their
    subscription without having to re-checkout."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    if user.get("role") not in ("teacher", "parent"):
        raise HTTPException(status_code=403, detail="Only teacher and parent accounts can manage a subscription here.")
    active_subs = _active_stripe_subs(user.get("stripe_customer_id"))
    if not active_subs:
        raise HTTPException(status_code=400, detail="No active subscription found to resume.")
    for sub in active_subs:
        stripe_lib.Subscription.modify(_sget(sub, "id"), cancel_at_period_end=False)
    return {"status": "resumed"}


