import random, string, calendar
from datetime import datetime, timezone, timedelta

def gen_code(length=8):
    return ''.join(random.choices(string.ascii_uppercase + string.digits, k=length))

@api_router.post("/creatures/generate-code")
async def generate_submission_code(request: Request):
    """Teacher or parent generates a code to give a student."""
    user = await get_current_user(request)
    if not user or user.get("role") not in ["teacher","parent","school_admin","admin","superadmin"]:
        raise HTTPException(status_code=403, detail="Teachers and parents only")
    code = gen_code()
    # ensure unique
    while supabase.table("submission_codes").select("id").eq("code", code).execute().data:
        code = gen_code()
    supabase.table("submission_codes").insert({
        "code": code,
        "created_by": user["user_id"],
        "school_id": user.get("school_id") or user.get("school_name"),
        "expires_at": (datetime.now(timezone.utc) + timedelta(days=30)).isoformat(),
        "max_uses": 10,
        "used_count": 0,
    }).execute()
    return {"code": code, "expires_in_days": 30, "max_uses": 10}

# Real fix Aug 19: the app's code-entry screen only ever did a client-side length check
# (code.length < 6) before letting a student proceed through the whole submit flow -
# details, emotion, 4 photo uploads - only to find out the code was invalid at the very
# last step. Same validation /creatures/submit already does (existence, use count,
# expiry), exposed standalone so the app can check it immediately, before any of that
# work happens.
@api_router.get("/creatures/validate-code/{code}")
async def validate_submission_code(code: str, request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    code = code.upper().strip()
    code_row = supabase.table("submission_codes").select("*").eq("code", code).execute()
    if not code_row.data:
        return {"valid": False, "reason": "Invalid code"}
    c = code_row.data[0]
    if c["used_count"] >= c["max_uses"]:
        return {"valid": False, "reason": "Code has been used too many times"}
    if datetime.fromisoformat(c["expires_at"].replace("Z", "+00:00")) < datetime.now(timezone.utc):
        return {"valid": False, "reason": "Code has expired"}
    return {"valid": True}

@api_router.get("/creatures/submission-options")
async def get_creature_submission_options(request: Request, real_student_id: Optional[str] = None):
    """Real feature Aug 22 (item 1): resolves what scope options are genuinely valid for a
    submission, so the frontend never has to guess from partial data. A real student with a
    resolved classroom can offer Classroom/School/Global; one with only a resolved school (no
    classroom) can offer School/Global; a home-only family member (no real_student_id, or one
    that resolves to neither) can only offer Global. Reuses the exact same
    _resolve_student_classroom_school + _is_authorized_for_student helpers the eligibility
    feed already depends on, so this is a single source of truth, not a second guess at the
    same logic."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    classroom_id, school_name = None, None
    if real_student_id:
        student_r = supabase.table("students").select("*").eq("id", real_student_id).execute()
        student_data = student_r.data[0] if student_r.data else None
        if student_data and await _is_authorized_for_student(user, real_student_id, student_data):
            classroom_id, school_name = _resolve_student_classroom_school(student_data)
    return {
        "has_classroom": bool(classroom_id),
        "has_school": bool(school_name),
        "school_name": school_name,
        "default_country": user.get("country") or "PT",
    }

@api_router.post("/creatures/submit")
async def submit_creature(request: Request):
    """Student submits a creature using 4 Supabase Storage URLs + a code."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    body = await request.json()
    code = body.get("code", "").upper().strip()
    emotion = body.get("emotion_colour", "").lower()
    if emotion not in ["green","blue","yellow","red"]:
        raise HTTPException(status_code=400, detail="Invalid emotion colour")
    # Validate code
    code_row = supabase.table("submission_codes").select("*").eq("code", code).execute()
    if not code_row.data:
        raise HTTPException(status_code=400, detail="Invalid code")
    c = code_row.data[0]
    if c["used_count"] >= c["max_uses"]:
        raise HTTPException(status_code=400, detail="Code has been used too many times")
    if datetime.fromisoformat(c["expires_at"].replace("Z","+00:00")) < datetime.now(timezone.utc):
        raise HTTPException(status_code=400, detail="Code has expired")
    # Check student hasn't already submitted this colour
    existing = supabase.table("creature_submissions").select("id")        .eq("student_id", user["user_id"])        .eq("emotion_colour", emotion)        .in_("status", ["pending","approved"])        .execute()
    if existing.data:
        raise HTTPException(status_code=400, detail=f"You already have a {emotion} creature submitted or approved")

    # Real feature Aug 24 (item 2, free-tier submission cap): mirrors the existing
    # free_tier_limit pattern used for students/classrooms/children - free accounts get 2
    # total submission tries, any status (Jono's explicit call: a rejection still counts as
    # a used try, not a free retry) across every colour/scope combined.
    if _is_genuinely_free_tier(user):
        submit_count = supabase.table("creature_submissions").select("id", count="exact").eq("student_id", user["user_id"]).execute()
        total_submitted = submit_count.count or len(submit_count.data or [])
        if total_submitted >= 2:
            raise HTTPException(
                status_code=403,
                detail="free_tier_limit|Free plan is limited to 2 creature submissions. Upgrade for unlimited creature submissions."
            )

    # Real fix Aug 21: "student_id" above has always actually been the SUBMITTING ACCOUNT's
    # own user_id (teacher or parent), never a real students.id - confirmed live, e.g. a
    # real "approved" row's student_id resolves to a users row with role=teacher, not any
    # students row at all. So there was never a reliable way to show which actual child made
    # a creature, or their classroom. real_student_id/classroom_id are a genuine new capture,
    # populated only when the submission screen's new student-picker step resolves one (a
    # school-linked family member or a teacher's own student both resolve to a real
    # students.id; a home-only family member has no classroom, only a name).
    real_student_id = body.get("real_student_id")
    classroom_id, school_name_resolved = None, None
    if real_student_id:
        student_r = supabase.table("students").select("*").eq("id", real_student_id).execute()
        student_data = student_r.data[0] if student_r.data else None
        if student_data and await _is_authorized_for_student(user, real_student_id, student_data):
            classroom_id, school_name_resolved = _resolve_student_classroom_school(student_data)

    # Real feature Aug 22 (item 1): submitter-chosen scope + country, resolved server-side
    # against the SAME real classroom/school data _resolve_student_classroom_school just
    # looked up - never trusted from the client directly. Requested scope is clamped down to
    # the widest option the real data actually supports; this becomes the submission's
    # initial visibility_scope, which superadmin's existing global-approve gate can still
    # freely override later - same two-gate authority as before, just no longer silently
    # defaulting to "school" with no submitter input at all.
    requested_scope = (body.get("visibility_scope") or "school").lower()
    if requested_scope not in ("classroom", "school", "global"):
        requested_scope = "school"
    # Real bug fix Aug 23: "classroom" used to be downgraded to "school"/"global" whenever
    # there was no real classroom_id - which meant it was NEVER a real option for a home-only
    # family submission (the common parent case). "classroom" is now always valid: real
    # classroom match when classroom_id exists, family-private match (see
    # get_eligible_creatures) when it doesn't - so no downgrade needed here any more.
    if requested_scope == "school" and not school_name_resolved:
        requested_scope = "global"

    submission = {
        "student_id": user["user_id"],
        "student_name": user.get("name", "Student"),
        "year_group": body.get("year_group", user.get("year_group", "")),
        "school_name": user.get("school_name", body.get("school_name", "")),
        "country": body.get("country", user.get("country", "PT")),
        "emotion_colour": emotion,
        "creature_name": body.get("name", "My Creature")[:50],
        "description": body.get("description", "")[:200],
        "stage1_url": body["stage1_url"],
        "stage2_url": body["stage2_url"],
        "stage3_url": body["stage3_url"],
        "stage4_url": body["stage4_url"],
        "submission_code": code,
        "status": "pending",
        "visibility_scope": requested_scope,
    }
    # Requires a migration this environment can't run (no DDL access) - see COH-REVIEW-PLAN.md.
    # Old submissions are NOT backfilled, by design - defensive fallback below means the
    # feature just silently doesn't capture this until the migration runs, without breaking
    # submission for anyone in the meantime.
    if real_student_id:
        try:
            result = supabase.table("creature_submissions").insert({
                **submission, "real_student_id": real_student_id, "classroom_id": classroom_id
            }).execute()
        except Exception as e:
            logger.warning(f"[creatures/submit] real_student_id/classroom_id columns not available yet, falling back: {e}")
            result = supabase.table("creature_submissions").insert(submission).execute()
    else:
        result = supabase.table("creature_submissions").insert(submission).execute()
    # Increment code usage
    supabase.table("submission_codes").update({"used_count": c["used_count"]+1}).eq("code", code).execute()
    return {"status": "submitted", "id": result.data[0]["id"], "message": "Your creature is under review!"}

@api_router.get("/creatures/pending")
async def get_pending_creatures(request: Request):
    """Teachers and school admin see their school's pending submissions. Parents see only
    their own family's pending submissions.
    Real bug fix Aug 22 (item 8c): parent used to fall into the same branch as school_admin
    and get the exact same school-wide moderation queue - a parent could see every other
    family's and every classroom's pending submissions at their school. Decided fix: parents
    are scoped to their own submissions only, matching the approval authority
    _can_approve_creature already gives them. See /creatures/my-submissions for the
    equivalent teacher/parent self-service status view - this endpoint stays the
    moderation-queue surface used by the approve/reject UI."""
    user = await get_current_user(request)
    role = user.get("role") if user else None
    if not user or role not in ["teacher","parent","school_admin","admin","superadmin"]:
        raise HTTPException(status_code=403, detail="Not authorised")
    if role == "superadmin":
        rows = supabase.table("creature_submissions").select("*").eq("status","pending").order("created_at").execute()
    elif role == "teacher":
        # Resolve the teacher's real school via school_admin_id (school_name is unreliable/unset)
        admin_r = supabase.table("users").select("school_admin_id").eq("user_id", user["user_id"]).execute()
        school_admin_id = (admin_r.data or [{}])[0].get("school_admin_id")
        school = ""
        if school_admin_id:
            profile_r = supabase.table("school_profiles").select("school_name").eq("school_admin_user_id", school_admin_id).execute()
            if profile_r.data:
                school = profile_r.data[0].get("school_name", "")
        # Real bug fix Aug 22: found live, during item 8 verification, testing this exact
        # endpoint against a real teacher account - school_profiles is confirmed empty in
        # production (same finding as the security fix), so `school` always resolved to ""
        # here and this endpoint has been silently returning zero pending submissions for
        # every real teacher, full stop. _can_approve_creature already got this same
        # fallback during the Aug 22 security fix; this endpoint never did. Without it, a
        # teacher's Pending Creatures queue shows nothing to review even when real
        # submissions are genuinely waiting at their school.
        if not school:
            school = user.get("school_name")
        rows = supabase.table("creature_submissions").select("*").eq("status","pending").eq("school_name", school).order("created_at").execute() if school else type("R",(),{"data":[]})()
    elif role == "parent":
        rows = supabase.table("creature_submissions").select("*").eq("status","pending").eq("student_id", user["user_id"]).order("created_at").execute()
    else:
        school = user.get("school_name", user.get("school_id", ""))
        rows = supabase.table("creature_submissions").select("*")            .eq("status","pending").eq("school_name", school).order("created_at").execute()
    data = rows.data or []

    # Real feature Aug 22 (item 8d): annotate each row with who submitted it (teacher vs
    # parent) so the school_admin/teacher moderation queue can distinguish them. No new
    # column needed - resolved with a batch lookup against users.role keyed on student_id
    # (the submitting account's own id, per the Aug 21 finding that this field never holds
    # a real students.id).
    student_ids = list({r["student_id"] for r in data if r.get("student_id")})
    role_map = {}
    if student_ids:
        users_r = supabase.table("users").select("user_id,role").in_("user_id", student_ids).execute()
        role_map = {u["user_id"]: u.get("role") for u in (users_r.data or [])}
    for r in data:
        r["submitted_by_role"] = role_map.get(r.get("student_id"), "unknown")

    # Real feature Aug 23 (item 4): resolve the REAL child a submission is for, not just
    # which account submitted it - see _annotate_real_student_names below.
    return _annotate_real_student_names(data)

async def _can_approve_creature(user: dict, submission: dict) -> bool:
    """Real bug fix Aug 22 (urgent security fix): /creatures/approve and /creatures/reject had
    ZERO ownership/school-scoping - any authenticated teacher/parent/school_admin could
    approve or reject ANY creature submission system-wide, not just ones at their own school.
    superadmin/admin keep unrestricted authority (matches their real final-approval role,
    unchanged). teacher/school_admin are now scoped to their own resolved school - same
    real-school resolution pattern already used by /creatures/pending. parent is scoped to
    their OWN submissions only (student_id == their account) - the safest, most conservative
    reading of "their own school" for an account type with no reliable school-affiliation
    field of its own; whether parents should instead get broader same-school moderation
    access (matching what the portal currently, incorrectly, already gives them) is a real
    open product question, deliberately not resolved by this urgent fix."""
    role = user.get("role")
    if role in ("superadmin", "admin"):
        return True
    if role == "teacher":
        # Real bug fix Aug 22: the school_admin_id -> school_profiles resolution used by
        # /creatures/pending is the "more correct" method, but school_profiles is confirmed
        # live to be essentially empty in production (one unusable row, no admin_id) - using
        # it as the ONLY path would silently lock out every real teacher, not just close the
        # security hole. Falls back to the teacher's own school_name field (imperfect, but
        # real and populated) rather than fail closed for everyone.
        school = None
        admin_r = supabase.table("users").select("school_admin_id").eq("user_id", user["user_id"]).execute()
        school_admin_id = (admin_r.data or [{}])[0].get("school_admin_id")
        if school_admin_id:
            profile_r = supabase.table("school_profiles").select("school_name").eq("school_admin_user_id", school_admin_id).execute()
            if profile_r.data:
                school = profile_r.data[0].get("school_name")
        if not school:
            school = user.get("school_name")
        return bool(school) and submission.get("school_name") == school
    if role == "school_admin":
        school = user.get("school_name") or user.get("school_id")
        return bool(school) and submission.get("school_name") == school
    if role == "parent":
        return submission.get("student_id") == user["user_id"]
    return False

@api_router.post("/creatures/approve/{submission_id}")
async def approve_creature(submission_id: str, request: Request):
    """Teacher, parent or school admin approves a creature submission."""
    user = await get_current_user(request)
    if not user or user.get("role") not in ["teacher","parent","school_admin","admin","superadmin"]:
        raise HTTPException(status_code=403, detail="Not authorised")
    sub_r = supabase.table("creature_submissions").select("school_name,student_id").eq("id", submission_id).execute()
    if not sub_r.data:
        raise HTTPException(status_code=404, detail="Submission not found")
    if not await _can_approve_creature(user, sub_r.data[0]):
        raise HTTPException(status_code=403, detail="You can only approve submissions at your own school")
    # Teacher/parent approval no longer auto-publishes globally — superadmin's
    # global-approve endpoint is the real second gate before anything is public.
    supabase.table("creature_submissions").update({
        "status": "approved",
        "approved_by": user["user_id"],
        "approved_at": datetime.now(timezone.utc).isoformat(),
    }).eq("id", submission_id).execute()
    return {"status": "approved"}

@api_router.post("/creatures/reject/{submission_id}")
async def reject_creature(submission_id: str, request: Request):
    user = await get_current_user(request)
    if not user or user.get("role") not in ["teacher","parent","school_admin","admin","superadmin"]:
        raise HTTPException(status_code=403, detail="Not authorised")
    sub_r = supabase.table("creature_submissions").select("school_name,student_id").eq("id", submission_id).execute()
    if not sub_r.data:
        raise HTTPException(status_code=404, detail="Submission not found")
    if not await _can_approve_creature(user, sub_r.data[0]):
        raise HTTPException(status_code=403, detail="You can only reject submissions at your own school")
    body = await request.json()
    supabase.table("creature_submissions").update({
        "status": "rejected",
        "rejection_reason": body.get("reason", "Does not meet the Class of Happiness standards"),
        "approved_by": user["user_id"],
    }).eq("id", submission_id).execute()
    return {"status": "rejected"}

@api_router.delete("/creatures/cancel/{submission_id}")
async def cancel_creature(submission_id: str, request: Request):
    """Superadmin can cancel any creature globally."""
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Superadmin only")
    supabase.table("creature_submissions").update({
        "status": "cancelled",
        "is_globally_available": False,
    }).eq("id", submission_id).execute()
    return {"status": "cancelled"}

@api_router.delete("/creatures/{submission_id}")
async def delete_creature(submission_id: str, request: Request):
    """Real feature Aug 23 (item 2, same portal-testing round as the featured-creature gap):
    superadmin previously had no real delete - only approve/reject, and a cancel_creature
    endpoint that existed in the backend but was never wired into any UI (soft-cancel only,
    row stays forever). Explicit real ask: remove inappropriate content that slipped
    through, and clean up test submissions - a soft "cancelled" status row sitting in the
    table forever doesn't satisfy either use case. This is a genuine hard delete: the
    submission row, any creature_unlocks referencing it (a student's real progress on a
    creature that no longer exists - can't be kept pointing at nothing), and any
    featured_creatures rows referencing it. Storage image cleanup is best-effort (never
    blocks the actual delete if it fails) since no prior code in this file has ever
    parsed a public Storage URL back into a bucket path - if that ever breaks, the DB
    cleanup (the part that actually matters for both stated use cases) still succeeds."""
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Superadmin only")

    existing = supabase.table("creature_submissions").select(
        "id,creature_name,stage1_url,stage2_url,stage3_url,stage4_url"
    ).eq("id", submission_id).execute()
    if not existing.data:
        raise HTTPException(status_code=404, detail="Submission not found")
    c = existing.data[0]

    supabase.table("creature_unlocks").delete().eq("creature_id", submission_id).execute()
    supabase.table("featured_creatures").delete().eq("creature_id", submission_id).execute()
    supabase.table("creature_submissions").delete().eq("id", submission_id).execute()

    deleted_images = 0
    try:
        marker = "/public/creature-images/"
        paths = []
        for field in ("stage1_url", "stage2_url", "stage3_url", "stage4_url"):
            url = c.get(field) or ""
            if marker in url:
                paths.append(url.split(marker, 1)[1])
        if paths:
            supabase.storage.from_("creature-images").remove(paths)
            deleted_images = len(paths)
    except Exception as e:
        logger.warning(f"[delete_creature] storage cleanup failed for {submission_id}, DB rows already deleted: {e}")

    return {"status": "deleted", "creature_name": c.get("creature_name"), "images_removed": deleted_images}

@api_router.get("/creatures/global")
async def get_global_creatures(request: Request):
    """Global feed of approved creatures — visible to all authenticated users. Real fix
    Aug 21: system-wide, not scoped to any one school (no school filter on this query) - so
    school_admin's "Approved Creatures" card and any superadmin view of the same data are
    already looking at the exact same list, not separate school-scoped/global versions."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    base_fields = ("id,creature_name,emotion_colour,student_name,school_name,country,year_group,"
                   "stage1_url,stage2_url,stage3_url,stage4_url,global_uses,approved_at,visibility_scope")
    # Real bug fix Aug 21: superadmin needs to see (and edit the scope of) ALL approved
    # creatures, including ones scoped to "school"/"classroom" (is_globally_available=False).
    # Everyone else keeps seeing only the is_globally_available=True subset - otherwise
    # changing a creature's scope away from "global" via the superadmin scope-editing dropdown
    # made it vanish from the very card the dropdown lives on.
    is_superadmin = user.get("role") == "superadmin"
    # Real bug fix Aug 23: found live during Jono's own portal testing of the safety fix -
    # this endpoint only ever checked status=="approved" (teacher/parent gate), same gap
    # class as get_eligible_creatures/start_creature/get_my_creatures, just missed in that
    # earlier pass. Confirmed live: 6 real teacher/parent-approved-only submissions were
    # showing here as "Approved Creatures" while simultaneously still sitting in
    # "Awaiting Final Approval" - the two queues are meant to be mutually exclusive.
    # superadmin_approved_at gates this the same way as the other surfaces; fails closed
    # (empty) if the migration column is somehow unavailable, matching the same safety
    # direction as everywhere else this signal is used.
    try:
        query = supabase.table("creature_submissions").select(
            base_fields + ",real_student_id,classroom_id,superadmin_approved_at"
        ).eq("status","approved")
        if not is_superadmin:
            query = query.eq("is_globally_available", True)
        rows = query.order("global_uses", desc=True).limit(50).execute()
        has_approval_gate = True
    except Exception:
        rows = type("R", (), {"data": []})()
        has_approval_gate = False
    creatures = [c for c in (rows.data or []) if has_approval_gate and c.get("superadmin_approved_at")]
    creature_ids = [c["id"] for c in creatures]

    # Resolve classroom names for whichever creatures have a real classroom_id captured
    classroom_ids = list({c["classroom_id"] for c in creatures if c.get("classroom_id")})
    classroom_names = {}
    if classroom_ids:
        cls_r = supabase.table("classrooms").select("id,name").in_("id", classroom_ids).execute()
        classroom_names = {cl["id"]: cl["name"] for cl in (cls_r.data or [])}
    for c in creatures:
        c["classroom_name"] = classroom_names.get(c.get("classroom_id"))

    # Real feature Aug 21: per-creature "times fully evolved by other students" - same
    # underlying data/pattern already used in /creatures/analytics' aggregate top-users/
    # top-schools view (stages_unlocked==4 = fully evolved), just grouped by creature_id
    # instead. Unlock rows only ever come from students who aren't the original creator
    # (creators get their own creature via student_rewards, a separate mechanism), so this
    # is already correctly "by other students" with no extra filtering needed.
    evolved_counts = {}
    if creature_ids:
        unlocks_r = supabase.table("creature_unlocks").select("creature_id").eq("stages_unlocked", 4).in_("creature_id", creature_ids).execute()
        for u in (unlocks_r.data or []):
            cid = u.get("creature_id")
            if cid:
                evolved_counts[cid] = evolved_counts.get(cid, 0) + 1

    # Real feature Aug 21: expiry only applies to a creature currently featured - not
    # tracked at all otherwise, matching how featured_creatures.active_until already works
    # for the separate "Feature a Creature This Month" card.
    featured_map = {}
    if creature_ids:
        now = datetime.now(timezone.utc).isoformat()
        featured_r = supabase.table("featured_creatures").select("creature_id,active_until").lte("active_from", now).gte("active_until", now).in_("creature_id", creature_ids).execute()
        for f in (featured_r.data or []):
            cid = f.get("creature_id")
            if cid:
                featured_map[cid] = f.get("active_until")

    for c in creatures:
        c["times_fully_evolved"] = evolved_counts.get(c["id"], 0)
        c["featured_until"] = featured_map.get(c["id"])

    return creatures

@api_router.get("/creatures/global/by-country")
async def get_global_creatures_by_country(request: Request):
    """Real bug fix Aug 29: the World Creature Gallery ("Aggregated, anonymised, no student
    data shown") was actually implemented by fetching the full /creatures/global response -
    which genuinely includes student_name and real_student_id, needed by the legitimate
    Approved Creatures moderation view that also uses that endpoint - into the browser, and
    only using the country field client-side (portal's saWorldGallery, app's countryGallery).
    The names/IDs never rendered, but they were still sitting in the actual network response
    and browser memory, for a feature that explicitly promises no student data. This endpoint
    aggregates server-side instead - never returns anything but country name and creature
    count, for anyone, ever.

    Also fixes a second, real bug found in the same investigation: the "5-contributor
    threshold" was actually a 5-CREATURE-COUNT threshold - a single unusually active student
    submitting 5+ creatures from a small country could pass it alone, with zero real
    contributor anonymity. Now counts distinct real_student_id per country, matching what the
    threshold was always supposed to mean.

    Deliberately NOT capped at 50 / not ordered by global_uses like /creatures/global is -
    that endpoint's cap only makes sense for its own "top creatures" purpose; this needs every
    real approved creature to aggregate country counts correctly.

    Extended Aug 29 for the interactive World Creature Gallery map (A68): each country entry
    now also carries a real, per-creature `creatures` list (name, stage art, usage counts) and
    a `top_creature` (the country's own most-adopted one, for the map pin's icon) - still never
    anything but creature_name/stage art/usage numbers, the same threshold gate as before still
    applies at the country level, and the underlying real_student_id used for that gate is
    computed here and never included in any returned object."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    try:
        rows = supabase.table("creature_submissions").select(
            "id,country,real_student_id,superadmin_approved_at,creature_name,emotion_colour,"
            "stage1_url,stage2_url,stage3_url,stage4_url,global_uses"
        ).eq("status", "approved").execute()
        has_approval_gate = True
    except Exception:
        rows = type("R", (), {"data": []})()
        has_approval_gate = False
    creatures = [c for c in (rows.data or []) if has_approval_gate and c.get("superadmin_approved_at")]
    creature_ids = [c["id"] for c in creatures]

    # Same "times fully evolved by other students" pattern as /creatures/global.
    evolved_counts = {}
    if creature_ids:
        unlocks_r = supabase.table("creature_unlocks").select("creature_id").eq("stages_unlocked", 4).in_("creature_id", creature_ids).execute()
        for u in (unlocks_r.data or []):
            cid = u.get("creature_id")
            if cid:
                evolved_counts[cid] = evolved_counts.get(cid, 0) + 1

    by_country = {}
    for c in creatures:
        country = c.get("country")
        if not country:
            continue
        entry = by_country.setdefault(country, {"creature_count": 0, "contributors": set(), "creatures": []})
        entry["creature_count"] += 1
        if c.get("real_student_id"):
            entry["contributors"].add(c["real_student_id"])
        entry["creatures"].append({
            "id": c["id"],
            "creature_name": c.get("creature_name") or "Unnamed",
            "emotion_colour": c.get("emotion_colour"),
            "stage1_url": c.get("stage1_url"), "stage2_url": c.get("stage2_url"),
            "stage3_url": c.get("stage3_url"), "stage4_url": c.get("stage4_url"),
            "global_uses": c.get("global_uses") or 0,
            "times_fully_evolved": evolved_counts.get(c["id"], 0),
        })

    MIN_DISTINCT_CONTRIBUTORS = 5
    result = []
    for country, entry in by_country.items():
        if len(entry["contributors"]) < MIN_DISTINCT_CONTRIBUTORS:
            continue
        creatures_sorted = sorted(entry["creatures"], key=lambda x: -x["global_uses"])
        result.append({
            "country": country,
            "creature_count": entry["creature_count"],
            "top_creature": creatures_sorted[0] if creatures_sorted else None,
            "creatures": creatures_sorted,
        })
    result.sort(key=lambda r: -r["creature_count"])
    return result

@api_router.get("/creatures/eligible")
async def get_eligible_creatures(request: Request, student_id: Optional[str] = None):
    """Real feature Aug 21: the actual student-facing feed — approved creatures this
    specific student is eligible to see/pursue given their classroom/school and each
    creature's visibility_scope, annotated with the caller's own unlock progress. Privacy
    fix (ClassDojo precedent, explicitly requested): peer creator identity (student_name,
    school_name, country) is NEVER included here - only in /creatures/global, which is
    admin/superadmin/school_admin-only moderation tooling, not student-facing.
    If student_id is omitted (or the caller isn't authorized for it), falls back to
    global-scope-only creatures so this never breaks for an unresolvable caller."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    classroom_id, school_name = None, None
    authorized_student_id = None
    scope_pref = "any"
    if student_id:
        student_r = supabase.table("students").select("*").eq("id", student_id).execute()
        student_data = student_r.data[0] if student_r.data else None
        if student_data and await _is_authorized_for_student(user, student_id, student_data):
            classroom_id, school_name = _resolve_student_classroom_school(student_data)
            authorized_student_id = student_id
            scope_pref = student_data.get("creature_scope_pref") or "any"

    base_fields = ("id,creature_name,emotion_colour,stage1_url,stage2_url,stage3_url,stage4_url,"
                   "global_uses,approved_at,visibility_scope,school_name,classroom_id,country,student_id")
    # URGENT real security fix Aug 23 (corrected): superadmin_approved_at is a genuine new
    # column (global_uses turned out to have a DB default of 0, never actually NULL - see
    # global_approve_creature). If the migration hasn't landed yet, fail CLOSED - nothing is
    # eligible - rather than silently falling back to the old, unsafe status-only check.
    try:
        rows = supabase.table("creature_submissions").select(base_fields + ",superadmin_approved_at").eq("status", "approved").execute()
        has_approval_gate = True
    except Exception:
        rows = type("R", (), {"data": []})()
        has_approval_gate = False
    all_approved = rows.data or []

    # Real feature Aug 22: country-of-origin, global-scope creatures only, gated behind the
    # same real 5-contributor privacy threshold already used on the superadmin dashboard
    # (portal100.html's MIN_THRESHOLD) - showing a single creature's country when it's the
    # only one from that country would narrow down who made it. Computed across the full
    # global population, not just this student's eligible subset, to match the real
    # anonymity set the threshold is meant to protect.
    from collections import Counter
    global_country_counts = Counter(
        c.get("country") for c in all_approved
        if (c.get("visibility_scope") or "global") == "global" and c.get("country")
    )
    COUNTRY_MIN_THRESHOLD = 5
    safe_countries = {country for country, count in global_country_counts.items() if count >= COUNTRY_MIN_THRESHOLD}

    eligible = []
    for c in all_approved:
        # URGENT real security/product fix Aug 23: this loop only ever checked
        # status=="approved" (the teacher/parent gate, applied above via .eq("status",
        # "approved")) - superadmin's second gate (global_approve_creature) was never
        # actually enforced on this, the real student-facing read path. It only ever set
        # visibility_scope/is_globally_available, which affects WHICH scope a creature shows
        # under, not WHETHER it's visible at all - so a teacher/parent-only-approved
        # creature was immediately eligible to every matching student, completely bypassing
        # superadmin. Applies to every scope branch below, not just global - a
        # classroom/school/family-scoped creature needs superadmin's sign-off exactly as
        # much as a global one does.
        # CORRECTED same day: the first attempt at this fix used global_uses as the gate
        # signal, on the assumption it was NULL until superadmin acted. Live-verified false -
        # global_uses has a DB-level default of 0, confirmed 0 on a truly-fresh, zero-approval
        # submission - it's a pre-existing popularity counter, never a usable approval gate,
        # and that first fix was a silent no-op. superadmin_approved_at is a genuine new
        # column (see global_approve_creature) that only that one action ever sets. If the
        # migration hasn't landed yet (has_approval_gate False), this fails CLOSED - nothing
        # eligible - rather than repeat the same mistake in a new shape.
        if not has_approval_gate or not c.get("superadmin_approved_at"):
            continue
        scope = c.get("visibility_scope") or "global"
        # Real feature Aug 21: student scope-preference (classroom/school/global/any) - once
        # eligibility is computed as before, further narrow to just the preferred scope unless
        # the student wants "any" (the default). A creature must still pass the real
        # classroom/school/global eligibility check below regardless of preference - the
        # preference can only narrow what's shown, never widen it beyond what's genuinely
        # eligible.
        if scope_pref != "any" and scope != scope_pref:
            continue
        if scope == "global":
            eligible.append(c)
        elif scope == "school" and school_name and c.get("school_name") == school_name:
            eligible.append(c)
        elif scope == "classroom" and classroom_id and c.get("classroom_id") == classroom_id:
            eligible.append(c)
        # Real bug fix Aug 23 (parent scope options): "classroom" scope only ever matched a
        # real classroom_id - for a home-only family member (no classroom at all, the common
        # parent case), a "classroom"-scoped submission was eligible to NOBODY, not even the
        # family that made it, since `classroom_id and ...` short-circuits false whenever the
        # browsing student has none either. This is the real reason parents only ever saw
        # "Global" in the submission-time scope picker - "classroom"/"Family" scope was
        # silently non-functional for exactly the account type it would matter most for.
        # Fix: when NEITHER side has a real classroom, "classroom" scope now means
        # family-private - eligible only to the same account that submitted it. Deliberately
        # narrow (this one login, not "every parent linked to this child") - matches the
        # plain reading of "family" for an unlinked, home-only household.
        elif scope == "classroom" and not classroom_id and not c.get("classroom_id") and c.get("student_id") == user["user_id"]:
            eligible.append(c)

    creature_ids = [c["id"] for c in eligible]
    my_unlocks = {}
    if creature_ids:
        unlocks_r = _creature_unlocks_for(user["user_id"], authorized_student_id, creature_ids)
        for u in (unlocks_r.data or []):
            my_unlocks[u["creature_id"]] = u.get("stages_unlocked", 0)

    classroom_ids = list({c["classroom_id"] for c in eligible if c.get("classroom_id")})
    classroom_names = {}
    if classroom_ids:
        cls_r = supabase.table("classrooms").select("id,name").in_("id", classroom_ids).execute()
        classroom_names = {cl["id"]: cl["name"] for cl in (cls_r.data or [])}

    # Real feature Aug 22: expiry date wasn't shown anywhere - a creature currently featured
    # (this month's spotlight pick) has a real active_until window; students need to see it to
    # know they have a limited time to earn it.
    featured_map = {}
    if creature_ids:
        now_iso = datetime.now(timezone.utc).isoformat()
        featured_r = supabase.table("featured_creatures").select("creature_id,active_until")            .lte("active_from", now_iso).gte("active_until", now_iso).in_("creature_id", creature_ids).execute()
        for f in (featured_r.data or []):
            fid = f.get("creature_id")
            if fid:
                featured_map[fid] = f.get("active_until")

    # Real feature Aug 24 (item 1, free-tier collection cap): locked creatures still need to
    # show up here (faded, not hidden - Jono's explicit spec) rather than being filtered out,
    # so the frontend gets a real "locked" flag per creature instead of a bare exclusion.
    # Computed once per request, not per-creature - _free_tier_colour_locks is one query pair.
    free_tier_locks = _free_tier_colour_locks(user["user_id"], authorized_student_id) if _is_genuinely_free_tier(user) else {}

    result = []
    for c in eligible:
        scope = c.get("visibility_scope") or "global"
        locked_id = free_tier_locks.get(c["emotion_colour"])
        result.append({
            "id": c["id"],
            "creature_name": c["creature_name"],
            "emotion_colour": c["emotion_colour"],
            "stage1_url": c.get("stage1_url"),
            "stage2_url": c.get("stage2_url"),
            "stage3_url": c.get("stage3_url"),
            "stage4_url": c.get("stage4_url"),
            "global_uses": c.get("global_uses", 0),
            "visibility_scope": scope,
            "classroom_name": classroom_names.get(c.get("classroom_id")),
            "my_stages_unlocked": my_unlocks.get(c["id"], 0),
            "featured_until": featured_map.get(c["id"]),
            "country": c.get("country") if scope == "global" and c.get("country") in safe_countries else None,
            "locked": bool(locked_id) and locked_id != c["id"],
        })
    # Real feature Aug 23 (item 8): aggregate teaser count - "X countries have joined" -
    # reuses safe_countries (already computed above, zero extra query) so it only ever
    # counts countries that have genuinely cleared the same 5-contributor threshold that
    # protects individual creature country reveals. Never leaks a below-threshold country by
    # counting it - the whole point is showing momentum without ever risking identification.
    return {"creatures": result, "scope_pref": scope_pref, "has_classroom": bool(classroom_id), "countries_joined": len(safe_countries)}

@api_router.get("/creatures/country-leaderboard")
async def get_creature_country_leaderboard(request: Request):
    """Real feature Aug 23 (item 3, the deferred "creatures per country" leaderboard/graph
    from item 5 of the Aug 22 round - see COH-REVIEW-PLAN.md): student-facing UI on the exact
    same k-anonymity computation already proven for get_eligible_creatures' countries_joined
    teaser and portal100.html's world map (MIN_THRESHOLD=5). Global-scope, superadmin-approved
    creatures only, counted by country. A country below the threshold is never shown
    individually - not even dropped, since a dropped count would still shrink the visible
    total in a way that could be reasoned about - it's folded into a single "Rest of World"
    bucket instead, so the leaderboard's total always matches the real worldwide count with
    zero individual-identification risk, resolving Jono's "bucket sub-5 into rest of world"
    decision."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        rows = supabase.table("creature_submissions").select(
            "country,visibility_scope,superadmin_approved_at"
        ).eq("status", "approved").execute()
        approved = rows.data or []
    except Exception:
        approved = []

    from collections import Counter
    counts = Counter(
        c.get("country") for c in approved
        if c.get("superadmin_approved_at")
        and (c.get("visibility_scope") or "global") == "global"
        and c.get("country")
    )

    THRESHOLD = 5
    leaderboard = [{"country": country, "count": count} for country, count in counts.items() if count >= THRESHOLD]
    leaderboard.sort(key=lambda x: -x["count"])
    rest_of_world = sum(count for count in counts.values() if count < THRESHOLD)
    if rest_of_world > 0:
        leaderboard.append({"country": "Rest of World", "count": rest_of_world})

    return {
        "leaderboard": leaderboard,
        "total_countries": len(counts),
        "total_creatures": sum(counts.values()),
    }

