@api_router.post("/creatures/feature/{submission_id}")
async def feature_creature(submission_id: str, request: Request):
    """Teacher or school admin features a creature for their school this month."""
    user = await get_current_user(request)
    if not user or user.get("role") not in ["teacher","school_admin","admin","superadmin"]:
        raise HTTPException(status_code=403, detail="Not authorised")
    # Get creature info
    creature = supabase.table("creature_submissions").select("*").eq("id", submission_id).execute()
    if not creature.data or creature.data[0]["status"] != "approved":
        raise HTTPException(status_code=400, detail="Creature not found or not approved")
    c = creature.data[0]
    # Real bug fix Aug 23: found alongside get_global_creatures - a teacher/school_admin
    # could feature (spotlight, this school or wider, for the whole month) a creature
    # superadmin had never signed off on, same gap class as the urgent safety fix. Confirmed
    # live: "Waterman" was actively featured (through 2026-08-31) despite never being
    # superadmin-approved. Same superadmin_approved_at gate as everywhere else.
    if not c.get("superadmin_approved_at"):
        raise HTTPException(status_code=400, detail="This creature needs superadmin's final approval before it can be featured")
    # Deactivate existing featured for same school + colour
    supabase.table("featured_creatures").update({
        "active_until": datetime.now(timezone.utc).isoformat()
    }).eq("featured_by", user["user_id"]).eq("emotion_colour", c["emotion_colour"])        .gte("active_until", datetime.now(timezone.utc).isoformat()).execute()
    # Feature this one
    now = datetime.now(timezone.utc)
    _, last_day = calendar.monthrange(now.year, now.month)
    month_end = now.replace(day=last_day, hour=23, minute=59, second=59)
    result = supabase.table("featured_creatures").insert({
        "creature_id": submission_id,
        "emotion_colour": c["emotion_colour"],
        "featured_by": user["user_id"],
        "school_id": user.get("school_name",""),
        "active_from": now.isoformat(),
        "active_until": month_end.isoformat(),
    }).execute()
    return {"status": "featured", "expires": month_end.isoformat()}

@api_router.post("/creatures/unlock/{submission_id}")
async def unlock_creature_stage(submission_id: str, request: Request):
    """Student unlocks next stage of a featured creature."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real feature Aug 21: optional real_student_id in the body lets the new eligible-creatures
    # UI enforce that a student can only unlock a creature they're actually eligible to see
    # (their classroom/school matches the creature's visibility_scope, or it's global). If no
    # real_student_id is sent, skip this check - preserves old behaviour for any other caller.
    try:
        body = await request.json()
    except Exception:
        body = {}
    real_student_id = body.get("real_student_id") if isinstance(body, dict) else None

    # Real bug fix Aug 21: fetch the creature (incl. its own colour) unconditionally, not just
    # inside the real_student_id branch - needed below to filter check-ins by matching colour.
    creature_r = supabase.table("creature_submissions").select(
        "visibility_scope,school_name,classroom_id,status,emotion_colour,creature_name,stage4_url"
    ).eq("id", submission_id).execute()
    if not creature_r.data or creature_r.data[0].get("status") != "approved":
        raise HTTPException(status_code=404, detail="Creature not found")
    creature = creature_r.data[0]

    if real_student_id:
        student_r = supabase.table("students").select("*").eq("id", real_student_id).execute()
        student_data = student_r.data[0] if student_r.data else None
        if not student_data or not await _is_authorized_for_student(user, real_student_id, student_data):
            raise HTTPException(status_code=403, detail="Not authorized for this student")
        classroom_id, school_name = _resolve_student_classroom_school(student_data)
        scope = creature.get("visibility_scope") or "global"
        is_eligible = (
            scope == "global"
            or (scope == "school" and school_name and creature.get("school_name") == school_name)
            or (scope == "classroom" and classroom_id and creature.get("classroom_id") == classroom_id)
        )
        if not is_eligible:
            raise HTTPException(status_code=403, detail="This creature isn't available to this student")
        # Real bug fix Aug 21: enforce the new one-active-creature-per-colour rule server-side,
        # not just in the UI - a student may only progress the creature that's genuinely their
        # active pursuit for this colour. Closes a bypass where this endpoint, called directly,
        # could progress a creature that was never actually "started" via /creatures/start.
        active = _get_active_creatures(student_data)
        if active.get(creature.get("emotion_colour")) != submission_id:
            raise HTTPException(status_code=403, detail="This isn't your active creature for this colour yet - set it as active first.")

    # Real bug fix Aug 21: this function's whole body used to be duplicated between here and
    # add_points' check-in-driven path - now both share _progress_community_creature, which
    # already includes the colour-filtered check-in count fix and the expiry-snapshot capture.
    result = _progress_community_creature(real_student_id or user["user_id"], submission_id)
    if result is None:
        raise HTTPException(status_code=404, detail="Creature not found")
    if result["is_complete"] and not result["evolved"]:
        return {"stages_unlocked": 4, "message": "Already fully unlocked!"}
    if not result["evolved"]:
        return {
            "stages_unlocked": result["current_stage"],
            "needed": result["needed_for_next"],
            "message": f"Do {result['needed_for_next']} more check-ins to unlock stage {result['current_stage']+1}!",
        }
    return {"stages_unlocked": result["current_stage"], "message": f"Stage {result['current_stage']} unlocked!"}

@api_router.post("/creatures/start/{submission_id}")
async def start_creature(submission_id: str, request: Request):
    """Real feature Aug 21: a student picks a community creature to become their active
    pursuit for its colour - this is a SELECTION, not progress. Progress then happens
    automatically through normal check-ins (same as the default per-colour creatures always
    have), via add_points routing to whichever creature is active. Gated: the creature must
    match the target colour (implicit - a creature only ever belongs to its own colour slot),
    the student must be eligible to see it (classroom/school/global), and their CURRENTLY
    active creature for that colour must already be fully evolved - "one active creature per
    colour, choose the next only once you've finished the current one," per Jono's explicit
    rule (this replaces the earlier multi-simultaneous-progress behaviour)."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    body = await request.json()
    real_student_id = body.get("real_student_id")
    if not real_student_id:
        raise HTTPException(status_code=400, detail="real_student_id is required")

    student_r = supabase.table("students").select("*").eq("id", real_student_id).execute()
    student_data = student_r.data[0] if student_r.data else None
    if not student_data or not await _is_authorized_for_student(user, real_student_id, student_data):
        raise HTTPException(status_code=403, detail="Not authorized for this student")

    try:
        creature_r = supabase.table("creature_submissions").select(
            "visibility_scope,school_name,classroom_id,status,emotion_colour,creature_name,student_id,superadmin_approved_at"
        ).eq("id", submission_id).execute()
        has_approval_gate = True
    except Exception:
        creature_r = type("R", (), {"data": []})()
        has_approval_gate = False
    if not creature_r.data or creature_r.data[0].get("status") != "approved":
        raise HTTPException(status_code=404, detail="Creature not found")
    creature = creature_r.data[0]
    # URGENT real security/product fix Aug 23 (corrected same day - see
    # get_eligible_creatures for the full writeup on why global_uses never worked as a gate):
    # same gap, same real fix. A student could START (create a real creature_unlocks row,
    # appear in My Creatures/rewards) a creature the moment a teacher or parent approved it,
    # fully bypassing superadmin. Fails CLOSED if the migration hasn't landed yet.
    if not has_approval_gate or not creature.get("superadmin_approved_at"):
        raise HTTPException(status_code=404, detail="Creature not found")
    colour = creature.get("emotion_colour")

    classroom_id, school_name = _resolve_student_classroom_school(student_data)
    scope = creature.get("visibility_scope") or "global"
    is_eligible = (
        scope == "global"
        or (scope == "school" and school_name and creature.get("school_name") == school_name)
        or (scope == "classroom" and classroom_id and creature.get("classroom_id") == classroom_id)
        # Real bug fix Aug 23: this endpoint never got the family-private matching branch
        # added to get_eligible_creatures earlier today - a home-only family's own
        # "classroom"/Family-scoped creature couldn't be started at all, browse-eligible or
        # not. Same fix, same reasoning: no real classroom on either side means
        # family-private, matched by the submitting account.
        or (scope == "classroom" and not classroom_id and not creature.get("classroom_id") and creature.get("student_id") == user["user_id"])
    )
    if not is_eligible:
        raise HTTPException(status_code=403, detail="This creature isn't available to this student")

    active = _get_active_creatures(student_data)
    current_active = active.get(colour)
    if current_active == submission_id:
        return {"active_creatures": active, "message": "Already your active creature for this colour."}
    if not _is_creature_fully_evolved(student_data, current_active, real_student_id):
        raise HTTPException(
            status_code=400,
            detail="You need to fully evolve your current creature for this colour before starting a new one."
        )

    # Real feature Aug 24 (item 1, free-tier collection cap): the check just above already
    # lets a student cycle through creatures for a colour one at a time, fully evolving each
    # before moving to the next - this additionally caps how many they can ever collect per
    # colour when NOT subscribed. Once a free-tier account has fully evolved one creature for
    # this colour, they can't move on to a genuinely different one. Subscribed/school-covered
    # accounts are unaffected - same unlimited behaviour as before.
    if _is_genuinely_free_tier(user):
        locks = _free_tier_colour_locks(user["user_id"], real_student_id)
        locked_creature_id = locks.get(colour)
        if locked_creature_id and locked_creature_id != submission_id:
            raise HTTPException(
                status_code=403,
                detail="free_tier_limit|Free plan is limited to one fully-evolved creature per colour. Upgrade for unlimited community creatures."
            )

    active[colour] = submission_id
    try:
        supabase.table("students").update({"active_creatures": active}).eq("id", real_student_id).execute()
    except Exception as e:
        raise HTTPException(status_code=400, detail="Starting a new creature isn't available yet - migration pending")

    # Real feature Aug 21: create the creature_unlocks row immediately at start time (stage 0)
    # rather than waiting for the first check-in threshold to be met, so "started_at" (the
    # row's unlocked_at) genuinely reflects when the student chose this creature, not when
    # they first made enough progress to move it to stage 1 - matters for the collection
    # view's "when they started it" requirement.
    existing = _creature_unlocks_for(user["user_id"], real_student_id, [submission_id])
    if not existing.data:
        new_row = {"student_id": user["user_id"], "creature_id": submission_id, "stages_unlocked": 0}
        try:
            supabase.table("creature_unlocks").insert({**new_row, "real_student_id": real_student_id}).execute()
        except Exception:
            pass

    return {"active_creatures": active, "message": f"{creature.get('creature_name')} is now your active {colour} creature!"}

@api_router.get("/creatures/my-unlocks")
async def get_my_unlocks(request: Request, student_id: Optional[str] = None):
    """Student sees all creatures they've started unlocking. Real feature Aug 21: optional
    student_id (a real students.id) scopes this to one specific student instead of the whole
    account, once real_student_id-keyed rows exist for them - see _creature_unlocks_for.
    Privacy fix: peer creator identity is stripped here too, same as /creatures/eligible -
    a creature in your own collection may have been made by another student."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    real_student_id = None
    if student_id:
        student_r = supabase.table("students").select("*").eq("id", student_id).execute()
        student_data = student_r.data[0] if student_r.data else None
        if student_data and await _is_authorized_for_student(user, student_id, student_data):
            real_student_id = student_id
    select_fields = "*, creature_submissions(id,creature_name,emotion_colour,stage1_url,stage2_url,stage3_url,stage4_url)"
    if real_student_id:
        try:
            rows = supabase.table("creature_unlocks").select(select_fields).eq("real_student_id", real_student_id).execute()
            return rows.data or []
        except Exception:
            pass
    rows = supabase.table("creature_unlocks").select(select_fields).eq("student_id", user["user_id"]).execute()
    return rows.data or []

@api_router.get("/students/{student_id}/active-creatures")
async def get_active_creatures_endpoint(student_id: str, request: Request):
    """Real feature Aug 21: lets the frontend check, per colour, which creature is active and
    whether it's fully evolved yet - drives whether World Creatures shows "Set as Active"
    (enabled) or a locked/disabled state ("finish your current one first")."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    student_r = supabase.table("students").select("*").eq("id", student_id).execute()
    student_data = student_r.data[0] if student_r.data else None
    if not student_data or not await _is_authorized_for_student(user, student_id, student_data):
        raise HTTPException(status_code=403, detail="Not authorized for this student")
    active = _get_active_creatures(student_data)
    result = {}
    for colour, active_id in active.items():
        result[colour] = {
            "active_id": active_id,
            "is_default": active_id in DEFAULT_CREATURE_IDS,
            "is_fully_evolved": _is_creature_fully_evolved(student_data, active_id, student_id),
            # Real feature Aug 27 (item 12): drives the press-and-hold progress ring on
            # world-creatures.tsx's active card. See _creature_progress_percent's docstring.
            "progress_percent": _creature_progress_percent(active_id, student_id, colour),
        }
    return result

@api_router.get("/students/{student_id}/my-creatures")
async def get_my_creatures(student_id: str, request: Request):
    """Real feature Aug 21: the permanent "My Creatures" collection - Pokedex-style, not a
    single current-creature slot. Every creature a student has ever started or fully evolved,
    default or community, grouped by colour, with a real total-collected count. A creature
    that stops being "active" is NEVER removed from this view - its final state (points/
    stage for defaults, snapshot for community) just stays as permanent history."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    student_r = supabase.table("students").select("*").eq("id", student_id).execute()
    student_data = student_r.data[0] if student_r.data else None
    if not student_data or not await _is_authorized_for_student(user, student_id, student_data):
        raise HTTPException(status_code=403, detail="Not authorized for this student")

    active = _get_active_creatures(student_data)

    rewards_r = supabase.table("student_rewards").select("creature_stages,creature_points").eq("student_id", student_id).execute()
    creature_stages = (rewards_r.data[0].get("creature_stages") if rewards_r.data else None) or {}
    creature_points = (rewards_r.data[0].get("creature_points") if rewards_r.data else None) or {}
    creatures_map = {c["id"]: c for c in CREATURES}

    buckets = {"blue": [], "green": [], "yellow": [], "red": []}
    total_collected = 0

    for colour, default_id in FEELING_COLOUR_MAP.items():
        cdata = creatures_map.get(default_id, {})
        stage = creature_stages.get(default_id, 0)
        is_complete = stage >= 3
        if is_complete:
            total_collected += 1
        buckets[colour].append({
            "type": "default",
            "id": default_id,
            "name": cdata.get("name"),
            "emoji": (cdata.get("stages") or [{}])[min(stage, 3)].get("emoji") if cdata.get("stages") else None,
            "current_stage": stage,
            "max_stage": 3,
            "is_complete": is_complete,
            "is_active": active.get(colour) == default_id,
            "points": creature_points.get(default_id, 0),
            # Real feature Aug 22 (item 2 visual polish): full per-stage emoji list, so the
            # detail view can show the whole evolution row (egg -> full creature), not just
            # the current stage - same real data _get_collection already exposes for the old
            # modal, just not previously threaded through this endpoint.
            "stage_emojis": [s.get("emoji") for s in (cdata.get("stages") or [])],
        })

    # URGENT real security/product fix Aug 23 (corrected same day - see
    # get_eligible_creatures): joined select fails as one unit if superadmin_approved_at
    # doesn't exist yet, which lands in the except below and fails CLOSED (unlock_rows = [],
    # nothing displays) - the right direction to fail in, unlike the earlier global_uses
    # attempt which looked gated but never actually was.
    try:
        unlocks_r = supabase.table("creature_unlocks").select(
            "*, creature_submissions(id,creature_name,emotion_colour,stage1_url,stage2_url,stage3_url,stage4_url,visibility_scope,status,superadmin_approved_at)"
        ).eq("real_student_id", student_id).execute()
        unlock_rows = unlocks_r.data or []
    except Exception:
        unlock_rows = []
    for u in unlock_rows:
        cs = u.get("creature_submissions")
        if not cs:
            continue
        # A creature a student already started stays in creature_unlocks (real progress,
        # never deleted), but shouldn't display in My Creatures/rewards unless superadmin
        # has actually signed off.
        if not cs.get("superadmin_approved_at") or cs.get("status") != "approved":
            continue
        colour = cs.get("emotion_colour")
        if colour not in buckets:
            continue
        stages_unlocked = u.get("stages_unlocked", 0) or 0
        is_complete = stages_unlocked >= 4
        if is_complete:
            total_collected += 1
        name = (is_complete and u.get("creature_name_snapshot")) or cs.get("creature_name")
        stage_img = (is_complete and u.get("stage_image_snapshot")) or cs.get(f"stage{max(1, min(stages_unlocked, 4))}_url") or cs.get("stage1_url")
        buckets[colour].append({
            "type": "community",
            "id": cs["id"],
            "name": name,
            "stage_image": stage_img,
            "current_stage": stages_unlocked,
            "max_stage": 4,
            "is_complete": is_complete,
            "is_active": active.get(colour) == cs["id"],
            "started_at": u.get("unlocked_at"),
            "completed_at": u.get("completed_at"),
            "was_featured": u.get("was_featured", False),
            "featured_until": u.get("featured_until_snapshot"),
            # Real feature Aug 22 (item 2 visual polish): full per-stage photo URLs, so the
            # detail view can show the whole evolution row the same way a default creature's
            # stage_emojis does - the photos already exist on the submission row, just weren't
            # threaded through this endpoint before.
            "stage_urls": [cs.get("stage1_url"), cs.get("stage2_url"), cs.get("stage3_url"), cs.get("stage4_url")],
        })

    return {"colours": buckets, "total_collected": total_collected}

def _annotate_real_student_names(rows: list) -> list:
    """Real feature Aug 23 (item 4): "student_name" on a submission row has always actually
    been the SUBMITTING ACCOUNT's own display name (teacher or parent), never the real
    child's - a reviewer needs to know which real child a creature is for, not just who
    logged in to submit it. Shared by /creatures/my-submissions' parent and teacher branches."""
    real_student_ids = list({r["real_student_id"] for r in rows if r.get("real_student_id")})
    real_name_map = {}
    if real_student_ids:
        students_r = supabase.table("students").select("id,name").in_("id", real_student_ids).execute()
        real_name_map = {s["id"]: s.get("name") for s in (students_r.data or [])}
    for r in rows:
        r["real_student_name"] = real_name_map.get(r.get("real_student_id"))
    return rows

@api_router.get("/creatures/my-submissions")
async def get_my_submissions(request: Request):
    """Real feature Aug 22 (items 8a/8b): a parent's or teacher's own status view of
    creature submissions, separate from the /creatures/pending moderation queue (which only
    ever shows pending ones and, for parent, is now scoped the same way as this endpoint -
    see item 8c). Was already wired into the frontend api client (creaturesApi.getMySubmissions)
    but never called from any screen and never did more than a bare student_id match - dead
    plumbing, not a real feature, until now.
    Parent: their own family's submissions only (any status).
    Teacher: explicit product decision - everything their classroom(s) have submitted, not
    just what they personally logged. A teacher managing a whole class needs visibility over
    the whole class. Falls back to their own directly-submitted rows too, since classroom_id
    is a newer column that isn't populated on every legacy submission."""
    user = await get_current_user(request)
    role = user.get("role") if user else None
    if not user or role not in ["teacher", "parent"]:
        raise HTTPException(status_code=403, detail="Not authorised")

    base_fields = ("id,creature_name,emotion_colour,student_name,school_name,status,"
                   "created_at,approved_at,rejection_reason,is_globally_available,visibility_scope,"
                   "stage1_url,stage4_url")

    if role == "parent":
        try:
            rows = supabase.table("creature_submissions").select(
                base_fields + ",real_student_id,classroom_id"
            ).eq("student_id", user["user_id"]).order("created_at", desc=True).execute()
        except Exception:
            rows = supabase.table("creature_submissions").select(
                base_fields
            ).eq("student_id", user["user_id"]).order("created_at", desc=True).execute()
        return _annotate_real_student_names(rows.data or [])

    # teacher: classroom-wide, not just self-submitted
    classrooms_r = supabase.table("classrooms").select("id").eq("user_id", user["user_id"]).execute()
    classroom_ids = [c["id"] for c in (classrooms_r.data or [])]
    seen_ids = set()
    results = []
    if classroom_ids:
        try:
            by_classroom = supabase.table("creature_submissions").select(
                base_fields + ",real_student_id,classroom_id"
            ).in_("classroom_id", classroom_ids).order("created_at", desc=True).execute()
        except Exception:
            by_classroom = type("R", (), {"data": []})()
        for row in (by_classroom.data or []):
            if row["id"] not in seen_ids:
                seen_ids.add(row["id"])
                results.append(row)
    try:
        by_teacher = supabase.table("creature_submissions").select(
            base_fields + ",real_student_id,classroom_id"
        ).eq("student_id", user["user_id"]).order("created_at", desc=True).execute()
    except Exception:
        by_teacher = supabase.table("creature_submissions").select(
            base_fields
        ).eq("student_id", user["user_id"]).order("created_at", desc=True).execute()
    for row in (by_teacher.data or []):
        if row["id"] not in seen_ids:
            seen_ids.add(row["id"])
            results.append(row)
    results.sort(key=lambda r: r.get("created_at") or "", reverse=True)
    return _annotate_real_student_names(results)


# ================== ADMIN ==================
@api_router.get("/admin/stats")
async def get_admin_stats(request: Request, days: int = 7):
    """Enhanced stats with daily breakdown for graphs"""
    user = await get_current_user(request)
    if not user or user.get("role") not in ["admin", "superadmin", "school_admin"]:
        raise HTTPException(status_code=403, detail="Admin access required")

    try:
        from datetime import datetime, timezone, timedelta

        now = datetime.now(timezone.utc)
        days = max(1, min(days, 1100))  # clamp 1-1100 (covers up to ~3 years)
        week_ago = (now - timedelta(days=days)).isoformat()
        month_ago = (now - timedelta(days=30)).isoformat()

        # Basic counts — scoped to the caller's own school if they're a school_admin, global for superadmin
        school_teacher_ids = []
        student_ids_for_school = None  # only populated for school_admin; None means "not scoped" (superadmin)
        if user.get("role") == "school_admin":
            admin_id = user.get("user_id")
            school_name = user.get("school_name", "")
            # Real fix Aug 15: this only matched teachers via school_admin_id, but real
            # teacher accounts are often linked only by matching school_name instead (same
            # dual-lookup pattern already working correctly in /school-admin/analytics —
            # that's why the portal showed real numbers while this endpoint, used by the
            # COH app, showed all zeros for the exact same account).
            teachers_by_id_r = supabase.table("users").select("user_id").eq("school_admin_id", admin_id).execute()
            teachers_by_name_r = supabase.table("users").select("user_id").eq("school_name", school_name).eq("role", "teacher").execute() if school_name else type('obj', (object,), {'data': []})()
            school_teacher_ids = list({t["user_id"] for t in (teachers_by_id_r.data or []) + (teachers_by_name_r.data or [])})
            total_teachers = len(school_teacher_ids)
            # Real fix Aug 14: students link via classroom_id, NOT teacher_id (that column
            # doesn't exist on the students table — same architectural fact already
            # documented earlier this session). Resolve real classrooms first.
            # Real fix Aug 21: classroom_owner_ids also includes the school_admin's own
            # user_id now — same gap just fixed on /school-admin/analytics tonight (a
            # classroom reassigned to the school_admin directly, e.g. via account-deletion,
            # was invisible here too, since this only ever looked at classrooms owned by
            # linked teachers).
            classroom_owner_ids = school_teacher_ids + [admin_id]
            school_classrooms_r = supabase.table("classrooms").select("id").in_("user_id", classroom_owner_ids).execute()
            school_classroom_ids = [c["id"] for c in (school_classrooms_r.data or [])]
            if school_classroom_ids:
                students_r = supabase.table("students").select("id").in_("classroom_id", school_classroom_ids).execute()
                student_ids_for_school = [s["id"] for s in (students_r.data or [])]
            else:
                student_ids_for_school = []
            total_students = len(student_ids_for_school)
        else:
            students_result = supabase.table("students").select("id", count="exact").execute()
            total_students = students_result.count or 0

            # Teachers are stored as role='admin' (set on school creation)
            # Count all non-superadmin, non-parent users as teachers
            teachers_result = supabase.table("users").select("user_id", count="exact").in_("role", ["admin", "teacher", "school_admin"]).execute()
            total_teachers = teachers_result.count or 0

        users_result = supabase.table("users").select("user_id", count="exact").execute()
        total_users = users_result.count or 0

        # Zone logs for this week
        # Query both zone_logs and feeling_logs
        # Real fix Aug 21: for a school_admin caller, this previously queried feeling_logs
        # with NO scoping at all — the app's "Your school's data" donut/stats were actually
        # showing PLATFORM-WIDE numbers. Live-confirmed, same account/window: this summed to
        # 1000 (the whole platform's 90-day volume) vs the correctly-scoped
        # /school-admin/analytics' 840 for Sunshine specifically. Chunked in batches of 50
        # (Supabase .in_() practical limit), not truncated to the first 50 like the
        # pre-existing schools_breakdown code further down does.
        # Real bug fix Aug 28 (systematic sweep, same class as /school-admin/analytics):
        # every unpaginated .execute() here silently truncates at PostgREST's default
        # 1000-row cap. The superadmin branch is the highest-risk - days can be clamped up
        # to 1100, so a real multi-month platform-wide query was silently capped with no
        # error. Fixed with the same _fetch_all_paginated() helper.
        logs = []
        try:
            if user.get("role") == "school_admin":
                for i in range(0, len(student_ids_for_school or []), 50):
                    chunk = student_ids_for_school[i:i + 50]
                    logs.extend(_fetch_all_paginated("feeling_logs", "*", lambda q, c=chunk: q.in_("student_id", c).gte("timestamp", week_ago)))
            else:
                logs = _fetch_all_paginated("feeling_logs", "*", lambda q: q.gte("timestamp", week_ago))
        except: pass

        # Zone counts
        zone_counts = {"blue": 0, "green": 0, "yellow": 0, "red": 0}
        checkin_daily = [0] * 7
        today = now.date()

        for log in logs:
            zone = log.get("zone") or log.get("feeling_colour") or log.get("color", "")
            if zone in zone_counts:
                zone_counts[zone] += 1
            # Daily breakdown
            try:
                ts = log.get("timestamp") or log.get("created_at") or ""
                if not ts: continue
                log_date = datetime.fromisoformat(ts.replace("Z", "+00:00")).date()
                days_ago = (today - log_date).days
                if 0 <= days_ago < 7:
                    checkin_daily[6 - days_ago] += 1
            except:
                pass

        # Today's checkins
        today_str = now.strftime("%Y-%m-%d")
        checkins_today = sum(1 for log in logs if (
            log.get("timestamp","") or log.get("created_at","")
        ).startswith(today_str))

        # Teacher check-ins — from teacher_checkins table + feeling_logs with no student_id
        teacher_zone_counts = {"blue": 0, "green": 0, "yellow": 0, "red": 0}
        teacher_daily = [0] * 7
        try:
            # Try teacher_checkins table first. Real fix Aug 21: scoped to this school's
            # teachers for a school_admin caller — teacher_checkins has a real user_id
            # column (confirmed via /school-admin/analytics' identical query), same bug
            # class as the feeling_logs scoping above.
            if user.get("role") == "school_admin":
                tc_data = _fetch_all_paginated("teacher_checkins", "*", lambda q: q.in_("user_id", school_teacher_ids).gte("created_at", week_ago)) if school_teacher_ids else []
            else:
                tc_data = _fetch_all_paginated("teacher_checkins", "*", lambda q: q.gte("created_at", week_ago))
            for tc in tc_data:
                tz = tc.get("zone") or tc.get("feeling_colour", "")
                if tz in teacher_zone_counts:
                    teacher_zone_counts[tz] += 1
                try:
                    ts2 = tc.get("created_at","")
                    if ts2:
                        tdate = datetime.fromisoformat(ts2.replace("Z","+00:00")).date()
                        d_ago = (today - tdate).days
                        if 0 <= d_ago < 7:
                            teacher_daily[6 - d_ago] += 1
                except: pass
        except: pass
        # Note: feeling_logs has no teacher/user identity column at all (only student_id), so
        # entries with a null student_id genuinely can't be scoped to a school without a
        # schema change — left global for both roles, unlike the two blocks above.
        try:
            teacher_logs = _fetch_all_paginated("feeling_logs", "*", lambda q: q.is_("student_id", "null").gte("timestamp", week_ago))
            for tl in teacher_logs:
                tz = tl.get("feeling_colour") or tl.get("zone", "")
                if tz in teacher_zone_counts:
                    teacher_zone_counts[tz] += 1
                try:
                    ts2 = tl.get("timestamp","")
                    if ts2:
                        tdate = datetime.fromisoformat(ts2.replace("Z","+00:00")).date()
                        d_ago = (today - tdate).days
                        if 0 <= d_ago < 7:
                            teacher_daily[6 - d_ago] += 1
                except: pass
        except Exception as te:
            logger.error(f"Teacher zone counts error: {te}")

        # Support requests (wellbeing_alerts table may not exist yet)
        support_requests = 0

        # Total creatures across all students
        total_creatures = 0
        try:
            creatures_r = supabase.table("creatures").select("id", count="exact").execute()
            total_creatures = creatures_r.count or 0
        except: pass

        # Streak students — students with check-ins on 3+ consecutive days
        streak_students = 0
        try:
            # Real fix Aug 21: same unscoped-for-school_admin bug as the zone_counts logs
            # query above — this counted streaks across the whole platform, not just this
            # school's students.
            all_logs_data = []
            if user.get("role") == "school_admin":
                for i in range(0, len(student_ids_for_school or []), 50):
                    chunk = student_ids_for_school[i:i + 50]
                    all_logs_data.extend(_fetch_all_paginated("feeling_logs", "student_id,timestamp", lambda q, c=chunk: q.in_("student_id", c).gte("timestamp", month_ago)))
            else:
                all_logs_data = _fetch_all_paginated("feeling_logs", "student_id,timestamp", lambda q: q.gte("timestamp", month_ago))
            from collections import defaultdict
            student_dates = defaultdict(set)
            for l in all_logs_data:
                try:
                    d = datetime.fromisoformat(l["timestamp"].replace("Z","+00:00")).date()
                    student_dates[l["student_id"]].add(d)
                except: pass
            for sid, dates in student_dates.items():
                sorted_dates = sorted(dates)
                streak = 1
                for i in range(1, len(sorted_dates)):
                    if (sorted_dates[i] - sorted_dates[i-1]).days == 1:
                        streak += 1
                        if streak >= 3:
                            streak_students += 1
                            break
                    else:
                        streak = 1
        except: pass

        # Top strategy
        strategy_counts = {}
        for log in logs:
            for s in (log.get("strategies_selected") or []):
                strategy_counts[s] = strategy_counts.get(s, 0) + 1
        top_strategy = max(strategy_counts, key=strategy_counts.get) if strategy_counts else "—"

        # Schools breakdown — one entry per unique school, students via teachers linked to this school_admin
        try:
            school_admins = supabase.table("users").select("*").eq("role", "school_admin").execute()
            schools_breakdown = []
            seen_school_names = set()
            for admin in (school_admins.data or []):
                admin_id = admin.get("user_id", "")
                school_name_key = admin.get("school_name") or admin_id
                if school_name_key in seen_school_names:
                    continue
                seen_school_names.add(school_name_key)
                # Get students belonging to this admin's school (via teachers linked through
                # school_admin_id OR school_name — dual-match, same pattern as
                # /school-admin/analytics, since teachers whose school_admin_id was never
                # backfilled would otherwise be silently dropped from this breakdown).
                try:
                    admin_school_name = admin.get("school_name") or ""
                    school_teachers_by_id = supabase.table("users").select("user_id").eq("school_admin_id", admin_id).execute()
                    school_teachers_by_name = supabase.table("users").select("user_id").eq("school_name", admin_school_name).eq("role", "teacher").execute() if admin_school_name else type("obj", (object,), {"data": []})()
                    teacher_ids_for_school = list({t["user_id"] for t in (school_teachers_by_id.data or []) + (school_teachers_by_name.data or [])})
                    student_ids = []
                    # Real fix Aug 14: same architectural fact as above — students link via
                    # classroom_id, not a direct teacher_id column (which doesn't exist).
                    if teacher_ids_for_school:
                        school_classrooms_r2 = supabase.table("classrooms").select("id").in_("user_id", teacher_ids_for_school).execute()
                        school_classroom_ids2 = [c["id"] for c in (school_classrooms_r2.data or [])]
                        if school_classroom_ids2:
                            school_students = supabase.table("students").select("id,classroom_id").in_("classroom_id", school_classroom_ids2).execute()
                            student_ids = [s["id"] for s in (school_students.data or [])]
                except:
                    student_ids = []

                school_zone_counts = {"blue": 0, "green": 0, "yellow": 0, "red": 0}
                school_checkins = 0
                if student_ids:
                    try:
                        # Real bug fix Aug 23 (item 7): "zone" was never a real column on
                        # feeling_logs (confirmed live - the actual schema is student_id,
                        # feeling_colour, helpers_selected, comment, location, timestamp,
                        # logged_by, family_member_id, no "zone" at all). This select failed
                        # with a Postgres "column does not exist" error on every single call,
                        # silently swallowed by the except below - Schools Breakdown showed
                        # 0 check-ins for every school, at every time period, regardless of
                        # how much real check-in data existed, because the query never
                        # actually succeeded even once. feeling_colour alone is correct and
                        # sufficient - it's the only field that's ever been real.
                        # student_ids[:50] is a separate, pre-existing, still-open limitation
                        # (only the first 50 students of a school are ever considered here) -
                        # not fixed as part of this pass, flagged separately below. Row
                        # pagination added for consistency with every other query in this
                        # endpoint, in case that 50-student subset alone tops 1000 rows.
                        school_logs_data = _fetch_all_paginated("feeling_logs", "feeling_colour", lambda q, sids=student_ids[:50]: q.in_("student_id", sids).gte("timestamp", week_ago))
                        for log in school_logs_data:
                            z = log.get("feeling_colour") or ""
                            if z in school_zone_counts:
                                school_zone_counts[z] += 1
                        school_checkins = len(school_logs_data)
                    except:
                        pass

                # Get school name from admin record or school_profiles
                school_name = admin.get("school_name") or admin.get("email", "Unknown School")
                school_desc = ""
                try:
                    profile = supabase.table("school_profiles").select("school_name,description").eq("user_id", admin_id).execute()
                    if profile.data:
                        school_name = profile.data[0].get("school_name") or school_name
                        school_desc = profile.data[0].get("description", "")
                except:
                    pass

                schools_breakdown.append({
                    "name": school_name,
                    "description": school_desc,
                    "total_checkins": school_checkins,
                    "zone_counts": school_zone_counts,
                })
            total_schools = len(schools_breakdown)
        except Exception as sb_err:
            logger.error(f"Schools breakdown error: {sb_err}")
            schools_breakdown = []
            total_schools = 0

        # Build classroom name lookup
        classroom_name_map = {}
        try:
            classrooms_r = supabase.table("classrooms").select("id,name").execute()
            classroom_name_map = {c["id"]: c["name"] for c in (classrooms_r.data or [])}
        except: pass

        # Real feature Aug 26 (item 10): the portal's "Subscriptions & Revenue" card has read
        # active_parents/annual_parents/active_teachers/annual_teachers/active_schools from
        # this endpoint since the day it was built, but none of the five were ever computed or
        # returned — it's shown five dashes in production the entire time. Confirmed live before
        # building this: there is no self-serve annual plan for parents/teachers at all
        # (/subscription/checkout only accepts teacher_monthly/parent_monthly), and no field
        # anywhere tracks billing interval — so annual_parents/annual_teachers are dropped
        # rather than faked with a query that can only ever return 0. Only the real, trackable
        # active counts are built. Platform-wide, so superadmin/admin only — a school_admin
        # doesn't need (and shouldn't see) other schools' paying-subscriber counts.
        active_parents = 0
        active_teachers = 0
        active_schools = 0
        if user.get("role") != "school_admin":
            try:
                paying_r = supabase.table("users").select("role,subscription_status,subscription_expires_at").eq("subscription_status", "active").in_("role", ["parent", "teacher"]).execute()
                for u in (paying_r.data or []):
                    exp = u.get("subscription_expires_at")
                    if exp:
                        try:
                            if datetime.fromisoformat(exp.replace("Z", "+00:00")) <= now:
                                continue  # expired, not a real paying subscriber
                        except (ValueError, TypeError):
                            pass
                    if u.get("role") == "parent":
                        active_parents += 1
                    elif u.get("role") == "teacher":
                        active_teachers += 1
            except Exception as sub_err:
                logger.error(f"Subscriptions stat error: {sub_err}")
            try:
                schools_active_r = supabase.table("school_profiles").select("id", count="exact").eq("status", "active").execute()
                active_schools = schools_active_r.count or 0
            except Exception as sub_err:
                logger.error(f"Active schools stat error: {sub_err}")

        return {
            "total_students": total_students,
            "total_teachers": total_teachers,
            "total_users": total_users,
            "total_schools": total_schools,
            "active_parents": active_parents,
            "active_teachers": active_teachers,
            "active_schools": active_schools,
            "classroom_names": classroom_name_map,
            "total_checkins": len(logs),
            "checkins_today": checkins_today,
            "active_users": min(total_students + total_teachers, len(set(l.get("student_id","") for l in logs))),
            "zone_counts": zone_counts,
            "teacher_zone_counts": teacher_zone_counts,
            "total_teacher_checkins": sum(teacher_zone_counts.values()),
            "checkin_daily": checkin_daily,
            "student_daily": checkin_daily,
            "teacher_daily": teacher_daily,
            "active_daily": checkin_daily,
            "school_daily": [total_schools] * 7,
            "support_requests": support_requests,
            "top_strategy": top_strategy,
            "top_teacher_strategy": "—",
            "total_creatures": total_creatures,
            "avg_checkins_to_evolve": "—",
            "streak_students": streak_students,
            "avg_session_mins": "—",
            "avg_student_session": "—",
            "avg_teacher_session": "—",
            "schools_breakdown": schools_breakdown,
        }
    except Exception as e:
        logger.error(f"Stats error: {e}", exc_info=True)
        # Try to get at least basic counts
        try:
            basic_students = supabase.table("students").select("id", count="exact").execute()
            basic_teachers = supabase.table("users").select("user_id", count="exact").eq("role", "teacher").execute()
            return {
                "total_students": basic_students.count or 0,
                "total_teachers": basic_teachers.count or 0,
                "total_users": 0,
                "total_schools": 0, "checkins_today": 0, "total_checkins": 0,
                "active_users": 0, "zone_counts": {}, "teacher_zone_counts": {},
                "total_teacher_checkins": 0, "checkin_daily": [0]*7,
                "student_daily": [0]*7, "teacher_daily": [0]*7,
                "active_daily": [0]*7, "school_daily": [0]*7,
                "support_requests": 0, "top_strategy": "—",
                "top_teacher_strategy": "—", "total_creatures": 0,
                "avg_checkins_to_evolve": "—", "streak_students": 0,
                "avg_session_mins": "—", "avg_student_session": "—",
                "avg_teacher_session": "—", "schools_breakdown": [],
            }
        except:
            pass
        return {
            "total_students": 0, "total_teachers": 0, "total_users": 0,
            "total_schools": 0, "checkins_today": 0, "total_checkins": 0,
            "active_users": 0, "zone_counts": {}, "teacher_zone_counts": {},
            "total_teacher_checkins": 0, "checkin_daily": [0]*7,
            "student_daily": [0]*7, "teacher_daily": [0]*7,
            "active_daily": [0]*7, "school_daily": [0]*7,
            "support_requests": 0, "top_strategy": "—",
            "top_teacher_strategy": "—", "total_creatures": 0,
            "avg_checkins_to_evolve": "—", "streak_students": 0,
            "avg_session_mins": "—", "avg_student_session": "—",
            "avg_teacher_session": "—", "schools_breakdown": [],
        }


@api_router.get("/admin/resources")
async def get_admin_resources(request: Request):
    user = await get_current_user(request)
    if not user or user.get("role") not in ["admin", "superadmin", "school_admin"]:
        raise HTTPException(status_code=403, detail="Admin only")
    # Real fix Aug 14: same root cause as the /parent/resources bug fixed earlier tonight —
    # select("*") pulled every resource's full base64 PDF content inline for ALL rows in one
    # response (some single rows 3MB+), causing this endpoint's real 500s. The portal's list
    # view never actually renders raw content — PDFs download via the separate /download
    # endpoint (needs only pdf_filename to know a download link should show), and only video
    # resources use "content" directly as their Watch-link URL. All 16 real resources today
    # are PDFs, none are video, so this is safe now — but if a video resource is ever added,
    # its portal Watch link would need "content" back in this select to work.
    result = supabase.table("resources").select(
        "id,title,description,content_type,pdf_filename,topic,category,target_audience,order_index,is_global,is_active,created_at,user_id"
    ).order("created_at", desc=True).execute()
    return result.data or []


@api_router.post("/admin/verify")
async def verify_admin_access(request: Request):
    """Role check added Aug 14. Real second-factor PIN check re-added Aug 20 (A19) after
    real-device testing found the in-app Unlock screen accepted an empty/any PIN — this
    endpoint never actually read the code the user typed, only their session's role. Role
    remains the primary gate (unchanged); PIN is now checked on top of it, not instead of it.
    superadmin/admin check against ADMIN_PIN (same value already required at login).
    ALWAYS_OPEN_PINS accounts (covers the demo school_admin) check their own fixed value.
    Real (non-demo) school_admin accounts have no PIN infrastructure yet — deliberately left
    on the role-only check, same as before Aug 20; a real per-school PIN is a separate future
    feature (Path 2, COH-REVIEW-PLAN.md A19), not bundled into this fix."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    role = user.get("role")
    if role not in ("superadmin", "school_admin"):
        return {"valid": False, "is_super_admin": False}

    body = await request.json()
    code = (body.get("code") or "").strip()
    email = (user.get("email") or "").strip().lower()

    if role == "superadmin":
        required_pin = os.environ.get("ADMIN_PIN", "")
        if required_pin and code != required_pin:
            return {"valid": False, "is_super_admin": False}
    elif email in ALWAYS_OPEN_PINS:
        if code != ALWAYS_OPEN_PINS[email]:
            return {"valid": False, "is_super_admin": False}
    # else: real school_admin, not in ALWAYS_OPEN_PINS — role-only gate, unchanged (Path 1)

    return {"valid": True, "is_super_admin": role == "superadmin"}


@api_router.post("/admin/resources")
async def create_admin_resource(request: Request):
    user = await get_current_user(request)
    if not user or user.get("role") not in ["admin", "superadmin", "school_admin"]:
        raise HTTPException(status_code=403, detail="Admin only")
    body = await request.json()
    title = (body.get("title") or "").strip()
    if not title:
        raise HTTPException(status_code=400, detail="Title is required")

    content_type = body.get("content_type", "text")
    target_audience = body.get("target_audience", "both")
    topic = body.get("topic") or body.get("category") or "general"
    resource_data = {
        "id": str(uuid.uuid4()),
        "user_id": user["user_id"],
        "title": title,
        "description": body.get("description", ""),
        "content_type": content_type,
        # Store text content OR base64 PDF payload
        "content": body.get("content") if content_type == "text" else body.get("pdf_data") or body.get("content"),
        "pdf_filename": body.get("pdf_filename"),
        "category": body.get("category", topic),
        "topic": topic,
        "target_audience": target_audience,
        "is_global": True,
        "is_active": True,
        "created_at": datetime.now(timezone.utc).isoformat(),
    }

    try:
        result = supabase.table("resources").insert(resource_data).execute()
    except Exception:
        # Backward-compatible fallback if new columns are missing in DB schema.
        fallback_data = {
            "id": resource_data["id"],
            "user_id": resource_data["user_id"],
            "title": resource_data["title"],
            "description": resource_data["description"],
            "content_type": resource_data["content_type"],
            "content": resource_data["content"],
            "pdf_filename": resource_data["pdf_filename"],
            "category": resource_data["category"],
            "is_global": resource_data["is_global"],
            "is_active": resource_data["is_active"],
            "created_at": resource_data["created_at"],
        }
        result = supabase.table("resources").insert(fallback_data).execute()

    return result.data[0] if result.data else resource_data


