@api_router.post("/auth/email-login")
async def email_login(request: Request):
    """Email-based login. Admin/superadmin accounts require an admin PIN."""
    try:
        body = await request.json()
        email = body.get("email", "").strip().lower()
        if not email or "@" not in email:
            raise HTTPException(status_code=400, detail="Valid email required")
        admin_pin = body.get("admin_pin", "").strip()
        
        # Find or create user
        try:
            existing = supabase.table("users").select("*").eq("email", email).execute()
            if existing.data:
                # User exists — use them
                user = existing.data[0]
                # Real feature Aug 20: blocks login for accounts with a pending self-service
                # deletion (see POST /account/delete-request) - the account is soft-deleted
                # immediately on request, not just at the end of the 30-day grace period.
                if user.get("deletion_requested_at"):
                    raise HTTPException(status_code=403, detail="This account is scheduled for deletion. Contact jono@classofhappiness.com if this wasn't you or you'd like to cancel.")
                # Real feature Aug 27 (item 11): mirrors the deletion_requested_at check just
                # above - a clear message at the actual login attempt, on top of the real-time
                # get_current_user() gate that kills an already-active session immediately.
                if user.get("account_suspended"):
                    raise HTTPException(status_code=403, detail="This account has been suspended. Contact jono@classofhappiness.com for details.")
                # PIN check for superadmin role (existing)
                if user.get("role") == "superadmin":
                    required_pin = os.environ.get("ADMIN_PIN", "")
                    if required_pin and admin_pin != required_pin:
                        raise HTTPException(status_code=403, detail="Admin PIN required. Contact Jono.")
                # PIN check for the 4 permanent always-open accounts
                elif email in ALWAYS_OPEN_PINS:
                    if admin_pin != ALWAYS_OPEN_PINS[email]:
                        raise HTTPException(status_code=403, detail="PIN required for this account. Contact Jono.")
                # Real password check — if this user has ever set a password via /auth/set-password,
                # it must now actually be required and verified. Previously portal_password was
                # stored but never checked anywhere, meaning setting a password had zero real
                # security effect — anyone could still log in with just the email.
                if user.get("portal_password"):
                    password = body.get("password", "")
                    if not password or not verify_password(password, user["portal_password"]):
                        raise HTTPException(status_code=401, detail="Incorrect password")
            else:
                # CRITICAL security fix Aug 26 (item 2): this used to silently create a real
                # teacher account for ANY unrecognized email, no confirmation, no verification
                # of any kind - typing a made-up email was indistinguishable from a genuine
                # signup. Combined with the password bypass (see the force-password-on-login
                # fix and COH-REVIEW-PLAN.md), this was a second, compounding way into the
                # app with zero real identity check. Plain email/password at LOGIN is no
                # longer a signup path - real email/password signup now exists as its own
                # deliberate, explicit action (POST /auth/signup, added Aug 26 the morning
                # after this fix - see its own docstring), with a real password required and
                # role chosen explicitly. Google sign-in (POST /auth/google) remains real
                # account-creation too, since Google itself verifies the email is genuinely
                # owned. Message updated Aug 29 to mention /auth/signup - build 24 is the
                # first app build whose login screen actually has the "Create an account"
                # link wired to it; builds 22/23 predate it and only had Google/invite-code.
                raise HTTPException(status_code=404, detail="No account found with this email. If you're new here, tap \"Create an account\" below, use \"Sign in with Google\", or ask your school/teacher for an invite code.")
        except HTTPException:
            # Real bug fix Aug 26, found live-verifying the 404 above: every HTTPException
            # raised inside this try block (including the pre-existing 401 "Incorrect
            # password", 403 "Admin PIN required", and 403 "scheduled for deletion" checks
            # above) was being caught by the broad `except Exception` below and rewrapped
            # into a 500 "Database error" - the real status code and message never actually
            # reached the client. Confirmed live: the new 404 came back as a 500 before this
            # fix. Real HTTPExceptions now propagate with their real status/detail; only a
            # genuine unexpected error (e.g. an actual DB failure) still becomes a 500.
            raise
        except Exception as e:
            logger.error(f"User lookup error: {e}")
            raise HTTPException(status_code=500, detail=f"Database error: {str(e)}")
        
        # Create session token - try user_sessions table first, fallback to simple token
        session_token = str(uuid.uuid4())
        try:
            supabase.table("user_sessions").insert({
                "session_token": session_token,
                "user_id": user["user_id"],
                "expires_at": (datetime.now(timezone.utc) + timedelta(days=30)).isoformat(),
                "created_at": datetime.now(timezone.utc).isoformat()
            }).execute()
        except Exception as e:
            logger.warning(f"user_sessions insert failed: {e} - using token only")
        
        return {"user": _public_user(user), "session_token": session_token}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Email login error: {e}")
        raise HTTPException(status_code=500, detail=str(e))


