def _resource_to_teacher_resource(r: dict, ratings: list) -> dict:
    resource_id = r.get("id", "")
    resource_ratings = [x for x in ratings if x.get("resource_id") == resource_id]
    avg_rating = 0.0
    if resource_ratings:
        avg_rating = sum(x.get("rating", 0) for x in resource_ratings) / len(resource_ratings)
    return {
        "id": resource_id,
        "title": r.get("title", ""),
        "description": r.get("description", ""),
        "content_type": r.get("content_type", "text"),
        "content": r.get("content", ""),
        "pdf_filename": r.get("pdf_filename"),
        "topic": r.get("topic") or r.get("category") or "general",
        "category": r.get("category") or r.get("topic") or "general",
        "target_audience": r.get("target_audience", "both"),
        "order_index": r.get("order_index", 0),
        "is_global": r.get("is_global", False),
        "is_active": r.get("is_active", True),
        "created_at": r.get("created_at", ""),
        "user_id": r.get("user_id", ""),
        "created_by": r.get("created_by"),
        "created_by_name": r.get("created_by_name"),
        "average_rating": round(avg_rating, 1),
        "rating_count": len(resource_ratings),
        "week_number": r.get("week_number"),
        "is_locked": r.get("is_locked", False),
    }

@api_router.get("/teacher-resources")  # audience filter supported
async def get_teacher_resources(request: Request, topic: Optional[str] = None, audience: Optional[str] = None):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    resources_result = supabase.table("resources").select("id,title,description,content_type,pdf_filename,topic,category,target_audience,order_index,is_global,is_active,created_at,user_id,created_by,week_number").eq("is_active", True).execute()
    all_resources = resources_result.data or []

    # Real freemium gating — same rule as /resources: Emotion Program always free, other
    # programs' week 1-2 (or no-week/general items) free, week 3+ locked for free tier.
    # Real bug fix Aug 28 (technical debt sweep, same class as the Aug 24/25 creature caps
    # and /resources' identical bug fixed alongside this one): treated any subscription_status
    # other than 'none'/'free' as "not free tier" - a genuinely expired trial or lapsed paid
    # plan would incorrectly stay unlocked forever, and this check (unlike /resources) never
    # even had a school-coverage exemption. _is_genuinely_free_tier() covers both real expiry
    # and both teacher/parent school-coverage exemptions - strict superset, not a behaviour
    # change for any genuinely-covered or genuinely-active user.
    is_free_tier = _is_genuinely_free_tier(user)
    for r in all_resources:
        if not is_free_tier:
            r["is_locked"] = False
            continue
        category = r.get("category")
        week = r.get("week_number")
        if category == "emotions_program":
            r["is_locked"] = False
        elif week is None or week <= 2:
            r["is_locked"] = False
        else:
            r["is_locked"] = True

    # Determine which audiences to show
    # If caller specifies audience=parents, show parents+both
    # If caller specifies audience=teachers (default), show teachers+both
    # If no audience specified, show all
    if audience == "parents":
        allowed_audiences = ["parents", "both", None, ""]
    elif audience == "teachers":
        allowed_audiences = ["teachers", "both", None, ""]
    else:
        allowed_audiences = ["teachers", "parents", "both", None, ""]

    visible = []
    for r in all_resources:
        r_audience = r.get("target_audience", "both")
        if r_audience not in allowed_audiences:
            continue
        resource_topic = r.get("topic") or r.get("category") or "general"
        if topic and topic != "all" and resource_topic != topic:
            continue
        visible.append(r)

    # teacher_resource_ratings table may not exist yet — safe fallback
    ratings = []
    try:
        ratings_result = supabase.table("teacher_resource_ratings").select("*").execute()
        if ratings_result and hasattr(ratings_result, 'data') and ratings_result.data:
            ratings = ratings_result.data
    except Exception:
        ratings = []

    return [_resource_to_teacher_resource(r, ratings) for r in visible]



