@api_router.get("/school-admin/stats")
async def get_school_admin_stats(request: Request):
    """School admin sees their school's stats"""
    user = await get_current_user(request)
    if not user or user.get("role") not in ["school_admin", "admin", "superadmin"]:
        raise HTTPException(status_code=403, detail="School admin access required")
    user_id = user["user_id"]
    # Get all teachers for this school admin — by school_admin_id OR school_name, same
    # dual-match pattern already used correctly in /school-admin/analytics and
    # /reports/pdf/school-overview. Without this, teachers whose school_admin_id was never
    # backfilled (only school_name set) are silently dropped from this admin's own stats.
    school_name = user.get("school_name", "")
    teachers_by_id = supabase.table("users").select("user_id, name, email").eq("school_admin_id", user_id).execute()
    teachers_by_name = supabase.table("users").select("user_id, name, email").eq("school_name", school_name).eq("role", "teacher").execute() if school_name else type("obj", (object,), {"data": []})()
    all_teachers = {t["user_id"]: t for t in (teachers_by_id.data or []) + (teachers_by_name.data or [])}
    teacher_ids = list(all_teachers.keys())
    # Real fix Aug 14: same architectural fact fixed 3x elsewhere in this file today —
    # students link via classroom_id, not a direct teacher-owned user_id column. Resolve
    # real classrooms first.
    classroom_ids_sa = [c["id"] for c in (supabase.table("classrooms").select("id").in_("user_id", teacher_ids).execute().data or [])] if teacher_ids else []
    students = supabase.table("students").select("*").in_("classroom_id", classroom_ids_sa).execute() if classroom_ids_sa else type("obj", (object,), {"data": []})()
    return {
        "total_teachers": len(teacher_ids),
        "total_students": len(students.data or []),
        "school_name": user.get("school_name", "My School"),
    }

@api_router.post("/admin/unlink-user")
async def unlink_user(request: Request):
    """Superadmin unlinks a parent-teacher connection"""
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Admin access required")
    body = await request.json()
    email = (body.get("email") or "").strip().lower()
    link_type = body.get("type", "teacher")
    if not email:
        raise HTTPException(status_code=400, detail="Email required")
    try:
        # Find user by email
        user_result = supabase.table("users").select("user_id, name, email").eq("email", email).execute()
        if not user_result.data:
            raise HTTPException(status_code=404, detail=f"No user found with email: {email}")
        target_user = user_result.data[0]
        target_id = target_user["user_id"]
        # Remove parent-teacher links
        if link_type == "parent":
            supabase.table("parent_teacher_links").delete().eq("parent_id", target_id).execute()
        else:
            supabase.table("parent_teacher_links").delete().eq("teacher_id", target_id).execute()
        # Log the action
        logger.info(f"Admin {user['user_id']} unlinked {link_type} {email}")
        return {"status": "unlinked", "email": email, "type": link_type}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Unlink error: {e}")
        raise HTTPException(status_code=500, detail="Failed to unlink user")

# ================== SCHOOL INVITE CODE SYSTEM ==================

import secrets
import string

def generate_invite_code(prefix="SCH"):
    """Generate a readable invite code like SCH-X7K2-M9P4"""
    chars = string.ascii_uppercase + string.digits
    part1 = ''.join(secrets.choice(chars) for _ in range(4))
    part2 = ''.join(secrets.choice(chars) for _ in range(4))
    return f"{prefix}-{part1}-{part2}"

@api_router.post("/school/generate-invite-code")
async def generate_school_invite_code(request: Request):
    """School admin generates an invite code for their teachers. Real fix Aug 20: the portal's
    superadmin Schools panel (saGenerateInviteCode) has always passed a target school_id in the
    body, but this endpoint silently ignored it and always used the CALLER's own user_id/
    school_name - meaning a superadmin generating "a code for Sunshine" from that panel was
    actually generating a code tied to their own superadmin account, not Sunshine. Any teacher
    who redeemed it would have been incorrectly linked to superadmin as their school_admin.
    Doesn't affect a school_admin generating their own code for themselves (the real, working,
    already-tested path) - user_id/school_name there were always the caller's own regardless."""
    user = await get_current_user(request)
    if not user or user.get("role") not in ["admin", "superadmin", "school_admin"]:
        raise HTTPException(status_code=403, detail="School admin access required")

    target_admin_id = user["user_id"]
    target_school_name = user.get("school_name", "My School")
    if user.get("role") == "superadmin":
        try:
            body = await request.json()
        except Exception:
            body = {}
        requested_admin_id = body.get("school_admin_id")
        if requested_admin_id:
            target_r = supabase.table("users").select("user_id,school_name").eq("user_id", requested_admin_id).eq("role", "school_admin").execute()
            if not target_r.data:
                raise HTTPException(status_code=404, detail="No school_admin account found with that user_id")
            target_admin_id = target_r.data[0]["user_id"]
            target_school_name = target_r.data[0].get("school_name") or "My School"

    code = generate_invite_code("SCH")
    expires_at = (datetime.now(timezone.utc) + timedelta(days=90)).isoformat()

    invite_data = {
        "id": str(uuid.uuid4()),
        "code": code,
        "school_admin_id": target_admin_id,
        "school_name": target_school_name,
        "type": "school",
        "expires_at": expires_at,
        "uses": 0,
        "max_uses": 999,
        "created_at": datetime.now(timezone.utc).isoformat(),
    }
    stored = False
    try:
        supabase.table("invite_codes").insert(invite_data).execute()
        stored = True
    except Exception as e:
        logger.error(f"Could not store invite code in invite_codes table: {e}")
        # Fallback: store in admin_settings as key-value so join still works
        # Real bug fix Aug 28: setting_key/setting_value are not real admin_settings columns
        # (see get_notification_settings' docstring) - this fallback has always silently
        # failed too (rarely exercised, since the primary invite_codes insert normally
        # succeeds, but genuinely broken if it's ever actually needed).
        try:
            import json
            supabase.table("admin_settings").insert({
                "school_admin_id": user["user_id"],
                "key": f"invite_code_{code}",
                "value": json.dumps(invite_data),
            }).execute()
            stored = True
            logger.info(f"Invite code stored in admin_settings fallback")
        except Exception as e2:
            logger.error(f"Fallback storage also failed: {e2}")

    return {"code": code, "expires_at": expires_at, "school_name": invite_data["school_name"], "stored": stored}

@api_router.post("/school/join")
async def join_school_with_invite(request: Request):
    """Teacher joins a school using invite code"""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Must be logged in")
    # Real fix Aug 20: school invite codes are only meant for teachers joining a school -
    # this endpoint had no role check at all, so any authenticated user (e.g. a parent who
    # got hold of a code) could set their own school_admin_id/school_name. That silently
    # made them show up in the school's teacher roster (server.py ~8416, filtered by
    # school_admin_id with no role check) and unlocked school-plan free-tier benefits
    # (is_school_covered, server.py ~2583). Parents get school access via parent_links
    # (linking to their own child), a completely separate mechanism - they never need this.
    if user.get("role") != "teacher":
        raise HTTPException(status_code=403, detail="Only teacher accounts can join a school with an invite code.")
    body = await request.json()
    code = (body.get("code") or "").strip().upper()
    if not code:
        raise HTTPException(status_code=400, detail="Invite code required")

    try:
        result = supabase.table("invite_codes").select("*").eq("code", code).execute()
        # Fallback: check admin_settings if invite_codes table is empty/missing
        # Real bug fix Aug 28: same setting_key/setting_value bug as the write side above.
        if not result.data:
            try:
                import json
                fb = supabase.table("admin_settings").select("*").eq("key", f"invite_code_{code}").execute()
                if fb.data:
                    result_data = json.loads(fb.data[0]["value"])
                    result = type('R', (), {'data': [result_data]})()
            except Exception as fb_err:
                logger.error(f"Fallback invite lookup failed: {fb_err}")
        if not result.data:
            raise HTTPException(status_code=404, detail="Invalid invite code. Check the code and try again.")
        invite = result.data[0]
        
        # Check expiry
        expires = datetime.fromisoformat(invite["expires_at"].replace("Z", "+00:00"))
        if datetime.now(timezone.utc) > expires:
            raise HTTPException(status_code=400, detail="This invite code has expired. Ask your school admin for a new one.")
        
        # Link teacher to school
        supabase.table("users").update({
            "school_admin_id": invite["school_admin_id"],
            "school_name": invite["school_name"],
        }).eq("user_id", user["user_id"]).execute()
        
        # Increment uses
        supabase.table("invite_codes").update({"uses": invite.get("uses", 0) + 1}).eq("code", code).execute()
        
        return {
            "status": "joined",
            "school_name": invite["school_name"],
            "message": f"Welcome! You've joined {invite['school_name']}."
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Join school error: {e}")
        raise HTTPException(status_code=500, detail="Could not join school. Try again.")

