@api_router.post("/school/bulk-invite")
async def bulk_invite_teachers(request: Request):
    """School admin pastes a list of emails — all get linked to the school instantly. Real fix
    Aug 21: same bug as /school/generate-invite-code (fixed Aug 20) - this always used the
    CALLER's own user_id/school_name/subscription_expires_at regardless of any target passed
    in the body, so a superadmin bulk-inviting "for Sunshine" from the portal's Schools panel
    would actually link those accounts to superadmin's own account instead. Doesn't affect a
    school_admin bulk-inviting for themselves (the real, working, already-tested path) - those
    fields were always the caller's own regardless. No role restriction on the TARGET account
    (a bulk-invited email can be any role) - unlike /school/join, which is the self-service
    path and is deliberately teacher-only."""
    user = await get_current_user(request)
    if not user or user.get("role") not in ["admin", "superadmin", "school_admin"]:
        raise HTTPException(status_code=403, detail="School admin access required")
    body = await request.json()

    target_admin_id = user["user_id"]
    target_school_name = user.get("school_name", "My School")
    target_subscription_expires_at = user.get("subscription_expires_at")
    if user.get("role") == "superadmin":
        requested_admin_id = body.get("school_admin_id")
        if requested_admin_id:
            target_r = supabase.table("users").select("user_id,school_name,subscription_expires_at").eq("user_id", requested_admin_id).eq("role", "school_admin").execute()
            if not target_r.data:
                raise HTTPException(status_code=404, detail="No school_admin account found with that user_id")
            target_admin_id = target_r.data[0]["user_id"]
            target_school_name = target_r.data[0].get("school_name") or "My School"
            target_subscription_expires_at = target_r.data[0].get("subscription_expires_at")

    raw_emails = body.get("emails", "")
    emails = [e.strip().lower() for e in raw_emails.replace(",", " ").split() if "@" in e.strip()]
    if not emails:
        raise HTTPException(status_code=400, detail="No valid email addresses found")
    results = {"linked": [], "not_found": [], "already_linked": []}
    for email in emails:
        try:
            res = supabase.table("users").select("*").eq("email", email).execute()
            if not res.data:
                results["not_found"].append(email)
                continue
            target = res.data[0]
            if target.get("school_admin_id") == target_admin_id:
                results["already_linked"].append(email)
                continue
            supabase.table("users").update({
                "school_admin_id": target_admin_id,
                "school_name": target_school_name,
                "subscription_status": "active",
                "subscription_expires_at": target_subscription_expires_at,
            }).eq("user_id", target["user_id"]).execute()
            results["linked"].append(email)
        except Exception as e:
            logger.error(f"Bulk invite error for {email}: {e}")
            results["not_found"].append(email)
    return results

@api_router.post("/teacher/student/{student_id}/flag-to-admin")
async def flag_student_to_admin(student_id: str, request: Request):
    """Teacher flags a wellbeing concern for a student to their school admin. Creates a real
    student_alerts row (same table/schema as help_request alerts) with a distinct alert_type,
    so it automatically flows into the already-built school-admin analytics dashboard without
    needing any new school-admin-side infrastructure."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    body = await request.json()
    message = (body.get("message") or "").strip()
    if not message:
        raise HTTPException(status_code=400, detail="A message is required to flag a student")

    student_result = supabase.table("students").select("*").eq("id", student_id).execute()
    if not student_result.data:
        raise HTTPException(status_code=404, detail="Student not found")
    student = student_result.data[0]
    # Real fix Aug 26 (security audit): had no authorization check at all - any authenticated
    # user could raise a wellbeing-concern flag against any student to that student's school
    # admin.
    if user.get("role") not in ("teacher", "school_admin", "superadmin"):
        raise HTTPException(status_code=403, detail="Teacher access required")
    if not await _is_authorized_for_student(user, student_id, student):
        raise HTTPException(status_code=403, detail="Not authorized for this student")

    classroom_name = ""
    if student.get("classroom_id"):
        classroom_result = supabase.table("classrooms").select("name").eq("id", student["classroom_id"]).execute()
        if classroom_result.data:
            classroom_name = classroom_result.data[0].get("name", "")

    alert_id = str(uuid.uuid4())
    try:
        supabase.table("student_alerts").insert({
            "id": alert_id,
            "student_id": student_id,
            "student_name": student.get("name", ""),
            "alert_type": "school_admin_flag",
            "context": "school",
            "classroom_name": classroom_name,
            "zone": body.get("zone", "yellow"),
            "strategy_id": None,
            "strategy_name": None,
            "message": message,
            "created_at": datetime.now(timezone.utc).isoformat(),
            "resolved": False,
        }).execute()
        return {"status": "flagged", "alert_id": alert_id}
    except Exception as e:
        logger.error(f"flag_student_to_admin error: {e}")
        raise HTTPException(status_code=500, detail="Could not flag student to admin")

def _fetch_all_paginated(table: str, select_fields: str, filters_fn, page_size: int = 1000) -> list:
    """Real bug fix Aug 28: found live-verifying demo-prep item 4 - PostgREST silently caps
    any unpaginated .execute() at 1000 rows (confirmed live: Sunshine's real 90-day
    feeling_logs count is 1731 after tonight's seed data, but the endpoint reported exactly
    1000 - the round number was the giveaway). This wasn't introduced tonight; it's been
    true of every unpaginated feeling_logs query in this file, just never crossed 1000 rows
    for any real school until now. Applied here and to the school-overview PDF's per-school
    stats (both touched tonight); NOT swept across every other occurrence in this file
    (/admin/stats, /creatures/analytics, etc.) - a real, separate cleanup pass, flagged not
    fixed, to avoid scope creep beyond what tonight's work actually touches."""
    all_rows = []
    offset = 0
    while True:
        q = supabase.table(table).select(select_fields)
        q = filters_fn(q)
        q = q.range(offset, offset + page_size - 1)
        page = q.execute().data or []
        all_rows.extend(page)
        if len(page) < page_size:
            break
        offset += page_size
    return all_rows


@api_router.get("/school-admin/analytics")
async def get_school_admin_analytics(request: Request, period: int = 30):
    """Rich emotional wellbeing analytics for school admin — no individual student data."""
    user = await get_current_user(request)
    if not user or user.get("role") not in ["school_admin", "admin", "superadmin"]:
        raise HTTPException(status_code=403, detail="School admin access required")
    user_id = user["user_id"]
    days = max(1, min(period, 90))
    start_date = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()

    # Get all teachers in this school — by school_admin_id OR school_name
    school_name = user.get("school_name", "")
    teachers_by_id = supabase.table("users").select("user_id,name,email").eq("school_admin_id", user_id).execute()
    teachers_by_name = supabase.table("users").select("user_id,name,email").eq("school_name", school_name).eq("role", "teacher").execute() if school_name else type('obj', (object,), {'data': []})()
    # Merge and deduplicate
    all_teachers = {t["user_id"]: t for t in (teachers_by_id.data or []) + (teachers_by_name.data or [])}
    teacher_list = list(all_teachers.values())
    teacher_ids = [t["user_id"] for t in teacher_list]

    # Real fix Aug 21: classrooms reassigned to the school_admin directly (e.g. via account-
    # deletion's teacher-reassignment logic - see POST /account/delete-request - or any
    # classroom a school_admin creates themselves) were invisible here, since this only ever
    # looked at classrooms owned by linked teacher_ids. classroom_owner_ids is used ONLY for
    # the classroom/student lookup below - teacher_ids itself must stay teacher-only, since it
    # also drives total_teachers/seats_used/teacher_checkin_rate further down.
    classroom_owner_ids = teacher_ids + [user_id]

    # Get classrooms
    classrooms_res = supabase.table("classrooms").select("*").in_("user_id", classroom_owner_ids).execute()
    classrooms = classrooms_res.data or []
    classroom_ids = [c["id"] for c in classrooms]

    if not teacher_ids and not classrooms:
        return {"total_teachers": 0, "total_students": 0, "total_checkins": 0,
                "zone_distribution": {}, "daily_counts": {}, "classroom_breakdown": [],
                "school_name": school_name or "My School"}

    # Get students. Real fix Aug 14: this queried students by "user_id" in teacher_ids,
    # but students link via classroom_id, not a direct teacher-owned user_id column (same
    # architectural fact already fixed twice elsewhere in this file today). classroom_ids
    # is already correctly computed right above — just wasn't being used here.
    students_res = supabase.table("students").select("*").in_("classroom_id", classroom_ids).execute() if classroom_ids else type('obj', (object,), {'data': []})()
    students = students_res.data or []
    student_ids = [s["id"] for s in students]

    # Get feeling logs
    logs = []
    if student_ids:
        logs = _fetch_all_paginated("feeling_logs", "*", lambda q: q.in_("student_id", student_ids).gte("timestamp", start_date))

    # Aggregate — no individual identifiers returned
    zone_dist = {"blue": 0, "green": 0, "yellow": 0, "red": 0}
    daily_counts = {}
    hourly = {str(h): 0 for h in range(24)}
    strategy_counts = {}

    for log in logs:
        zone = log.get("feeling_colour") or log.get("zone", "blue")
        if zone in zone_dist:
            zone_dist[zone] += 1
        day = (log.get("timestamp") or "")[:10]
        if day:
            daily_counts[day] = daily_counts.get(day, 0) + 1
        try:
            hour = str(int((log.get("timestamp") or "00:00")[-8:-6].strip(":")))
            if hour in hourly:
                hourly[hour] += 1
        except:
            pass
        # Real bug fix Aug 28 (found live-verifying demo-prep item 4): feeling_logs' real
        # column is helpers_selected (see the /checkins insert), not strategies_selected -
        # this loop has always silently counted zero strategies, so strategy_counts/
        # top_strategy_name have never actually reflected real usage on this endpoint.
        for s in (log.get("helpers_selected") or log.get("strategies_selected") or []):
            strategy_counts[s] = strategy_counts.get(s, 0) + 1

    # Classroom breakdown (aggregate only)
    classroom_breakdown = []
    for c in classrooms:
        owner_id = c.get("user_id")
        if owner_id == user_id:
            teacher_name = user.get("name") or "School Admin"
        else:
            teacher = next((t for t in teacher_list if t["user_id"] == owner_id), {})
            teacher_name = teacher.get("name", "Teacher")
        c_students = [s for s in students if s.get("classroom_id") == c["id"]]
        c_logs = [l for l in logs if l.get("student_id") in {s["id"] for s in c_students}]
        c_zones = {"blue": 0, "green": 0, "yellow": 0, "red": 0}
        for l in c_logs:
            z = l.get("feeling_colour") or "blue"
            if z in c_zones:
                c_zones[z] += 1
        classroom_breakdown.append({
            "classroom_name": c.get("name", "Classroom"),
            "teacher_name": teacher_name,
            "student_count": len(c_students),
            "checkin_count": len(c_logs),
            "zone_distribution": c_zones,
        })

    # Real alert stats + resolution speed — uses the SAME student_ids already resolved above,
    # aggregate-only (no student names/identifiers returned), matches the school's real
    # student_alerts data instead of the unrelated teacher-only wellbeing_alerts table
    alert_volume = 0
    alert_zone_dist = {"blue": 0, "green": 0, "yellow": 0, "red": 0}
    alert_context_dist = {"home": 0, "school": 0}
    # Real distinct-student count (not raw check-in count) currently in red — same miscounting
    # bug pattern already fixed for the teacher dashboard earlier this session, applying the
    # same fix here. Aggregate-only: no names, just a number, matching this endpoint's own
    # "no individual student data" rule.
    students_needing_support = len(set(l["student_id"] for l in logs if (l.get("feeling_colour") or l.get("zone")) == "red" and l.get("student_id")))
    resolved_count = 0
    resolution_seconds_total = 0
    resolution_count = 0
    if student_ids:
        alerts_res = supabase.table("student_alerts").select("*").in_("student_id", student_ids).gte("created_at", start_date).execute()
        school_alerts = alerts_res.data or []
        alert_volume = len(school_alerts)
        for a in school_alerts:
            z = a.get("zone") or "yellow"
            if z in alert_zone_dist:
                alert_zone_dist[z] += 1
            ctx = a.get("context") or "school"
            if ctx in alert_context_dist:
                alert_context_dist[ctx] += 1
            if a.get("resolved"):
                resolved_count += 1
                if a.get("resolved_at") and a.get("created_at"):
                    try:
                        created = datetime.fromisoformat(a["created_at"].replace("Z", "+00:00"))
                        resolved = datetime.fromisoformat(a["resolved_at"].replace("Z", "+00:00"))
                        resolution_seconds_total += (resolved - created).total_seconds()
                        resolution_count += 1
                    except Exception:
                        pass
    avg_resolution_hours = round((resolution_seconds_total / resolution_count) / 3600, 1) if resolution_count else None

    # Real teacher adoption — % of this school's teachers who have logged their own wellbeing
    # check-in within the period (teacher_checkins table, same one the teacher-wellbeing PDF uses)
    teachers_checked_in = 0
    if teacher_ids:
        try:
            tc_res = supabase.table("teacher_checkins").select("user_id").in_("user_id", teacher_ids).gte("timestamp", start_date).execute()
            teachers_checked_in = len(set(r["user_id"] for r in (tc_res.data or []) if r.get("user_id")))
        except Exception as e:
            logger.warning(f"[school-admin/analytics] teacher_checkins query failed: {e}")
    teacher_checkin_rate = round((teachers_checked_in / len(teacher_ids)) * 100) if teacher_ids else 0

    # Real feature Aug 28 (demo-prep item 4): the 7-card dashboard stack needed two things
    # this endpoint didn't compute yet - real participation rate (distinct students who
    # actually checked in, not raw check-in count) and a trend vs the immediately-preceding
    # period of equal length, so the app can show a real up/down arrow instead of inventing
    # one. Same student_ids/window length already resolved above - just re-queried one
    # period earlier.
    participating_students = len(set(l["student_id"] for l in logs if l.get("student_id")))
    participation_rate = round((participating_students / len(students)) * 100) if students else 0

    prev_start = (datetime.now(timezone.utc) - timedelta(days=days * 2)).isoformat()
    prev_logs = []
    if student_ids:
        prev_logs = _fetch_all_paginated("feeling_logs", "student_id,feeling_colour", lambda q: q.in_("student_id", student_ids).gte("timestamp", prev_start).lt("timestamp", start_date))
    prev_participating = len(set(l["student_id"] for l in prev_logs if l.get("student_id")))
    prev_participation_rate = round((prev_participating / len(students)) * 100) if students else 0
    prev_students_needing_support = len(set(l["student_id"] for l in prev_logs if (l.get("feeling_colour") or l.get("zone")) == "red" and l.get("student_id")))

    top_strategy_name = None
    if strategy_counts:
        top_id = max(strategy_counts, key=strategy_counts.get)
        top_strategy_name = resolve_strategy_name(top_id)

    return {
        "school_name": user.get("school_name", "My School"),
        "total_teachers": len(teacher_ids),
        "total_classrooms": len(classrooms),
        "total_students": len(students),
        "total_checkins": len(logs),
        "zone_distribution": zone_dist,
        "daily_counts": daily_counts,
        "hourly_distribution": hourly,
        "strategy_counts": strategy_counts,
        "classroom_breakdown": classroom_breakdown,
        "teachers": [{"name": t.get("name",""), "email": t.get("email","")} for t in teacher_list],
        "alert_volume": alert_volume,
        "alert_zone_distribution": alert_zone_dist,
        "alert_context_distribution": alert_context_dist,
        "alerts_resolved": resolved_count,
        "alerts_unresolved": alert_volume - resolved_count,
        "avg_resolution_hours": avg_resolution_hours,
        "teacher_checkin_rate": teacher_checkin_rate,
        "teachers_checked_in": teachers_checked_in,
        "students_needing_support": students_needing_support,
        "participation_rate": participation_rate,
        "participation_rate_prev": prev_participation_rate,
        "students_needing_support_prev": prev_students_needing_support,
        "top_strategy_name": top_strategy_name,
    }

@api_router.get("/school-admin/users")
async def get_school_admin_users(request: Request, limit: int = 200):
    """School admin's own scoped user list - teachers/parents linked via school_admin_id.
    Real fix Aug 21: the portal's "Users at Your School" section called /admin/users, which
    is hardcoded superadmin-only - every school_admin call silently 403'd and the portal's
    own .catch() swallowed it into an empty list. This mirrors /admin/users' shape but scopes
    to the caller's own school instead of returning every user in the system."""
    user = await get_current_user(request)
    if not user or user.get("role") not in ["school_admin", "admin", "superadmin"]:
        raise HTTPException(status_code=403, detail="School admin access required")
    base_fields = ("user_id,email,name,role,subscription_status,subscription_expires_at,"
                   "school_name,school_admin_id,school_country,created_at,language,promo_trial_ends_at,trial_started_at")
    # Real feature Aug 21: teacher_wellbeing_shared_with_admin may not exist yet if the
    # migration hasn't run - try the enriched select first, fall back to the base one.
    try:
        result = supabase.table("users").select(
            base_fields + ",teacher_wellbeing_shared_with_admin"
        ).eq("school_admin_id", user["user_id"]).order("created_at", desc=True).limit(limit).execute()
    except Exception:
        result = supabase.table("users").select(
            base_fields
        ).eq("school_admin_id", user["user_id"]).order("created_at", desc=True).limit(limit).execute()
    return {"users": result.data or [], "total": len(result.data or [])}

@api_router.get("/school-admin/students")
async def get_school_admin_students(request: Request):
    """Real feature Aug 21: school_admin's own scoped student roster (names + classroom),
    built to support real per-student click-through - previously school_admin had no student
    list at all (/school-admin/analytics is deliberately aggregate-only, no names/IDs). Same
    dual-match (school_admin_id OR school_name) + own-directly-owned-classrooms pattern
    already used by /school-admin/analytics and /admin/stats."""
    user = await get_current_user(request)
    if not user or user.get("role") not in ["school_admin", "admin", "superadmin"]:
        raise HTTPException(status_code=403, detail="School admin access required")
    admin_id = user["user_id"]
    school_name = user.get("school_name", "")
    teachers_by_id = supabase.table("users").select("user_id").eq("school_admin_id", admin_id).execute()
    teachers_by_name = supabase.table("users").select("user_id").eq("school_name", school_name).eq("role", "teacher").execute() if school_name else type("o",(object,),{"data":[]})()
    teacher_ids = list({t["user_id"] for t in (teachers_by_id.data or []) + (teachers_by_name.data or [])})
    classroom_owner_ids = teacher_ids + [admin_id]
    classrooms_r = supabase.table("classrooms").select("id,name").in_("user_id", classroom_owner_ids).execute()
    classrooms = classrooms_r.data or []
    classroom_ids = [c["id"] for c in classrooms]
    classroom_names = {c["id"]: c["name"] for c in classrooms}
    if not classroom_ids:
        return []
    students_r = supabase.table("students").select("id,name,classroom_id").in_("classroom_id", classroom_ids).order("name").execute()
    students = students_r.data or []
    for s in students:
        s["classroom_name"] = classroom_names.get(s.get("classroom_id"), "")
    return students

@api_router.get("/school-admin/subscription")
async def get_school_subscription(request: Request):
    """School admin sees their subscription/billing status and seat usage."""
    user = await get_current_user(request)
    if not user or user.get("role") not in ["school_admin", "admin", "superadmin"]:
        raise HTTPException(status_code=403, detail="School admin access required")
    # Dual-match by school_admin_id OR school_name — see /school-admin/stats for why. Matters
    # here specifically because seats_used feeds real billing/seat-limit decisions.
    school_name = user.get("school_name", "")
    teachers_by_id = supabase.table("users").select("user_id,name,email,subscription_status").eq("school_admin_id", user["user_id"]).execute()
    teachers_by_name = supabase.table("users").select("user_id,name,email,subscription_status").eq("school_name", school_name).eq("role", "teacher").execute() if school_name else type("obj", (object,), {"data": []})()
    all_teachers = {t["user_id"]: t for t in (teachers_by_id.data or []) + (teachers_by_name.data or [])}
    teacher_list = list(all_teachers.values())
    sub_status = user.get("subscription_status", "none")
    expires = user.get("subscription_expires_at")
    return {
        "school_name": user.get("school_name", "My School"),
        "subscription_status": sub_status,
        "subscription_expires_at": expires,
        "seats_used": len(teacher_list),
        "teachers": [{"name": t.get("name",""), "email": t.get("email",""), "status": t.get("subscription_status","active")} for t in teacher_list],
        "stripe_customer_id": user.get("stripe_customer_id"),
    }


@api_router.get("/admin/users")
async def get_all_users(request: Request, limit: int = 100, offset: int = 0, role: str = ""):
    """Returns all users for superadmin. Paginated."""
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Superadmin access required")
    base_fields = ("user_id,email,name,role,subscription_status,subscription_expires_at,"
                   "school_name,school_admin_id,school_country,created_at,language,promo_trial_ends_at,trial_started_at")
    try:
        query = supabase.table("users").select(base_fields + ",account_suspended")
        if role:
            query = query.eq("role", role)
        result = query.order("created_at", desc=True).range(offset, offset + limit - 1).execute()
    except Exception:
        # account_suspended migration hasn't run yet - fall back to the base field set.
        query = supabase.table("users").select(base_fields)
        if role:
            query = query.eq("role", role)
        result = query.order("created_at", desc=True).range(offset, offset + limit - 1).execute()
    return {"users": result.data or [], "total": len(result.data or [])}

@api_router.post("/admin/users/{target_user_id}/suspend")
async def suspend_user(target_user_id: str, request: Request):
    """Real feature Aug 27 (item 11): account suspend/reactivate - previously there was no
    lever at all short of full account deletion. Enforced in real time via
    get_current_user()'s account_suspended check (kills an already-active session
    immediately) and at /auth/email-login (clear message on the next login attempt).

    Migration (not run by me, see COH-REVIEW-PLAN.md):
    ALTER TABLE users ADD COLUMN account_suspended boolean DEFAULT false;
    ALTER TABLE users ADD COLUMN suspended_at timestamptz;
    ALTER TABLE users ADD COLUMN suspended_by text;
    ALTER TABLE users ADD COLUMN suspension_reason text;
    """
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Superadmin access required")
    if target_user_id == user["user_id"]:
        raise HTTPException(status_code=400, detail="You can't suspend your own account")
    target_r = supabase.table("users").select("user_id,role").eq("user_id", target_user_id).execute()
    if not target_r.data:
        raise HTTPException(status_code=404, detail="User not found")
    if target_r.data[0].get("role") == "superadmin":
        raise HTTPException(status_code=400, detail="Superadmin accounts can't be suspended here")
    body = {}
    try:
        body = await request.json()
    except Exception:
        pass
    try:
        supabase.table("users").update({
            "account_suspended": True,
            "suspended_at": datetime.now(timezone.utc).isoformat(),
            "suspended_by": user["user_id"],
            "suspension_reason": (body.get("reason") or "").strip() or None,
        }).eq("user_id", target_user_id).execute()
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Could not suspend — has the account_suspended migration run? ({str(e)[:150]})")
    return {"status": "suspended", "user_id": target_user_id}

@api_router.post("/admin/users/{target_user_id}/reactivate")
async def reactivate_user(target_user_id: str, request: Request):
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Superadmin access required")
    try:
        supabase.table("users").update({
            "account_suspended": False,
            "suspended_at": None,
            "suspended_by": None,
            "suspension_reason": None,
        }).eq("user_id", target_user_id).execute()
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Could not reactivate — has the account_suspended migration run? ({str(e)[:150]})")
    return {"status": "reactivated", "user_id": target_user_id}

@api_router.get("/admin/users/checkin-frequency")
async def get_users_checkin_frequency(request: Request):
    """Real feature Aug 27 (item 10): bulk usage-frequency map for the superadmin Users
    list — one call covering every user, not N+1 per card. 'Usage' means something
    different per role, per Jono's call: a teacher's own self check-ins (teacher_checkins,
    same table the Teacher Wellbeing card already uses) vs a parent's LINKED CHILD's
    check-in activity (parent_links -> feeling_logs), since parents never check in
    themselves. school_admin/superadmin/other roles have no defined usage concept here and
    are simply absent from the returned map - the caller should treat a missing user_id as
    "not applicable", not "zero"."""
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Superadmin access required")

    now = datetime.now(timezone.utc)
    since_30d = (now - timedelta(days=30)).isoformat()
    since_14d = (now - timedelta(days=14)).isoformat()
    since_7d = (now - timedelta(days=7)).isoformat()

    def bucket(timestamps: list) -> dict:
        return {
            "count_7d": sum(1 for t in timestamps if t >= since_7d),
            "count_14d": sum(1 for t in timestamps if t >= since_14d),
            "count_30d": sum(1 for t in timestamps if t >= since_30d),
        }

    result = {}

    try:
        tc = supabase.table("teacher_checkins").select("user_id,timestamp").gte("timestamp", since_30d).execute().data or []
        by_teacher = {}
        for row in tc:
            uid = row.get("user_id")
            if uid:
                by_teacher.setdefault(uid, []).append(row.get("timestamp") or "")
        for uid, timestamps in by_teacher.items():
            result[uid] = {**bucket(timestamps), "source": "own_checkins"}
    except Exception as e:
        logger.error(f"checkin-frequency teacher_checkins error: {e}")

    try:
        links = supabase.table("parent_links").select("parent_user_id,student_id").execute().data or []
        parent_to_students = {}
        for l in links:
            pid = l.get("parent_user_id")
            sid = l.get("student_id")
            if pid and sid:
                parent_to_students.setdefault(pid, set()).add(sid)
        all_student_ids = list({sid for sids in parent_to_students.values() for sid in sids})
        student_logs = {}
        if all_student_ids:
            logs = supabase.table("feeling_logs").select("student_id,timestamp").in_("student_id", all_student_ids).gte("timestamp", since_30d).execute().data or []
            for row in logs:
                sid = row.get("student_id")
                if sid:
                    student_logs.setdefault(sid, []).append(row.get("timestamp") or "")
        for pid, sids in parent_to_students.items():
            timestamps = [t for sid in sids for t in student_logs.get(sid, [])]
            result[pid] = {**bucket(timestamps), "source": "linked_child"}
    except Exception as e:
        logger.error(f"checkin-frequency parent_links error: {e}")

    return result

@api_router.get("/admin/dashboard-summary")
async def get_dashboard_summary(request: Request):
    """Rich summary for superadmin dashboard — schools comparison, country breakdown, daily trends."""
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Superadmin access required")

    users = supabase.table("users").select("*").execute().data or []
    students = supabase.table("students").select("id,classroom_id,user_id").execute().data or []
    classrooms = supabase.table("classrooms").select("*").execute().data or []

    from datetime import datetime, timezone, timedelta
    week_ago = (datetime.now(timezone.utc) - timedelta(days=7)).isoformat()
    month_ago = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
    today = datetime.now(timezone.utc).date().isoformat()

    logs_month = supabase.table("feeling_logs").select("*").gte("timestamp", month_ago).execute().data or []
    logs_week = [l for l in logs_month if (l.get("timestamp") or "") >= week_ago]

    # Strategy names lookup
    try:
        strategies_db = supabase.table("admin_teacher_strategies").select("id,name,zone").execute().data or []
        strat_map = {s["id"]: s["name"] for s in strategies_db}
    except:
        strat_map = {}

    # Strategy counts with real names
    strategy_counts = {}
    for log in logs_month:
        for s in (log.get("strategies_selected") or []):
            name = strat_map.get(s) or s  # fallback to ID if no name found
            if name and len(name) > 2:  # skip empty/short IDs
                strategy_counts[name] = strategy_counts.get(name, 0) + 1

    # Zone distribution
    zone_dist = {"blue": 0, "green": 0, "yellow": 0, "red": 0}
    daily_counts = {}
    for log in logs_month:
        z = log.get("feeling_colour") or log.get("zone", "blue")
        if z in zone_dist:
            zone_dist[z] += 1
        day = (log.get("timestamp") or "")[:10]
        if day:
            daily_counts[day] = daily_counts.get(day, 0) + 1

    # Country breakdown
    country_counts = {}
    for u in users:
        c = u.get("school_country") or u.get("language", "en")
        country_counts[c] = country_counts.get(c, 0) + 1

    # School comparison (school admins only)
    school_admins = [u for u in users if u.get("role") == "school_admin"]
    school_comparison = []
    for sa in school_admins:
        sa_id = sa["user_id"]
        sa_teachers = [u for u in users if u.get("school_admin_id") == sa_id]
        sa_teacher_ids = [t["user_id"] for t in sa_teachers]
        sa_students = [s for s in students if s.get("user_id") in sa_teacher_ids]
        sa_student_ids = {s["id"] for s in sa_students}
        sa_logs = [l for l in logs_month if l.get("student_id") in sa_student_ids]
        sa_zones = {"blue": 0, "green": 0, "yellow": 0, "red": 0}
        for l in sa_logs:
            z = l.get("feeling_colour") or "blue"
            if z in sa_zones:
                sa_zones[z] += 1
        school_comparison.append({
            "school_name": sa.get("school_name") or "Unknown School",
            "country": sa.get("school_country") or "—",
            "teacher_count": len(sa_teachers),
            "student_count": len(sa_students),
            "checkin_count": len(sa_logs),
            "zone_distribution": sa_zones,
            "subscription_status": sa.get("subscription_status", "none"),
        })

    # Role breakdown
    role_counts = {}
    for u in users:
        r = u.get("role", "unknown")
        role_counts[r] = role_counts.get(r, 0) + 1

    # Subscription breakdown
    sub_counts = {"active": 0, "trial": 0, "free": 0}
    for u in users:
        s = u.get("subscription_status", "none")
        if s == "active": sub_counts["active"] += 1
        elif s == "trial": sub_counts["trial"] += 1
        else: sub_counts["free"] += 1

    return {
        "total_users": len(users),
        "total_students": len(students),
        "total_classrooms": len(classrooms),
        "total_checkins_month": len(logs_month),
        "total_checkins_week": len(logs_week),
        "zone_distribution": zone_dist,
        "daily_counts": daily_counts,
        "strategy_counts": dict(sorted(strategy_counts.items(), key=lambda x: -x[1])[:10]),
        "country_breakdown": country_counts,
        "school_comparison": school_comparison,
        "role_counts": role_counts,
        "subscription_counts": sub_counts,
    }


@api_router.get("/admin/growth-stats")
async def get_growth_stats(request: Request):
    """Monthly user growth for last 6 months, broken down by role."""
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Superadmin access required")
    users = supabase.table("users").select("role,created_at,subscription_status").execute().data or []
    from datetime import datetime, timezone, timedelta
    now = datetime.now(timezone.utc)
    months = []
    for i in range(5, -1, -1):
        month_start = (now.replace(day=1) - timedelta(days=i*30)).replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        month_end = (month_start + timedelta(days=32)).replace(day=1)
        label = month_start.strftime("%b %Y")
        month_users = [u for u in users if u.get("created_at") and month_start.isoformat() <= u["created_at"] < month_end.isoformat()]
        cumulative = [u for u in users if u.get("created_at") and u["created_at"] < month_end.isoformat()]
        role_counts = {}
        cumulative_counts = {}
        for role in ["teacher","parent","student","school_admin","superadmin"]:
            role_counts[role] = len([u for u in month_users if u.get("role") == role])
            cumulative_counts[role] = len([u for u in cumulative if u.get("role") == role])
        months.append({
            "label": label,
            "new_users": len(month_users),
            "total_users": len(cumulative),
            "role_breakdown": role_counts,
            "cumulative_roles": cumulative_counts,
            "active_subs": len([u for u in cumulative if u.get("subscription_status") == "active"]),
        })
    return {"months": months}

