async def save_teacher_checkin(request: Request):
    """Save teacher self check-in to DB for dashboard visibility."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    try:
        body = await request.json()
        entry = {
            "id": str(uuid.uuid4()),
            "user_id": user["user_id"],
            "zone": body.get("zone", ""),
            "strategies_selected": body.get("strategies_selected", []),
            "notes": body.get("notes"),
            "shared": body.get("shared", False),
            "timestamp": body.get("timestamp") or datetime.now(timezone.utc).isoformat(),
        }
        try:
            supabase.table("teacher_checkins").insert(entry).execute()
        except Exception as e:
            # Table may not exist yet - create it
            logger.error(f"teacher_checkins insert error: {e}")
        return {"status": "saved"}
    except Exception as e:
        logger.error(f"save_teacher_checkin error: {e}")
        return {"status": "error", "detail": str(e)}

@api_router.get("/teacher-checkins")
async def get_teacher_checkins(request: Request, days: int = 7):
    """Get teacher self check-ins for dashboard."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real freemium gate: free tier capped at 30 days of their own wellbeing check-in history
    # (the days parameter was previously fully caller-controlled with zero server-side limit —
    # anyone could bypass an intended UI-level restriction just by requesting a larger range).
    # Real bug fix Aug 28 (technical debt sweep): was `sub_status in ("none","free",None)` -
    # expiry-blind (a lapsed trial/paid account would never hit the cap) and had no
    # school-coverage exemption at all, unlike every other free-tier check in this file.
    # _is_genuinely_free_tier() fixes both.
    if _is_genuinely_free_tier(user) and days > 30:
        days = 30
    try:
        start_date = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
        result = supabase.table("teacher_checkins").select("*").eq("user_id", user["user_id"]).gte("timestamp", start_date).order("timestamp", desc=True).execute()
        return result.data or []
    except Exception as e:
        logger.error(f"get_teacher_checkins error: {e}")
        return []


# ================== TEACHER → LINKED STUDENT ENDPOINTS ==================

@api_router.get("/teacher/student/{student_id}/sharing-status")
async def get_student_sharing_status(student_id: str, request: Request):
    """Check if a student is linked to a parent and sharing status.
    Real fix Aug 26 (item 3): school_sharing_enabled used to be hardcoded True - a UI
    stopgap, not a real toggle (see toggle_school_sharing below for the full story). Now
    reads the real column, defaulting to True (matches prior always-on behaviour) for any
    row from before the migration landed."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    try:
        # Check if any parent is linked to this student
        links = supabase.table("parent_links").select("*").eq("student_id", student_id).execute()
        is_linked = len(links.data or []) > 0
        home_sharing = False
        school_sharing = True
        parent_name = None
        if is_linked and links.data:
            link = links.data[0]
            home_sharing = link.get("home_sharing_enabled", False)
            school_sharing = link.get("school_sharing_enabled", True)
            if school_sharing is None:
                school_sharing = True
            # Get parent name
            try:
                parent = supabase.table("users").select("name,email").eq("user_id", link["parent_user_id"]).execute()
                if parent.data:
                    parent_name = parent.data[0].get("name") or parent.data[0].get("email", "Parent")
            except Exception:
                pass
        return {
            "is_linked_to_parent": is_linked,
            "home_sharing_enabled": home_sharing,
            "school_sharing_enabled": school_sharing,
            "parent_name": parent_name,
            "link_count": len(links.data or []),
        }
    except Exception as e:
        logger.error(f"get_student_sharing_status error: {e}")
        return {"is_linked_to_parent": False, "home_sharing_enabled": False, "school_sharing_enabled": True, "parent_name": None}

@api_router.put("/teacher/student/{student_id}/toggle-school-sharing")
async def toggle_school_sharing(student_id: str, request: Request):
    """Real feature Aug 26 (item 3): "Pause/Resume sharing with parent" was a UI stopgap -
    the button in teacher/student-detail.tsx called a POST /parent-links/school-sharing
    endpoint that never existed on the backend (a silent 404, swallowed by an empty catch),
    and school_sharing_enabled was hardcoded True everywhere it was read - so pressing it
    did nothing at all, ever. Built for real, with the same care as the other
    permission-sensitive toggles tonight:
    - WHO can toggle: the teacher who owns the student's classroom, their covering
      school_admin, or superadmin - the same authorization tier that can already see this
      student's data at all (_is_authorized_for_student), further restricted to staff roles
      only. A linked parent is deliberately NOT allowed to toggle this themselves - this is
      the teacher's/school's own consent for what THEY share outward, the mirror image of
      home_sharing_enabled (which is the parent's own consent for what they share inward).
    - WHAT HAPPENS to already-shared data when paused: nothing is deleted. Pausing only gates
      future reads (see get_school_checkins/get_all_checkins_for_linked_child/
      get_school_strategies_for_linked_child below) - resuming immediately restores full
      visibility of the same untouched history, exactly like home_sharing_enabled already
      works for the reverse direction.
    - Applies to every parent linked to this student, not just the first - a student can
      have more than one active parent_links row (e.g. two guardians)."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    if user.get("role") not in ("teacher", "school_admin", "superadmin"):
        raise HTTPException(status_code=403, detail="Only a teacher or school admin can control school-data sharing.")
    student_r = supabase.table("students").select("*").eq("id", student_id).execute()
    if not student_r.data:
        raise HTTPException(status_code=404, detail="Student not found")
    student_data = student_r.data[0]
    if not await _is_authorized_for_student(user, student_id, student_data):
        raise HTTPException(status_code=403, detail="Not authorized for this student")
    # select("*") deliberately, not naming school_sharing_enabled explicitly - PostgREST
    # errors on a named column that doesn't exist yet (pre-migration), where select("*")
    # degrades gracefully to whatever columns are actually there. Caught live-testing this
    # exact endpoint against the real, not-yet-migrated table - it 500'd instead of the
    # intended 404.
    links = supabase.table("parent_links").select("*").eq("student_id", student_id).execute()
    if not links.data:
        raise HTTPException(status_code=404, detail="No parent linked to this student yet")
    current = links.data[0].get("school_sharing_enabled")
    new_value = not (current if current is not None else True)
    try:
        for link in links.data:
            supabase.table("parent_links").update({"school_sharing_enabled": new_value}).eq("id", link["id"]).execute()
    except Exception as e:
        # Real, expected failure mode until the migration below has actually been run - the
        # column genuinely doesn't exist yet, so writing to it can never succeed regardless of
        # anything this endpoint does. Live-tested against the real, not-yet-migrated table:
        # this used to surface as an opaque 500 "Internal Server Error" with the real reason
        # only visible in Railway logs.
        logger.warning(f"toggle_school_sharing: school_sharing_enabled column not available yet: {e}")
        raise HTTPException(status_code=503, detail="This feature isn't available yet - it needs a database migration that hasn't been run. Contact Jono.")
    return {"school_sharing_enabled": new_value}


@api_router.get("/teacher/student/{student_id}/home-data")
async def get_student_home_data(student_id: str, request: Request, days: int = 30):
    """Get home check-ins and family strategies for a student (teacher view)."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    try:
        # Real fix Aug 26 (security audit): the comment here said "Verify teacher owns this
        # student" but the code below only ever checked the student EXISTS, never who was
        # asking - any authenticated user could pull any student's home check-in history.
        student = supabase.table("students").select("*").eq("id", student_id).execute()
        if not student.data:
            raise HTTPException(status_code=404, detail="Student not found")
        if user.get("role") not in ("teacher", "school_admin", "superadmin"):
            raise HTTPException(status_code=403, detail="Teacher access required")
        if not await _is_authorized_for_student(user, student_id, student.data[0]):
            raise HTTPException(status_code=403, detail="Not authorized for this student")

        start_date = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()

        # Home check-ins - check feeling_logs (logged_by=parent) AND family_zone_logs
        home_logs = supabase.table("feeling_logs").select("*").eq("student_id", student_id).gte("timestamp", start_date).order("timestamp", desc=True).execute()
        all_feeling_logs = home_logs.data or []
        # Filter for home/parent logs
        parent_feeling_logs = [l for l in all_feeling_logs if l.get("logged_by") in ("parent", "family")]
        # Also check family_zone_logs table
        try:
            fam_logs_result = supabase.table("family_zone_logs").select("*").eq("student_id", student_id).gte("timestamp", start_date).order("timestamp", desc=True).execute()
            fam_zone_logs = [{**l, "logged_by": "parent"} for l in (fam_logs_result.data or [])]
        except Exception:
            fam_zone_logs = []
        combined_home = parent_feeling_logs + fam_zone_logs
        # deduplicate by timestamp
        seen = set()
        home_only = []
        for l in combined_home:
            ts = l.get("timestamp","")
            if ts not in seen:
                seen.add(ts)
                home_only.append(l)
        home_only.sort(key=lambda x: x.get("timestamp",""), reverse=True)
        # Create mock result object
        class MockResult:
            def __init__(self, data): self.data = data
        home_logs = MockResult(home_only)

        # Family strategies
        try:
            fam_strats = supabase.table("family_assigned_strategies").select("*").eq("student_id", student_id).eq("share_with_teacher", True).execute()
            family_strategies = fam_strats.data or []
        except Exception:
            family_strategies = []

        home_checkins = [{
            **log,
            "zone": log.get("feeling_colour", log.get("zone", "")),
            "strategies_selected": log.get("helpers_selected", log.get("strategies_selected", [])),
        } for log in (home_logs.data or [])]

        return {
            "sharing_enabled": True,
            "home_checkins": home_checkins,
            "family_strategies": family_strategies,
            "total_home_checkins": len(home_checkins),
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"get_student_home_data error: {e}")
        return {"sharing_enabled": False, "home_checkins": [], "family_strategies": [], "total_home_checkins": 0}


@api_router.get("/teacher/student/{student_id}/combined-checkins")
async def get_student_combined_checkins(student_id: str, request: Request, days: int = 30):
    """Get ALL check-ins for a student — school + home combined."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): had no authorization check at all - any authenticated
    # user could pull any student's full combined school+home check-in history by id. Placed
    # before the try/except below since its bare `except Exception` would otherwise swallow
    # a raised HTTPException into a silent empty list instead of a real 403.
    if user.get("role") not in ("teacher", "school_admin", "superadmin"):
        raise HTTPException(status_code=403, detail="Teacher access required")
    if not await _is_authorized_for_student(user, student_id):
        raise HTTPException(status_code=403, detail="Not authorized for this student")
    try:
        start_date = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
        result = supabase.table("feeling_logs").select("*").eq("student_id", student_id).gte("timestamp", start_date).order("timestamp", desc=True).execute()
        logs = result.data or []
        return [{
            **log,
            "zone": log.get("feeling_colour", log.get("zone", "")),
            "strategies_selected": log.get("helpers_selected", log.get("strategies_selected", [])),
            "source": "home" if log.get("logged_by") == "parent" else "school",
        } for log in logs]
    except Exception as e:
        logger.error(f"get_student_combined_checkins error: {e}")
        return []


@api_router.get("/teacher/student/{student_id}/all-strategies")
async def get_student_all_strategies(student_id: str, request: Request):
    """Get all strategies for a student — school custom + family shared."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    try:
        # School strategies - normalize zone/feeling_colour
        try:
            school = supabase.table("custom_helpers").select("*").eq("student_id", student_id).execute()
            school_strats = []
            for s in (school.data or []):
                normalized = {**s, "source": "school"}
                if not normalized.get("zone"):
                    normalized["zone"] = normalized.get("feeling_colour", "green")
                if not normalized.get("feeling_colour"):
                    normalized["feeling_colour"] = normalized.get("zone", "green")
                school_strats.append(normalized)
        except Exception as e:
            logger.error(f"school strategies fetch error: {e}")
            school_strats = []
        # Family strategies (shared with teacher)
        try:
            family = supabase.table("family_assigned_strategies").select("*").eq("student_id", student_id).eq("share_with_teacher", True).execute()
            family_strats = [{**s, "source": "home", "name": s.get("strategy_name",""), "description": s.get("strategy_description","")} for s in (family.data or [])]
        except Exception:
            family_strats = []
        return {"school_strategies": school_strats, "family_strategies": family_strats}
    except Exception as e:
        logger.error(f"get_student_all_strategies error: {e}")
        return {"school_strategies": [], "family_strategies": []}


@api_router.post("/teacher/student/{student_id}/strategies")
async def add_student_strategy(student_id: str, request: Request):
    """Add a custom strategy for a student at school."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    # Real fix Aug 26 (security audit): had no authorization check on student_id at all -
    # any authenticated user could attach a strategy to any student. Placed before the
    # try/except below since its bare `except Exception` would otherwise mask a raised
    # HTTPException as a 500.
    if user.get("role") not in ("teacher", "school_admin", "superadmin"):
        raise HTTPException(status_code=403, detail="Teacher access required")
    if not await _is_authorized_for_student(user, student_id):
        raise HTTPException(status_code=403, detail="Not authorized for this student")
    try:
        body = await request.json()
        new_strategy = {
            "id": str(uuid.uuid4()),
            "student_id": student_id,
            "user_id": user["user_id"],
            "name": body.get("name", ""),
            "description": body.get("description", ""),
            "feeling_colour": body.get("feeling_colour", body.get("zone", "green")),
            "icon": body.get("icon", "star"),
            "is_shared": body.get("share_with_parent", False),
            "created_at": datetime.now(timezone.utc).isoformat(),
        }
        result = supabase.table("custom_helpers").insert(new_strategy).execute()
        return result.data[0] if result.data else new_strategy
    except Exception as e:
        logger.error(f"add_student_strategy error: {e}")
        raise HTTPException(status_code=500, detail=str(e))


