import stripe as stripe_lib

# Real fix Aug 18: temporary test-mode toggle for verifying the new checkout/webhook flow
# (L2/L3) without touching real money — the only Stripe secret configured before this was a
# LIVE key. When STRIPE_TEST_MODE is on, this deliberately does NOT fall back to the live
# key if the test vars are unset — better to fail closed ("not configured") than silently
# run test-mode intent against live Stripe. Flip STRIPE_TEST_MODE off (or unset it) once the
# test is done; this affects the whole running server, not just one request.
STRIPE_TEST_MODE = os.environ.get("STRIPE_TEST_MODE", "").strip().lower() in ("1", "true", "yes")
if STRIPE_TEST_MODE:
    STRIPE_SECRET_KEY = os.environ.get("STRIPE_SECRET_KEY_TEST", "")
    STRIPE_WEBHOOK_SECRET = os.environ.get("STRIPE_WEBHOOK_SECRET_TEST", "")
else:
    STRIPE_SECRET_KEY = os.environ.get("STRIPE_SECRET_KEY", "")
    STRIPE_WEBHOOK_SECRET = os.environ.get("STRIPE_WEBHOOK_SECRET", "")

if STRIPE_SECRET_KEY:
    stripe_lib.api_key = STRIPE_SECRET_KEY

# Real fix Aug 18: /subscription/checkout (below) needs an actual Stripe Price ID per
# self-serve plan. Kept as env vars rather than hardcoded so Jono can create/rotate the
# underlying Stripe products without a code deploy. Only teacher/parent monthly are
# self-serve today — school plans are sold manually (see the mailto enquiry in the app),
# so no school price IDs are needed here.
# Real fix Aug 25: this always read the plain (live) price vars regardless of
# STRIPE_TEST_MODE, unlike STRIPE_SECRET_KEY/STRIPE_WEBHOOK_SECRET above - flipping test mode
# on made checkout try to use a live-mode price ID against a test-mode key, which Stripe
# correctly rejects ("a similar object exists in live mode, but a test mode key was used").
# Same test/live split as the secret key now applies here too.
if STRIPE_TEST_MODE:
    STRIPE_PRICE_IDS = {
        "teacher_monthly": os.environ.get("STRIPE_PRICE_TEACHER_MONTHLY_TEST", ""),
        "parent_monthly": os.environ.get("STRIPE_PRICE_PARENT_MONTHLY_TEST", ""),
    }
else:
    STRIPE_PRICE_IDS = {
        "teacher_monthly": os.environ.get("STRIPE_PRICE_TEACHER_MONTHLY", ""),
        "parent_monthly": os.environ.get("STRIPE_PRICE_PARENT_MONTHLY", ""),
    }

def _get_plan_from_price(price_id: str) -> str:
    pid = (price_id or "").lower()
    # Real fix Aug 18: school tiers used to fall through to the generic "subscriber" label —
    # no way to tell Starter/Standard/Plus apart post-payment. Matches on the Stripe
    # price nickname/lookup_key Jono names the products with.
    if "school_starter" in pid: return "school_starter"
    if "school_standard" in pid: return "school_standard"
    if "school_plus" in pid: return "school_plus"
    if "parent" in pid: return "parent"
    if "teacher" in pid: return "teacher"
    return "subscriber"

# Real fix Aug 18, found while live-testing L2/L3 against Stripe test mode: the installed
# stripe-python version's StripeObject does NOT implement .get() at all (raises
# AttributeError — confirmed live via Railway logs) — only bracket/index access ([]) works.
# The webhook handler below (and the new /subscription/status/{session_id} endpoint) had
# used .get() throughout since it was first written; every single one of those calls would
# have thrown, meaning this webhook has likely never successfully processed a real Stripe
# event. _sget wraps safe bracket access with the same (key, default) signature as dict.get
# so the fix is a mechanical find-and-replace rather than a rewrite.
def _sget(obj, key, default=None):
    try:
        return obj[key]
    except (KeyError, TypeError, IndexError):
        return default

@api_router.post("/stripe/webhook")
async def stripe_webhook(request: Request):
    if not STRIPE_WEBHOOK_SECRET:
        raise HTTPException(status_code=500, detail="Webhook secret not configured")
    payload = await request.body()
    sig_header = request.headers.get("stripe-signature", "")
    try:
        event = stripe_lib.Webhook.construct_event(payload, sig_header, STRIPE_WEBHOOK_SECRET)
    except stripe_lib.error.SignatureVerificationError:
        raise HTTPException(status_code=400, detail="Invalid webhook signature")
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Webhook error: {str(e)}")

    event_type = event["type"]
    data_obj = event["data"]["object"]

    def _find_user(customer_id: str):
        if not customer_id: return None
        try:
            res = supabase.table("users").select("*").eq("stripe_customer_id", customer_id).execute()
            if res.data: return res.data[0]
            if STRIPE_SECRET_KEY:
                cus = stripe_lib.Customer.retrieve(customer_id)
                email = _sget(cus, "email")
                if email:
                    res2 = supabase.table("users").select("*").eq("email", email).execute()
                    if res2.data:
                        supabase.table("users").update({"stripe_customer_id": customer_id}).eq("user_id", res2.data[0]["user_id"]).execute()
                        return res2.data[0]
        except Exception as e:
            print(f"[Stripe webhook] Error finding user: {e}")
        return None

    if event_type in ("customer.subscription.created", "customer.subscription.updated"):
        customer_id = _sget(data_obj, "customer")
        status = _sget(data_obj, "status")
        items = _sget(_sget(data_obj, "items", {}), "data", [])
        # Real bug fix Aug 26 (found live-testing item 1, cancel-to-free): Stripe's newer API
        # versions moved current_period_end off the subscription object onto each item
        # (items[0].current_period_end) - confirmed live, a real cancel_at_period_end update
        # from this exact account came through with no top-level current_period_end at all.
        # This used to write that missing value straight into subscription_expires_at as
        # NULL on every single subscription.updated event (renewals, cancellations, plan
        # changes) - silently wiping a perfectly good expiry date and breaking Settings'
        # renewal/cancellation-date display. Falls back to the per-item field, and now never
        # overwrites a real value with nothing just because this particular event didn't
        # carry it either way.
        current_period_end = _sget(data_obj, "current_period_end") or (_sget(items[0], "current_period_end") if items else None)
        user = _find_user(customer_id)
        if user:
            sub_status = "active" if status in ("active", "trialing") else ("past_due" if status == "past_due" else "none")
            # Real fix Aug 18: this used to pass only price.id — Stripe auto-generates that
            # as a random string (price_1Abc...), which would never contain "teacher"/
            # "parent"/"school_starter" etc. no matter what Jono names the product. The
            # actual identifying name lives in price.nickname (what Jono sets in the
            # dashboard) or price.lookup_key — check all three so it works regardless of
            # which one ends up set.
            price_obj = _sget(items[0], "price", {}) if items else {}
            price_key = " ".join(filter(None, [_sget(price_obj, "nickname"), _sget(price_obj, "lookup_key"), _sget(price_obj, "id")]))
            plan = _get_plan_from_price(price_key)
            update = {"subscription_status": sub_status, "subscription_plan": plan, "stripe_customer_id": customer_id}
            if current_period_end:
                update["subscription_expires_at"] = datetime.fromtimestamp(current_period_end, tz=timezone.utc).isoformat()
            supabase.table("users").update(update).eq("user_id", user["user_id"]).execute()
            print(f"[Stripe] {event_type}: {user['user_id']} -> {sub_status} ({plan})")

    elif event_type == "customer.subscription.deleted":
        user = _find_user(_sget(data_obj, "customer"))
        if user:
            supabase.table("users").update({"subscription_status": "none", "subscription_expires_at": None}).eq("user_id", user["user_id"]).execute()

    elif event_type == "invoice.payment_succeeded":
        customer_id = _sget(data_obj, "customer")
        user = _find_user(customer_id)
        if user:
            lines = _sget(_sget(data_obj, "lines", {}), "data", [])
            period_end = _sget(_sget(lines[0], "period", {}), "end") if lines else None
            # Real fix Aug 26: same unconditional-null-write bug as the subscription.updated
            # handler above - never overwrite a real subscription_expires_at with nothing
            # just because this event didn't carry a period end.
            update = {"subscription_status": "active"}
            if period_end:
                update["subscription_expires_at"] = datetime.fromtimestamp(period_end, tz=timezone.utc).isoformat()
            supabase.table("users").update(update).eq("user_id", user["user_id"]).execute()

    elif event_type == "invoice.payment_failed":
        user = _find_user(_sget(data_obj, "customer"))
        if user:
            supabase.table("users").update({"subscription_status": "past_due"}).eq("user_id", user["user_id"]).execute()

    return {"status": "ok", "event": event_type}


# ================== ACCOUNT DELETION ==================
# Real feature Aug 20: self-service account deletion, scoped per Jono's decisions -
# required for both Apple and Google Play submission (an app that supports account
# creation must offer in-app deletion, not just an email-to-support path). Soft-delete
# with a 30-day grace period, matching the Privacy Policy's own retention language.
#
# - Teacher: personal data only (login/name/email/push_token). Classrooms/students are
#   reassigned to their linked school_admin immediately at request time (not left
#   orphaned during the grace window) - real students' check-in history and creature
#   progress belongs to the school, not to one teacher's personal account. Blocked with
#   a contact-support message if no school_admin is linked (no safe place to reassign to).
# - Parent: fully self-contained (family_members/family_zone_logs/custom_helpers/
#   family_assigned_strategies/parent_links all key directly to this one parent's own
#   user_id), no blocking condition.
# - School_admin: blocked entirely for now. Closing a school account has real downstream
#   consequences for every linked teacher/parent's free-plan coverage (see
#   _teacher_is_school_covered/_parent_is_school_covered) that this pass deliberately
#   doesn't attempt to handle - real support-assisted process only, per Jono's decision.
#
# Requires this migration to have been run first (this app has no DDL access from code):
#   ALTER TABLE users ADD COLUMN deletion_requested_at timestamptz;

@api_router.post("/account/delete-request")
async def request_account_deletion(request: Request):
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    role = user.get("role")
    if role == "school_admin":
        raise HTTPException(status_code=403, detail="Self-service deletion isn't available for school accounts yet. Please contact jono@classofhappiness.com to close your school's account.")
    if role not in ("teacher", "parent"):
        raise HTTPException(status_code=403, detail="Account deletion is not available for this account type. Please contact jono@classofhappiness.com.")

    body = await request.json()

    # Re-authentication required regardless of how the account normally signs in -
    # this is destructive and eventually irreversible.
    reauthed = False
    if user.get("portal_password"):
        password = body.get("password", "")
        if password and verify_password(password, user["portal_password"]):
            reauthed = True
    google_token = body.get("google_token")
    if not reauthed and google_token:
        try:
            async with httpx.AsyncClient() as client:
                resp = await client.get(
                    "https://www.googleapis.com/oauth2/v3/userinfo",
                    headers={"Authorization": f"Bearer {google_token}"}
                )
                if resp.status_code == 200 and resp.json().get("email", "").strip().lower() == (user.get("email") or "").strip().lower():
                    reauthed = True
        except Exception:
            pass
    if not reauthed:
        raise HTTPException(status_code=403, detail="Re-authentication required — enter your password or sign in with Google again to confirm.")

    if role == "teacher" and not user.get("school_admin_id"):
        raise HTTPException(status_code=400, detail="We can't automatically reassign your classrooms yet — please contact jono@classofhappiness.com to delete this account.")

    # Write the deletion marker FIRST, before any other mutation. Deliberate ordering:
    # this column (deletion_requested_at) requires a migration this app can't run itself
    # (no DDL access from code - see the module comment above). If it's missing, this call
    # fails immediately and nothing else below has happened yet - no partial state where
    # classrooms got reassigned or a subscription got cancelled but the account was never
    # actually marked for deletion.
    supabase.table("users").update({"deletion_requested_at": datetime.now(timezone.utc).isoformat()}).eq("user_id", user["user_id"]).execute()

    if role == "teacher":
        school_admin_id = user["school_admin_id"]
        supabase.table("classrooms").update({"user_id": school_admin_id}).eq("user_id", user["user_id"]).execute()
        supabase.table("students").update({"user_id": school_admin_id}).eq("user_id", user["user_id"]).execute()

    # Cancel any active Stripe subscription now rather than waiting for the purge -
    # nothing else in this app currently cancels a subscription on account closure.
    stripe_customer_id = user.get("stripe_customer_id")
    if stripe_customer_id and STRIPE_SECRET_KEY:
        try:
            subs = stripe_lib.Subscription.list(customer=stripe_customer_id, status="active")
            for sub in _sget(subs, "data", []):
                stripe_lib.Subscription.delete(_sget(sub, "id"))
        except Exception as e:
            logger.warning(f"Could not cancel Stripe subscription during account deletion for {user['user_id']}: {e}")

    # Immediate lockout - revoke every existing session. Future logins are already
    # blocked via deletion_requested_at (see /auth/email-login and /auth/google).
    supabase.table("user_sessions").delete().eq("user_id", user["user_id"]).execute()

    return {"status": "deletion_scheduled", "purge_at": (datetime.now(timezone.utc) + timedelta(days=30)).isoformat()}


@api_router.post("/admin/process-account-deletions")
async def process_account_deletions(request: Request):
    """Call this via a scheduled job (e.g. a daily cron hitting this endpoint) - hard-deletes
    any account whose 30-day grace period from /account/delete-request has elapsed. Only
    parent/teacher accounts can ever have deletion_requested_at set (see above), so this
    never needs to handle school_admin/superadmin cascades."""
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403)
    cutoff = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
    due = supabase.table("users").select("user_id,role").not_.is_("deletion_requested_at", "null").lte("deletion_requested_at", cutoff).execute()
    purged, failed = [], []
    for u in (due.data or []):
        uid = u["user_id"]
        try:
            if u.get("role") == "parent":
                supabase.table("family_zone_logs").delete().eq("user_id", uid).execute()
                supabase.table("family_members").delete().eq("user_id", uid).execute()
                supabase.table("parent_links").delete().eq("parent_user_id", uid).execute()
                supabase.table("custom_helpers").delete().eq("user_id", uid).execute()
                supabase.table("family_assigned_strategies").delete().eq("parent_user_id", uid).execute()
            supabase.table("user_sessions").delete().eq("user_id", uid).execute()
            supabase.table("users").delete().eq("user_id", uid).execute()
            purged.append(uid)
        except Exception as e:
            logger.error(f"Account purge failed for {uid}: {e}")
            failed.append(uid)
    return {"purged": purged, "purged_count": len(purged), "failed": failed}


