@api_router.post("/classrooms/join/{code}")
async def join_classroom_by_code(code: str, request: Request):
    """
    Student joins a classroom using the teacher's join code.
    Called from profile creation — adds student to the classroom.
    Requires student to be authenticated OR uses student_id from body.
    """
    try:
        body = await request.json()
    except:
        body = {}

    classroom_result = supabase.table("classrooms").select("*").eq("join_code", code.upper().strip()).execute()
    if not classroom_result.data:
        raise HTTPException(status_code=404, detail="Invalid class code")
    classroom = classroom_result.data[0]

    student_id = body.get("student_id")
    if not student_id:
        # Try to get from auth
        user = await get_current_user(request)
        if not user:
            raise HTTPException(status_code=400, detail="student_id required")
        student_id = body.get("student_id") or user.get("user_id")

    # Update student's classroom
    supabase.table("students").update({
        "classroom_id": classroom["id"]
    }).eq("id", student_id).execute()

    return {"message": f"Joined {classroom['name']}", "classroom_id": classroom["id"], "classroom_name": classroom["name"]}

@api_router.get("/classrooms/{classroom_id}/join-code")
async def get_classroom_join_code(classroom_id: str, request: Request):
    """Get or generate a join code for a classroom. Teacher only."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    result = supabase.table("classrooms").select("*").eq("id", classroom_id).execute()
    if not result.data:
        raise HTTPException(status_code=404, detail="Classroom not found")
    classroom = result.data[0]
    # Real fix Aug 26 (security audit): docstring already said "Teacher only" but the code
    # never checked role or ownership - any authenticated user could read (and silently
    # generate) any classroom's real join code, which anyone could then use to enrol a
    # student into someone else's classroom.
    if not await _is_authorized_for_classroom(user, classroom_id, classroom):
        raise HTTPException(status_code=403, detail="Not authorized for this classroom")

    # Generate if missing
    if not classroom.get("join_code"):
        import random, string
        code = ''.join(random.choices(string.ascii_uppercase + string.digits, k=6))
        supabase.table("classrooms").update({"join_code": code}).eq("id", classroom_id).execute()
        classroom["join_code"] = code

    return {"join_code": classroom["join_code"], "classroom_name": classroom["name"]}








@api_router.post("/creatures/global-approve/{submission_id}")
async def global_approve_creature(submission_id: str, request: Request):
    """Superadmin's second-stage review — only for submissions teacher/parent already approved.
    Flips is_globally_available so it appears in the World Gallery. Can also reject at this stage
    with a reason, even after teacher/parent approval, as a final safety net."""
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Superadmin access required")

    existing = supabase.table("creature_submissions").select("status").eq("id", submission_id).execute()
    if not existing.data:
        raise HTTPException(status_code=404, detail="Submission not found")
    if existing.data[0].get("status") != "approved":
        raise HTTPException(status_code=400, detail="Only submissions already approved by a teacher or parent can be globally approved")

    body = await request.json()
    action = body.get("action")  # "approve" or "reject"
    # Real fix Aug 18: visibility_scope - who gets to see/unlock this creature.
    # "classroom" = originating classroom only, "school" = whole school, "global" = every school.
    scope = body.get("visibility_scope", "school")
    if scope not in ["classroom", "school", "global"]:
        raise HTTPException(status_code=400, detail="visibility_scope must be classroom, school, or global")
    from datetime import datetime, timezone

    if action == "approve":
        # URGENT real security fix Aug 23 (corrected): global_uses turned out to be a
        # pre-existing popularity counter with a DB-level DEFAULT of 0, not a signal that
        # was ever NULL until this action set it - confirmed live against a truly-fresh,
        # zero-approvals submission (global_uses was 0 from the moment of insert). It could
        # never have worked as an approval gate. superadmin_approved_at is a genuine new
        # column, only ever set here, NULL everywhere else (including old rows) until this
        # action runs. Falls back to the old update if the migration hasn't landed yet, so
        # this endpoint doesn't start hard-failing before then - see COH-REVIEW-PLAN.md for
        # the exact migration SQL Jono needs to run.
        approved_at_iso = datetime.now(timezone.utc).isoformat()
        try:
            supabase.table("creature_submissions").update({
                "is_globally_available": scope == "global",
                "visibility_scope": scope,
                "global_uses": 0,
                "superadmin_approved_at": approved_at_iso,
            }).eq("id", submission_id).execute()
        except Exception as e:
            logger.warning(f"[global_approve_creature] superadmin_approved_at column not available yet, falling back: {e}")
            supabase.table("creature_submissions").update({
                "is_globally_available": scope == "global",
                "visibility_scope": scope,
                "global_uses": 0,
            }).eq("id", submission_id).execute()
        return {"success": True, "is_globally_available": scope == "global", "visibility_scope": scope}
    elif action == "reject":
        supabase.table("creature_submissions").update({
            "status": "rejected",
            "rejection_reason": body.get("reason", "Did not meet global gallery standards"),
            "approved_by": user.get("user_id"),
            "approved_at": datetime.now(timezone.utc).isoformat(),
        }).eq("id", submission_id).execute()
        return {"success": True, "status": "rejected"}
    else:
        raise HTTPException(status_code=400, detail="action must be approve or reject")


@api_router.get("/creatures/awaiting-global-approval")
async def get_awaiting_global_approval(request: Request):
    """Superadmin's queue — creatures already approved by teacher/parent, waiting for the final global check.
    URGENT real bug fix Aug 23: this filtered on is_globally_available==False, which stays
    False forever for any non-global scope (classroom/school/family) regardless of whether
    superadmin has already approved it - is_globally_available only ever means "is this in
    the World Gallery", not "has superadmin reviewed this". Confirmed live: 2 real, already
    superadmin-approved submissions were still showing as "awaiting" here.
    CORRECTED same day: first fix used global_uses as the signal - live-verified false, it
    has a DB default of 0 and was never NULL to begin with (see get_eligible_creatures for
    the full story). superadmin_approved_at is the real, genuine-new-column signal. This
    endpoint is superadmin's own queue, not a student-facing safety gate, so if the
    migration hasn't landed yet this falls back to the old (imperfect but non-crashing)
    is_globally_available filter rather than erroring outright."""
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Superadmin access required")
    try:
        result = supabase.table("creature_submissions").select("*").eq("status", "approved").is_("superadmin_approved_at", "null").execute()
    except Exception:
        result = supabase.table("creature_submissions").select("*").eq("status", "approved").eq("is_globally_available", False).execute()
    # Real feature Aug 23 (item 4): same real-student-name resolution as
    # /creatures/pending and /creatures/my-submissions, so superadmin's final-approval
    # decision isn't made blind to which real child a creature is for either.
    return _annotate_real_student_names(result.data or [])




