@api_router.post("/creatures/upload-image")
async def upload_creature_image(request: Request):
    """Receives a base64 image, uploads to Supabase Storage, returns public URL."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    import base64, uuid
    body = await request.json()
    b64 = body.get("image_base64", "")
    stage = body.get("stage", 1)
    ext = body.get("ext", "jpg")
    if not b64:
        raise HTTPException(status_code=400, detail="No image data")
    img_bytes = base64.b64decode(b64.split(",")[-1])
    filename = f"creatures/{user['user_id']}_stage{stage}_{uuid.uuid4().hex[:8]}.{ext}"
    supabase.storage.from_("creature-images").upload(
        filename, img_bytes,
        {"content-type": f"image/{ext}", "upsert": "true"}
    )
    url = supabase.storage.from_("creature-images").get_public_url(filename)
    return {"url": url, "filename": filename}

import hashlib, secrets

def hash_password(password: str) -> str:
    salt = secrets.token_hex(16)
    hashed = hashlib.sha256((password + salt).encode()).hexdigest()
    return f"{salt}:{hashed}"

def verify_password(password: str, stored: str) -> bool:
    try:
        salt, hashed = stored.split(":")
        return hashlib.sha256((password + salt).encode()).hexdigest() == hashed
    except:
        return False

@api_router.post("/auth/set-password")
async def set_password(request: Request):
    """Allow a logged-in user to set their portal password."""
    user = await get_current_user(request)
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")
    body = await request.json()
    password = body.get("password", "").strip()
    if len(password) < 8:
        raise HTTPException(status_code=400, detail="Password must be at least 8 characters")
    hashed = hash_password(password)
    supabase.table("users").update({"portal_password": hashed}).eq("user_id", user["user_id"]).execute()
    return {"status": "password set successfully"}

@api_router.post("/auth/signup")
async def email_signup(request: Request):
    """Real feature Aug 26 (item 2, follow-up to the A40 access-control fix): a genuine
    email/password signup with an explicit role picker. Before this, plain email/password was
    login-only - /auth/email-login's unrecognized-email path used to silently create an
    account (the exact bug A40 closed), and after that fix there was briefly no email-based
    way to create a real new account at all (Google sign-in remained the only real path). This
    restores email-based signup as its own deliberate, explicit action: a real password is
    required at creation (never optional, unlike the old silent-creation accounts which mostly
    had none - see the force-password-on-login fix), and role is chosen explicitly here, never
    silently derived later (see the A41 fix removing silent updateRole() calls)."""
    body = await request.json()
    email = body.get("email", "").strip().lower()
    password = body.get("password", "")
    name = body.get("name", "").strip()
    role = body.get("role", "").strip().lower()

    if not email or "@" not in email:
        raise HTTPException(status_code=400, detail="Valid email required")
    if len(password) < 8:
        raise HTTPException(status_code=400, detail="Password must be at least 8 characters")
    if not name:
        raise HTTPException(status_code=400, detail="Name required")
    if role not in ("teacher", "parent"):
        raise HTTPException(status_code=400, detail="Please choose whether you're a Teacher or Parent")

    existing = supabase.table("users").select("user_id").eq("email", email).execute()
    if existing.data:
        raise HTTPException(status_code=409, detail="An account with this email already exists. Please sign in instead.")

    user_id = f"user_{uuid.uuid4().hex[:12]}"
    new_user = {
        "user_id": user_id,
        "email": email,
        "name": name,
        "role": role,
        "language": "en",
        "subscription_status": "none",
        "portal_password": hash_password(password),
        "created_at": datetime.now(timezone.utc).isoformat(),
    }
    supabase.table("users").insert(new_user).execute()

    session_token = str(uuid.uuid4())
    supabase.table("user_sessions").insert({
        "session_token": session_token,
        "user_id": user_id,
        "expires_at": (datetime.now(timezone.utc) + timedelta(days=30)).isoformat(),
        "created_at": datetime.now(timezone.utc).isoformat(),
    }).execute()

    return {"user": _public_user(new_user), "session_token": session_token}

import resend

# Real feature Aug 27 (password-reset email delivery): the reset flow (below) generated and
# stored a real token since Aug 26 but had no way to deliver it to the account owner - see
# reset_password_request's docstring for the full history. Resend chosen over SendGrid for
# this volume (password-reset emails only): a single pip install, ~5-line send call, and its
# sandbox mode sends immediately without any domain setup (restricted to the account owner's
# own signup email until a sending domain is verified) - good enough to build and verify
# tonight, upgradeable to arbitrary real users later just by verifying a domain, no code
# change needed. RESEND_FROM_EMAIL defaults to the sandbox sender so this works out of the
# box; set it to a verified-domain address once one exists.
RESEND_API_KEY = os.environ.get("RESEND_API_KEY", "")
RESEND_FROM_EMAIL = os.environ.get("RESEND_FROM_EMAIL", "Class of Happiness <onboarding@resend.dev>")
if RESEND_API_KEY:
    resend.api_key = RESEND_API_KEY

def _send_password_reset_email(email: str, token: str) -> tuple:
    """Returns (sent: bool, detail: str). Never raises - a broken email provider must not
    break the reset-request endpoint itself (same defensive-fallback standard as everything
    else migration/config-dependent in this codebase)."""
    if not RESEND_API_KEY:
        return False, "RESEND_API_KEY not configured"
    try:
        result = resend.Emails.send({
            "from": RESEND_FROM_EMAIL,
            "to": [email],
            "subject": "Reset your Class of Happiness password",
            "html": f"""
                <div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:24px">
                  <h2 style="color:#1A1A2E">Reset your password</h2>
                  <p style="color:#333;font-size:15px">
                    Open the Class of Happiness app, tap <b>Forgot Password</b>, then
                    <b>"I already have a reset code"</b>, and enter this code:
                  </p>
                  <div style="background:#F5F5F5;border-radius:10px;padding:16px;margin:16px 0;
                              font-family:monospace;font-size:14px;word-break:break-all;color:#1A1A2E">
                    {token}
                  </div>
                  <p style="color:#888;font-size:13px">
                    This code expires in 1 hour. If you didn't request this, you can safely ignore this email.
                  </p>
                </div>
            """,
        })
        email_id = result.get("id") if isinstance(result, dict) else getattr(result, "id", None)
        return True, email_id or "sent"
    except Exception as e:
        logger.error(f"[SECURITY] Password reset email send failed for {email}: {e}")
        return False, str(e)[:150]

@api_router.post("/auth/reset-password-request")
async def reset_password_request(request: Request):
    """Real feature Aug 27: now sends a real email via Resend (see _send_password_reset_email
    above) instead of only logging the token - closes the "self-service reset temporarily
    unavailable" gap from Aug 26's security fix. Defensive fallback intact: if RESEND_API_KEY
    isn't configured or the send fails, falls back to the exact Aug 26 behavior (log a
    warning, generic "contact support" message) rather than erroring - this endpoint must
    never break just because email delivery isn't set up yet.

    Security invariant unchanged from Aug 26: the response is IDENTICAL whether or not the
    email exists, and NEVER includes the token - both deliberate, don't leak account
    existence, don't hand out the one secret this flow protects. The token only ever reaches
    the account owner via the email itself now, never via any API response or log line."""
    body = await request.json()
    email = body.get("email", "").strip()
    existing = supabase.table("users").select("user_id,email").eq("email", email).execute()
    if existing.data:
        reset_token = secrets.token_urlsafe(32)
        supabase.table("users").update({
            "reset_token": reset_token,
            "reset_token_expires": (datetime.now(timezone.utc) + timedelta(hours=1)).isoformat()
        }).eq("email", email).execute()
        sent, detail = _send_password_reset_email(email, reset_token)
        if sent:
            logger.info(f"Password reset email sent to {email} (resend id: {detail})")
        else:
            logger.warning(f"[SECURITY] Password reset requested for {email} - token generated but NOT emailed ({detail}). Manual recovery: contact support.")
    return {"status": "If this email exists, we've sent password reset instructions to it. If you don't see it, contact jono@classofhappiness.com."}

@api_router.post("/auth/reset-password")
async def reset_password(request: Request):
    """Consume a reset token generated by /auth/reset-password-request and actually set a new
    password. This endpoint never existed before — the reset flow used to dead-end after
    generating a token, meaning 'forgot password' never actually worked end-to-end."""
    body = await request.json()
    token = body.get("token", "").strip()
    new_password = body.get("new_password", "").strip()
    if not token:
        raise HTTPException(status_code=400, detail="Reset token required")
    if len(new_password) < 8:
        raise HTTPException(status_code=400, detail="Password must be at least 8 characters")
    existing = supabase.table("users").select("user_id,reset_token_expires").eq("reset_token", token).execute()
    if not existing.data:
        raise HTTPException(status_code=400, detail="Invalid or already-used reset token")
    user = existing.data[0]
    expires = user.get("reset_token_expires")
    if expires:
        try:
            expires_dt = datetime.fromisoformat(expires.replace("Z", "+00:00"))
            if expires_dt < datetime.now(timezone.utc):
                raise HTTPException(status_code=400, detail="Reset token has expired")
        except HTTPException:
            raise
        except Exception:
            pass
    hashed = hash_password(new_password)
    supabase.table("users").update({
        "portal_password": hashed,
        "reset_token": None,
        "reset_token_expires": None,
    }).eq("user_id", user["user_id"]).execute()
    return {"status": "password reset successfully"}

@api_router.get("/creatures/analytics")
async def get_creature_analytics(request: Request):
    """Superadmin-only aggregate stats: active featured creatures + expiry,
    most engaging creatures (by global_uses), top users and top schools by
    fully-completed creatures obtained. Real fix Aug 18."""
    user = await get_current_user(request)
    if not user or user.get("role") != "superadmin":
        raise HTTPException(status_code=403, detail="Superadmin access required")

    now = datetime.now(timezone.utc).isoformat()
    featured_r = supabase.table("featured_creatures").select("*, creature_submissions(*)")        .lte("active_from", now).gte("active_until", now).execute()
    featured = featured_r.data or []

    top_creatures_r = supabase.table("creature_submissions").select(
        "id,creature_name,emotion_colour,school_name,country,global_uses,stage4_url"
    ).eq("status", "approved").order("global_uses", desc=True).limit(10).execute()
    top_creatures = top_creatures_r.data or []

    # Real bug fix Aug 28 (systematic sweep, same class as /school-admin/analytics and
    # /admin/stats): unlike featured_creatures (bounded to right-now) and creature_submissions
    # (explicit .limit(10)), this query has no bound at all - every fully-evolved creature
    # ever, platform-wide, for the platform's whole lifetime. Currently 0 rows (confirmed
    # live), so no symptom yet, but it's the identical unpaginated pattern that will silently
    # cap at 1000 the same way once real usage grows - fixed proactively.
    unlocks = _fetch_all_paginated("creature_unlocks", "student_id,creature_id,completed_at", lambda q: q.eq("stages_unlocked", 4))

    user_counts = {}
    for u in unlocks:
        sid = u.get("student_id")
        if sid: user_counts[sid] = user_counts.get(sid, 0) + 1
    top_user_ids = sorted(user_counts.items(), key=lambda x: x[1], reverse=True)[:10]

    # Real fix Aug 23 (item 12): this was one users-table query per unique student with any
    # fully-completed creature - unbounded, scaling with total platform-wide unlocks rather
    # than the top 10 actually returned. Single batched query instead, same result shape.
    all_sids = list(user_counts.keys())
    user_rows = _fetch_all_paginated("users", "user_id,name,school_name", lambda q: q.in_("user_id", all_sids)) if all_sids else []
    user_school_cache = {r["user_id"]: (r.get("name", ""), r.get("school_name", "")) for r in (user_rows or [])}

    top_users = []
    school_counts = {}
    for sid, count in user_counts.items():
        name, school = user_school_cache.get(sid, ("", ""))
        if school:
            school_counts[school] = school_counts.get(school, 0) + count

    for sid, count in top_user_ids:
        name, school = user_school_cache.get(sid, ("", ""))
        top_users.append({"user_id": sid, "name": name or sid, "school_name": school, "count": count})

    top_schools = sorted(school_counts.items(), key=lambda x: x[1], reverse=True)[:10]
    top_schools = [{"school_name": s, "count": c} for s, c in top_schools]

    return {"featured": featured, "top_creatures": top_creatures, "top_users": top_users, "top_schools": top_schools}

